INSERT INTO `gpb_aufgabe` (`id`, `kursid`, `typ`, `titel`, `beschreibung`, `punkte_max`, `sichtbar_ab`, `faellig_am`, `erstellt_von`, `erstellt_am`) VALUES
(1, 1343, 'text_upload', 'Testaufgabe: Kurzreflexion', 'Bitte schreibe zwei Sätze zum heutigen Thema und lade optional eine Datei hoch.', 10.00, NULL, '2026-09-21 13:16:25', 8, '2026-09-14 13:16:25'),
(2, 1343, 'multiple_choice', 'Test-Quiz: Grundlagen', 'Bitte beantworte die folgenden Fragen.', 10.00, NULL, '2026-12-21 14:45:00', 8, '2026-09-14 14:45:34'),
(3, 1343, 'text_upload', 'Java: Klassen und Objekte', 'Schreibe eine Klasse "Buch" mit den Attributen Titel, Autor und Erscheinungsjahr sowie einer Methode, die diese Angaben als Text ausgibt. Lade deinen Quellcode als .java-Datei hoch und beschreibe kurz im Textfeld, wie du vorgegangen bist.', 10.00, '2026-09-16 18:20:00', '2026-09-23 00:00:00', 8, '2026-09-16 18:22:45'),
(4, 1343, 'multiple_choice', 'Klausur - Geschichte', '', 100.00, NULL, '2026-10-29 11:00:00', 8, '2026-10-08 08:10:36');
INSERT INTO `gpb_aufgabe_abgabe` (`id`, `aufgabeid`, `tnid`, `text`, `dateiname`, `gespeicherter_dateiname`, `groesse`, `abgegeben_am`) VALUES
(1, 1, 1586, 'Am enden wurde alles gut.\r\nJetzt kommen noch die MCs...', '46b.jpeg', 'f13c56be3b47ce4a4d78c418042e35e2.jpeg', 51005, '2026-09-14 14:27:04'),
(3, 2, 1586, NULL, NULL, NULL, NULL, '2026-09-14 14:56:11'),
(4, 3, 1586, 'Ich habe die Klasse Buch mit den Attributen titel, autor und erscheinungsjahr angelegt, dazu einen Konstruktor zum Setzen der Werte und eine toString()-Methode, die alle Angaben als Text zusammenfasst.', 'Buch.txt', '2847d7c601f1252ca7ef9a3b39e538c4.txt', 560, '2026-09-16 18:42:50'),
(7, 4, 978, NULL, NULL, NULL, NULL, '2026-10-28 14:20:54'),
(8, 2, 978, NULL, NULL, NULL, NULL, '2026-10-28 14:26:19');
