(1271, '2025-11-13', '07:00:00', '14:30:00', 0.5, 'URLAUB'),
(971, '2025-08-19', '08:15:00', '16:15:00', 1, 'Ökonomisches Prinzip, Produktionsfaktoren, Volkswirtschaftliche Produktionsfaktoren, Betriebswirtschaftliche Produktionsfaktoren'),
(971, '2025-08-20', '08:15:00', '16:15:00', 1, 'Wirtschaftssektoren, Wirtschaftseinheiten, Wirtschaftskreislauf, Erweiterter Wirtschaftskreislauf, Markt und Preise'),
(971, '2025-08-21', '08:15:00', '16:15:00', 1, 'Preistheorie, Preisbildung, Wirtschaftsordnung, Konjunkturphase, Stabilitätsgesetz, Magisches Viereck'),
(971, '2025-08-22', '08:15:00', '13:15:00', 0.5, 'Wiederholung der Woche, Übungen'),
(971, '2025-09-22', '08:15:00', '16:15:00', 1, 'I. Ziele der Unternehmen, Zielsysteme \n1. Planung, Organisation, Koordination, Kontrolle/Controlling (kurz zum Unterschied) \n2. Entscheidungsprozesse \n3. Einführung in die betriebliche Organisation \n3.1. Begriff und Aufgabe \n3.2. Generelle Regelungen, Disposition und Improvisation \n3.3. Grundsätze der Organisation \n3.4. Regelkreis \nII. Aufbauorganisation \n1. Aufgabenanalyse, Kriterien der Aufgabengliederung (Verrichtung, Objekt, Phase, Rang \nund Zweckbeziehung) \n2. Aufgabensynthese, Stellenbildung, Stellenarten, Abteilungsbildung, spezielle Aspekte \nder Stellen- und Abteilungsbildung, Zentralisation und Dezentralisation, Delegation \n3. Stellenbildung, Stellenbeschreibung, Anforderungsprofil, Stellenausschreibung (kurz) \n4. Struktur und Aufgaben der betrieblichen Leitungsebene, Betriebspyramide, \nInstanzenaufbau und Dienstweg \n5. Leitungssysteme, wie Einliniensystem, Mehrliniensystem, Stab-Linien-System, \nMatrixorganisation, Spartenorganisation \n6. Entscheidungssysteme (Direktorial- und Kollegialprinzip) \nIII. Ablauforganisation \n1. Begriff, Ziele und Arten \n2. Funktions-, verrichtungsorientierte Ablauforganisation \n3. Ist-Aufnahme und ihre Methoden, Soll-Vorschläge \n4. Zeitorientierte Ablauforganisation \n5. Raumorientierte Ablauforganisation\nÜbungsaufgabe: „Was ist für Euch eine Organisation im Allgemeinen? '),
(971, '2025-09-23', '08:15:00', '16:15:00', 1, 'IV. Netzplantechnik (DIN 69900)\nV. Führung und Führungsverhalten \n1. Führungsaufgaben \n2. Führungsstile \n3. Führungstechniken \n4. Grundsätze der Mitarbeiterführung\nÜbungsaufgabe Critical Path (Kritischer Pfad => Netzplantechnik!)');
INSERT INTO `gpb_berichtsheft` (`tnid`, `datum`, `beginn`, `ende`, `pausen`, `was`) VALUES
(971, '2025-09-24', '08:15:00', '16:15:00', 1, 'I. Personalplanung und Personalentwicklung \n1. Definition Personal \n2. Aufgaben der Personalwirtschaft \n2.1. Planung und Ermittlung des Personalbedarfs \n2.1.1. Arten und Methoden der Personalbedarfsermittlung \n2.1.1.1. Qualitative Methoden der Personalbedarfsermittlung \n2.1.1.2. Quantitative Methoden der Personalbedarfsermittlung \n2.2. Personalbeschaffung \n2.2.1. Die Stellenbeschreibung \n2.2.2. Personalanforderung \n2.2.3. Formen der Personalbeschaffung \n2.2.4. Personalauswahl \n2.2.4.1. Methoden der Personalauswahl; Biografische \nFragebögen/Lebenslaufanalyse \n2.2.4.1.1. Einstellungsinterview \n2.2.4.1.2. Das Allgemeine Gleichbehandlungsgesetz (AGG) \n2.2.4.1.3. Leistungs- und Intelligenztests \n2.2.4.1.4. Persönlichkeitstests \n2.2.4.1.5. Arbeitsproben und situative Verhalten \n2.2.4.1.6. Assessment Center \n2.2.5. Die Personalentwicklung \n2.2.5.1. Die Personalbildung - Berufsausbildung, Fortbildung, Umschulung \n2.2.5.2. Die Personalförderung \nII. Personalfreisetzung im System Personalwesen \n1. Ansätze zum Abbau von personellen Überkapazitäten \n1.1. Versetzung und Umsetzung \n2. Beendigung bestehender Arbeitsverhältnisse \n2.1. Positive Förderung des freiwilligen Ausscheidens \n2.2. Aufhebungsvertrag \n2.3. Vorzeitiger Ruhestand \n2.4. Outplacement \nÜbungsaufgabe zum Thema Kündigungsschutz!'),
(971, '2025-09-25', '08:15:00', '16:15:00', 1, '3. Beendigung bestehender Arbeitsverhältnisse durch Kündigung \n3.1. Betriebsbedingte Kündigung \n3.2. verhaltensbedingte Kündigung \n3.3. Personenbedingte Kündigung \n4. Umgehung der Arbeitgeberverantwortung \n4.1. Personalleasing und befristete Arbeitsverhältnisse \nIII. Die Personalführung  \n1. Managen und Führen (Wiederholung aus Arbeitsorganisation) \n2. Führungsstile \n2.1. Autoritärer, kooperativer Führungsstil, Laissez-Faire \n3. Führungstechniken \nIV. Personalverwaltung \n1. Aufgaben der Personalverwaltung \n2. Führung der Personalakten \n3. Abschlussarbeiten \n3.1. Arbeitspapiere bei Einstellung und Kündigung \n3.2. Die elektronische Lohnsteuerkarte (ELSTAM) \n3.3. Sozialversicherungsnachweis, Sozialversicherungsausweis \n3.4. Arbeitszeugnis (Erstellung und Codierung) \n3.5. Urlaubsbescheinigung Achtung! \nKlausurvorbereitung'),
(971, '2025-09-29', '08:15:00', '16:15:00', 1, 'Vortrag zur Einführung ins BGB, Rechtsordnung, Abgrenzung öff. vs. privates Recht, Rechtsobjekte, Rechtssubjekte, Rechtsgeschäfte, Rechtsfähigkeit, Geschäftsfähigkeit, Vertragsfreiheit, Zweck von Formvorschriften,\nselbständiges Lösen von Übungsaufgaben und anschließender Besprechung, Wiederholung und Vertiefung mit selbständigem Lösen von Übungsaufgaben und anschließender Besprechung'),
