(710, '2026-01-13', '08:15:00', '14:15:00', 1, '- Rechte an Grundstücken Abt. II (Grunddienstbarkeit, beschränkt persönliche Dienstbarkeit, Nießbrauch, Dauerwohn-/Dauernutzungsrecht, Reallast,, Vorkaufsrecht, Erbbaurecht, Altenteil, Eigentumverschaffungsvormerkung, Verfügungsbeschränkungen des Eigentümers)\n- Grundpfandrechte (Hypothek, Grundschuld, Rentenschuld), Unterschiede zwischen Hypothek und Grundschuld, Brieferteilung, Bestellung\n- Grundbuch (Definition, Aufbau)\n- KGU (Klausurauswertung)'),
(710, '2026-01-12', '08:15:00', '14:15:00', 1, '-Kurze Einführung in Bereich Grundstücksrecht\n- Eigentum (Befugnisse, Beschränkungen, Formen)\n- Gegenstände (nichtkörperliche, körperliche),/ Sachen (bewegliche, unbewegliche) / Rechtsänderungen bei Immobilien (Einigung + Eintragung ins Grundbuch)\n- Grundstücke (natürlich, katastermäßig, rechtlich)\n- Grundstücksgleiche Rechte (Schiffe, Flugzeuge, Erbbaurechte)\n- IL-Aufgaben erteilt'),
(720, '2026-01-13', '08:15:00', '16:00:00', 1, 'aktives Zuhören - Inhalte erfassen\n4-Seiten einer Nachricht Schulz von Thun\nTeamuhr nach Tuckman\nKennzeichen Gruppe / Team\nTeamrollen\nFührungsstile\nNachbereitung des Stoffes\n'),
(720, '2026-01-14', '08:15:00', '16:00:00', 1, 'Anforderungen an Teamleiter\nPräsentationtechniken\nGrundlagen Aufbau eines Vortrages\nErstellen einer Präsentation zum Thema Teambuilding-Event\n\nFertigstellung der Präsentation'),
(1342, '2026-01-15', '08:00:00', '16:30:00', 0.5, 'Rechnungen in Scan Ordner umbenannt .Briefe eingetütet.'),
(1317, '2026-01-14', '09:00:00', '16:30:00', 0.5, 'Vorbereitung von Praktikumsvereinbarungen.\nSprachkurs Tänzer: Vereinbarung Kostenerstattung nach Vorlage anpassen und Seriendruck vorbereiten.\n'),
(1342, '2026-01-06', '08:00:00', '16:30:00', 0.5, 'Ich habe Rechnungen mit Leistungsnachweise eingescannt und dabei den Umgang mit dem Scanner sowie interne Ablagestruktur kennengelernt.\nHabe auch Einblick in Rechnungstellung durch Programm Medifox bekommen.'),
(1342, '2026-01-07', '08:00:00', '16:30:00', 0.5, 'Den Ablauf der Postbearbeitung im Unternehmen kennengelernt. Ich habe Unernehmenspost eingetütet und zum Empfang runtergebracht.\nWeiterhin Dokumente eingescannt und umbenannt habe. Dabei habe ich gelernt, welche Paragrafe dann hier abgerechtet werden.\n'),
(1342, '2026-01-09', '07:30:00', '16:00:00', 0.5, 'Weiterhin SEPA-Lastschriften eigegeben und unvollständige, unkorrekte Lastschriften an der Seite gelegt, das sie zur Korrektur an den Standort weitergeleiten werden müssen.'),
(1342, '2026-01-12', '08:00:00', '16:30:00', 0.5, 'Ich habe vollständige SEPA-Lastschriften in den Ordner Alphabetisch einsortiert. '),
(1270, '2026-01-13', '10:00:00', '19:00:00', 0.5, 'Rechnungen Deutschland & EU, revisionssichere Archivierung besprochen\nOnline-Bestellungen & Versand\nWarenbestellung beim Anbieter\nAktionen für das 1. Halbjahr recherchiert'),
(1270, '2026-01-14', '09:30:00', '19:30:00', 0.5, 'Konkurrenz recherchiert + analysiert, Aktionskalender für wichtige Anlässen erstellt, Aktionen für den Valentinstag ausgearbeitet\nPunkte für Aktionen im 1. Halbjahr: BIOFACH / VIVANESS (Messe) recherchiert\nAnhand Aktionskalender Social Media Ideen erstellt (inkl. Text- und Bildvorschläge)'),
(2907, '2026-01-12', '08:15:00', '15:15:00', 1, 'Einführung in die Thematik. Vorstellung der Teilnehmerinnen und Teilnehmer sowie des Dozenten. Rundgang durch das Haus. Behandlung der "Einführungsmappe": Leitbild der GPB. Unterrichtsabläufe. Regelungen zur Anwesenheit. Prüfungsordnung. Hausordnung. Arbeits- und Brandschutzbelehrung. Regelungen zur Nutzung der EDV-Räume. Datenschutzbestimmungen. Beschwerdemanagement. GPB-Digital-Login-Anleitung. BBB-Anleitung. ');
INSERT INTO `gpb_berichtsheft` (`tnid`, `datum`, `beginn`, `ende`, `pausen`, `was`) VALUES
(2907, '2026-01-13', '08:15:00', '15:15:00', 1, 'Fortführung "Behandlung der Einführungsmappe" (siehe Montag). Einführung in den Bildungsalltag "Fit für den Job". Beantwortung von bisher aufgetauchten Fragen (BQ. SQ. Prüfungabläufe etc., etc.). Grundlagen der Kommunikation.'),
(2907, '2026-01-14', '08:15:00', '15:15:00', 1, 'Fortsetzung "Einführung in die Kommunikation". Eisberg-Prinzip etc.  Vom Problem zum Ziel. Mit Druck richtig umgehen. "Lernen lernen" (also: Lerntypen, Lerntechniken etc.). Schaubilder und Mindmaps. Lernposter.Lernkartei. Lernort. Die Facetten unserer Persönlichkeit (Varianz etc., etc.). Persönlichkeitsmodelle. Profilbildung. Das Sechs-Faktoren-Modell. '),
(2907, '2026-01-15', '08:15:00', '14:15:00', 1, 'Grundlagen des Wissenschaftlichen Arbeitens (z. B. Aufbau einer Hausarbeit, eines Exzerpts, Exposé etc., etc.). Das Erkennen von wissenschaftlich fundierter Fachliteratur. Professionell recherchieren. Quellenarbeit. Checkliste: Wissenschaftliche Arbeiten erstellen. '),
(2907, '2026-01-16', '08:15:00', '13:15:00', 0.5, 'Die gelungene Vorbereitung auf eine Prüfung. Grundlagen der optimalen Präsentation, hier auch Powerpoint-Präsentation. Beantwortung offener Fragen. '),
(1350, '2026-01-15', '09:15:00', '18:30:00', 0.5, 'Kreditorenbuchhaltung: Eigenständige Bearbeitung der Eingangsrechnungen der Buchungskreise 03 IGB und 06 IZW für den Freigabe-Prozess. Meldung von Sonderfällen bei den Teamkolleg*innen. Parallel: Pflege der Kreditorenstammdaten im SAP, insbesondere bezüglich Umsatzsteuer-ID und Steuernummer.\n\nScannen von per Post gelieferten Rechnungen.\n\nNachkontrolle offene Posten am 31.12.2024 anhand einer Liste ausgewählter Kreditoren.\n'),
(1345, '2026-01-15', '08:30:00', '17:00:00', 30, 'Tätigkeiten: Durchführung der Deutschberatung für neue Kursteilnehmende inkl. Antragsaufnahme und Weiterleitung an das BAMF.\n\nLerninhalte: Vertiefung der Kenntnisse in Antragsbearbeitung und Behördenkommunikation mit dem BAMF.'),
(1345, '2026-01-16', '00:00:00', '00:00:00', 0, 'Krankheitsbedingt nicht anwesend.\n'),
(1342, '2026-01-13', '07:30:00', '16:00:00', 0.5, 'Ich habe Email an die Standort verfasst, um fehlende oder unkorrekte SEPA´s zu prüfen/klären.\nDabei habe ich gelernt, wie wichtig eine korrekte Datenbasis für den Zahlungsverkehr ist.'),
(1284, '2026-01-14', '07:55:00', '16:00:00', 0.3, 'Post bearbeiten: Briefe und E-Mails sichten, vorbereiten und ausdrucken.\nAntragsteller/innen im System suchen.\nAuskunft aus dem Berliner Melderegister ausdrucken (Erstantrag).\nAktennummer vergeben, Aktendeckel vorbereiten und beschriften.\nAkten anlegen. \nUnterlagen von Rentner/innen auf Vollständigkeit prüfen.'),
(1284, '2026-01-15', '07:30:00', '15:45:00', 0.3, 'Post bearbeiten: Briefe und E-Mails sichten, vorbereiten und ausdrucken.\nVorgänge von Rentner/innen bearbeiten.\nAkten, die ins Archiv müssen, sortieren, anhängen '),
(1317, '2026-01-15', '08:00:00', '15:30:00', 0.5, 'Unfallanzeige melden, Eintrag Verbandbuch in die digitale Personalakte hochladen.\nSelbstständiges Durchführen von Excel-Übungen.\nBeschäftigung mit Tarifvertrag NV-Bühne.'),
(1249, '2026-01-15', '07:00:00', '16:00:00', 0.5, 'Einarbeitung Empfang, Postbearbeitung, Gutschein erstellen, Ordner Etikette erstellen, Diebstahlerfassungsbogen bearbeitet, Mahnwesen im Datev angeschaut.'),
