(1632, '2026-01-02', '10:00:00', '18:00:00', 0, 'Urlaub'),
(1563, '2026-02-23', '08:15:00', '16:15:00', 1, '8.15-14.15 Präsenzunterricht: Einführung ins Handelsrecht, Rechte und Pflichten von Kaufleuten, Ist-, Kann-, Formkaufmann, Handelsregister (Aufbau, eintragungspflichtige/-fähige Tatsachen, Eintragungswirkungen, Prokura, Handlungsvollmachten\n14.15-15.00 Wiederholung und Vertiefung mit Übungsaufgaben'),
