INSERT INTO `gpb_berichtsheft` (`tnid`, `datum`, `beginn`, `ende`, `pausen`, `was`) VALUES
(1312, '2025-12-16', '09:00:00', '17:00:00', 0.5, 'Im Laufe des Tages überprüfte ich verschiedene Objektunterlagen und pflegte relevante Daten in die Verwaltungsunterlagen ein. Darüber hinaus bereitete ich Unterlagen für anstehende Besichtigungen und Termine vor. Zusätzlich stand ich telefonisch mit Kunden und Dienstleistern in Kontakt.'),
(1312, '2025-12-17', '09:00:00', '17:30:00', 0.5, 'Heute kontrollierte ich eingegangene Rechnungen auf Vollständigkeit und Richtigkeit, kontierte diese und leitete sie an die Buchhaltung weiter. Danach bearbeitete ich laufende Anliegen im Rahmen der Objektverwaltung und kümmerte mich um die Dokumentation offener Vorgänge. Außerdem unterstützte ich bei organisatorischen Bürotätigkeiten.'),
(1312, '2025-12-18', '09:00:00', '17:30:00', 0.5, 'Von 10:00 bis 13:00 Uhr führte ich Telefonate mit Mietern und Eigentümern und bearbeitete deren Rückfragen. Anschließend unterstützte ich bei der Koordination von Reparatur- und Wartungsterminen mit externen Firmen. Darüber hinaus bearbeitete ich verschiedene E-Mails und schriftliche Anliegen.'),
(1312, '2025-12-19', '09:00:00', '17:30:00', 0.5, 'Heute half ich bei der Vorbereitung von Unterlagen für Eigentümerversammlungen und sortierte relevante Dokumente für die weitere Bearbeitung. Zusätzlich bearbeitete ich Anliegen aus dem Tagesgeschäft und kümmerte mich um die Ablage und Strukturierung von Verwaltungsunterlagen. Zum Abschluss des Tages führte ich weitere organisatorische Aufgaben im Büro aus.'),
(1312, '2026-01-05', '09:00:00', '17:30:00', 0.5, 'Heute bearbeitete ich im Zeitraum von 10:00 bis 13:00 Uhr telefonische Anfragen von Mietern, Eigentümern und Interessenten. Anschließend kümmerte ich mich um die Bearbeitung eingegangener E-Mails sowie um allgemeine Aufgaben des Tagesgeschäfts. Zudem unterstützte ich bei der Erstellung und Vorbereitung von Anschreiben an Mieter und Eigentümer.'),
(1312, '2026-01-06', '09:00:00', '17:30:00', 0.5, 'Im Laufe des Tages überprüfte ich verschiedene Objektunterlagen und pflegte relevante Daten in die Verwaltungsunterlagen ein. Darüber hinaus bereitete ich Unterlagen für anstehende Besichtigungen und Termine vor. Zusätzlich stand ich telefonisch mit Kunden und Dienstleistern in Kontakt.'),
