(45, 183, 'material_gut', 3, '', 0, 0),
(45, 183, 'lernklima', 1, '', 0, 0),
(45, 183, 'ausstattung', 2, '', 0, 0),
(33, 183, 'info', 0, 'Besonders in Sachen Wirtschaft halte ich es für äußerst hilfreich mit DozentInnen zu lernen, die vorzeigbare Praxiserfahrung haben. Heydenbluth ist ein solider Dozent mir universitärer Lehrerfahrung, was man seinem Lehrstil anmerkt und auch erfrischend ist, dennoch hatte ich das Gefühl, dass Personen mit weniger Vorerfahrung oder geringerem Kenntnisstand ihm manchmal nicht ganz folgen können - könnte aber auch eine Fehlbeurteilung meinerseits sein.', 1, 0),
(33, 183, 'interessant', 1, '', 0, 0),
(33, 183, 'gegliedert', 2, '', 0, 0),
(33, 183, 'zielorientiert', 2, '', 0, 0),
(33, 183, 'dozent_fachsicher', 1, '', 0, 0),
