(142, 180, 'material_gut', 6, '', 0, 0),
(142, 180, 'lernklima', 3, '', 0, 0),
(142, 180, 'ausstattung', 1, '', 0, 0),
(159, 111, 'info', 0, 'Frau Schulz hat sich sehr viel Zeit genommen mit dem einzeln über ihre Lebensläufe und Bewerbungen zu sprechen und wie man was noch verbessern könnte. Zudem wurden uns sehr viele hilfreiche Lernunterlagen zur Verfügung gestellt. ', 1, 0),
(159, 111, 'interessant', 1, '', 0, 0),
(159, 111, 'gegliedert', 1, '', 0, 0),
