(159, 111, 'ausstattung', 1, '', 0, 0),
(102, 111, 'info', 0, 'Wir mussten uns Videos 3 wochenlagen ansehen die zumal hingen aufgrund von Internet Problemen die uns keinen schritt weitergebracht haben. Ich fand das ganze Modul komplett miserabel, kann nicht behaupten, das ich da irgendetwas gelernt habe. ', 1, 0),
(102, 111, 'interessant', 6, '', 0, 0),
(102, 111, 'gegliedert', 6, '', 0, 0),
