(519, 759, 'lernklima', 5, '', 0, 0),
(519, 759, 'ausstattung', 4, '', 0, 0),
(527, 759, 'info', 0, 'Eigentlich wäre dieser Kurs als individuelle Einzelberatung viel sinnvoller, anstatt die Zeit des Fachunterrichts dafür zu verwenden. Es gibt einfach zu viele Einzelfälle, die die Dozentin gar nicht alle abdecken kann. Gegen Ende der Woche, besonders am Donnerstag und Freitag, entstehen dadurch große Leerlaufzeiten.', 1, 0),
(527, 759, 'interessant', 4, '', 0, 0),
(527, 759, 'gegliedert', 2, '', 0, 0),
