INSERT INTO `gpb_bewertung` (`kursid`, `tnid`, `frage`, `wert`, `feedback`, `anonym`, `stumm`) VALUES
(843, 1117, 'info', 0, 'Der Unterricht war interessant aber ehrlich gesagt hatte die Dozentin einen sehr unangenehmen, unfreundlichen Ton wenn man mal etwas nicht verstanden hat und nachgefragt hat. So dass man nichts mehr fragen wollte. Das hat einem echt den Spaß daran genommen:/', 1, 0),
