(861, 974, 'material_nuetzlich', 6, '', 0, 0),
(861, 974, 'material_gut', 6, '', 0, 0),
(861, 974, 'lernklima', 6, '', 0, 0),
(861, 974, 'ausstattung', 6, '', 0, 0),
(974, 3676, 'info', 0, 'Ich war voll und ganz zufrieden es wurde alles ausführlich erklärt. Der Dozent ist auch intensiv auf Fragen eingegangen voll und ganz das Arbeitsklima war auch angenehm. Alles in einem eine erfolgreiche Woche gewesen. ', 0, 0),
