INSERT INTO `gpb_bewertung` (`kursid`, `tnid`, `frage`, `wert`, `feedback`, `anonym`, `stumm`) VALUES
(1170, 637, 'info', 0, 'Sehr geehrte Schulleitung,\n\nich möchte ein ausdrückliches Lob für das Modul „WiSo Intensiv“ bei Herrn Meyer aussprechen. WiSo ist oft ein trockenes Fach, aber Herr Meyer schafft es durch sein herausragendes Engagement, die Inhalte auch im virtuellen Raum absolut verständlich, praxisnah und lebendig zu vermitteln.\n\nBesonders hervorheben möchte ich:\n\nExzellente Prüfungsvorbereitung: Wir werden punktgenau und sicher auf die Tücken der IHK-Prüfung vorbereitet.\n\nTolle Lernatmosphäre trotz Distanz: Der menschliche Austausch auf Augenhöhe motiviert enorm und tut im Prüfungsstress extrem gut – was gerade im Online-Unterricht absolut nicht selbstverständlich ist.\n\nNachhaltiger Erfolg: Selbst komplexe Rechnungen und Rechtsthemen sitzen am Ende, was viel Selbstbewusstsein für die Prüfung gibt.\n\nEin Online-Unterricht in dieser Qualität ist ein echter Gewinn für uns Auszubildende. Bitte geben Sie dieses Lob unbedingt an Herrn Meyer weiter und behalten Sie dieses Format für zukünftige Jahrgänge genau so bei!', 0, 0),
