INSERT INTO `gpb_bewertung` (`kursid`, `tnid`, `frage`, `wert`, `feedback`, `anonym`, `stumm`) VALUES
(1243, 637, 'info', 0, 'VIELEN LIEBEN DANK HERR MOUTON...\n\nich möchte auf diesem Wege ein kurzes, aber durchweg sehr positives Feedback zu meinem Dozenten Herrn Mouton geben.\n\nDer Unterricht bei ihm ist nicht nur inhaltlich hervorragend strukturiert, sondern zielt auch passgenau auf das Wesentliche ab. Ich bin mit seiner Arbeitsweise und Wissensvermittlung sehr zufrieden.\n\nBesonders hervorheben möchte ich folgende Punkte:\n\nPräzise Prüfungsvorbereitung: Herr Mouton gibt uns extrem wertvolle und strategische Tipps für die IHK-Prüfungen.\nVerständliche Skripte: Komplexe Themenbereiche wie Datenschutz und Datensicherheit bricht er in sehr gut verständliche, klar gegliederte Abschnitte herunter.\n\nMotivation und Klarheit: Er kommuniziert klare Anforderungen und bereitet uns fachlich so gut vor, dass man mit einem sehr sicheren Gefühl in die Prüfungen geht.\n\nDank seiner engagierten Art macht der Unterricht großen Spaß und ist absolut zielführend. Ein großes Lob an ihn und vielen Dank an Sie für diese hervorragende Dozentenwahl!\n\nNochmal insbesondere an Herrn Mouton, aber auch an alle ein großes Dankeschön.\n\nLG', 0, 0),
(1243, 637, 'interessant', 1, '', 0, 0),
(1243, 637, 'gegliedert', 1, '', 0, 0),
(1243, 637, 'zielorientiert', 1, '', 0, 0),
(1243, 637, 'dozent_fachsicher', 1, '', 0, 0),
(1243, 637, 'dozent_klar', 1, '', 0, 0),
