INSERT INTO `gpb_ihkprojektantrag` (`kursid`, `tnid`, `betreuerid`, `ampel`, `bezeichnung`, `bezeichnung_geaendertam`, `beschreibung`, `beschreibung_geaendertam`, `zielsetzung`, `zielsetzung_geaendertam`, `zeitplan`, `zeitplan_geaendertam`, `hinweise`, `hinweise_geaendertam`, `hinweise_geaendertvon`) VALUES
(1018, 226, 189, 'green', 'To-Do-Webanwendung angepasst auf Einfachheit', '2026-02-27 11:14:54', 'Das Projekt umfasst die Entwicklung einer einfachen Webanwendung, bei der die Bedienung dem Prinzip von CRUD (Create, Read, Update, Delete) folgt. Sie soll den Nutzern eine einfache Auffassung von den Aufgaben ermöglichen sowie deren Verwaltung. Die Website soll einen Kalender darstellen, auf dem der jeweilige Monat mit den Tagen und Wochen angezeigt wird. Außerdem soll man auch einen Monatsbericht über die ganzen aufgezeichneten Aufgaben kriegen, wie viele man dokumentiert hat, welche bearbeitet wurden und welche nicht.\n\nTechnologien: \nFrontend: React, Next.js\nBackend: Node.js \nDatenbank: supabase.com\nAPI: REST API \nEchtzeit-Kommunikation: Slack', '2026-02-27 11:15:15', 'Ist-Analyse: Derzeit existieren viele To-Do-Webanwendungen mit den genannten Verwaltungssystemen, die aber auch viele unnötige Bestandteile haben, wie beispielsweise Notizen oder eine übermäßige Auswahl an Personalisierungen. Es lenkt von der eigentlichen Verwaltung ab und ist somit keine Hilfe, sondern ein Verbrauch an Energie.\n\nSoll-Konzept: Es soll eine Webanwendung entwickelt werden, die es ermöglicht, sich einzeln auf die eigentliche Verwaltung zu spezialisieren und möglichst unnötigem Verbrauch an Ressourcen vorzubeugen, indem man sich nur einloggt, um eine bestimmte Aufgabe zu erledigen, und danach wieder ausloggt Dies soll einer größeren Gruppe an Nutzern die Chance bieten, sich der Webanwendung zu bedienen, ohne dass viel verschwendet wird.\n\nZusammenarbeit: Dieses Projekt benötigt eine Zusammenarbeit von Entwicklern, die sich mit dem UI/UX-Design auskennen, speziell auf die heutigen modernen Instrumente wie React und Next.js. Außerdem werden auch Entwickler verlangt, die in der Lage sind, Datenbanken sicher anzubinden, sodass die Funktionalität auch gesichert ist. \n\n\nNutzen des Projektes: Am Ende des Projekts wird eine benutzerfreundliche und simple Webanwendung entstehen, die auch nur eine bestimmte Aufgabe verfolgt und den einzigen Dienst erbringt, ohne Ablenkungen und sinnlose Anwendungen und Ressourcenverschwendung. Die Nutzer werden ihre Aufgaben eintragen mit nur den nötigen Informationen wie Name der Aufgabe, das Datum und die Möglichkeit, diese zu bearbeiten und zu markieren. Das soll die Verwaltung vereinfachen und für ein breites Nutzen sorgen. \n\nKosten- und Qualitätsziele: \nKostenrahmen: 10.000 €\nZeitrahmen: Fertigstellung des Projekts bis zum 13.03.2026\nQualitätsziele: Die Webanwendung soll eine simple und benutzerfreundliche Nutzung für User anbieten und sich streng auf die Verwaltung konzentrieren. Mit regelmäßigen Updates und festem Support für guten Kundenservice und Wartung.', '2026-02-27 11:15:37', '1. Analysephase (15 Stunden)\nFokus: Was muss die App können? (Listen, Prioritäten, Termine)\nKick-off-Meeting mit dem Auftraggeber: Definition der Zielgruppe (Privat vs. Business) – 2 h\nIST-Analyse & Requirements Engineering: Untersuchung bestehender Lösungen (z.B. Todoist, Trello) und Ableitung der Features – 5 h\nErstellung des Lastenhefts/User Stories: Definition der Kernfunktionen (CRUD: Create, Read, Update, Delete) – 8 h\n\n2. Planungsphase (25 Stunden)\nFokus: Das technische Fundament.\nSoll-Konzept & Systemarchitektur: Entscheidung für Tech-Stack (z.B. React/Node.js oder Vue/Firebase) – 8 h\nDatenbankdesign: Planung der Tabellen für User, Tasks, Kategorien und Status –   6 h\nProjektstrukturplan (PSP): Zerlegung in Sprints oder Arbeitspakete – 3 h\nUI/UX Design & Wireframing: Entwurf der Listenansicht und Task-Eingabemaske – 5 h\nKosten- und Ressourcenplan: Kalkulation der Hosting- und Entwicklungskosten – 3 h\n\n3. Entwicklungsphase (40 Stunden)\nFokus: Das „Herzstück“ der Anwendung.\nFrontend-Entwicklung: Dashboard, Aufgabenlisten und Filter (Heute, Geplant, Erledigt) – 10 h\nBackend- und API-Entwicklung: Speichern der Aufgaben, Benutzerauthentifizierung (Login/Register) – 10 h\nTask-Features: Implementierung von Prioritäten, Deadlines und Kategorien/Tags – 8 h\nZusatzfunktionen: Drag-and-Drop-Sortierung und Status-Benachrichtigungen –  4 h\nTesting & Bugfixing: Unit-Tests der Kernlogik und Behebung von UI-Fehlern – 8 h\n\n4. Abschlussphase (24 Stunden)\nFokus: Qualitätssicherung und Übergabe.\nProjektdokumentation: Erstellung des Entwickler-Handbuchs und der API-Doku – 10 h\nEndgültige Abnahmetests: Systemtest (End-to-End) mit dem Auftraggeber – 4 h\nSoll-Ist-Analyse (fachlich & zeitlich): Vergleich der geplanten Features und Stunden mit dem Ergebnis – 4 h\nAbschlusspräsentation: Vorstellung der fertigen Web-App – 4 h\nFazit & Projektabschluss: Lessons Learned und Projektabschlussbericht – 2 h', '2026-02-27 11:16:08', '1. Projektbezeichnung : fügen Sie noch ....  für die Firma X ein\n\nGenehmigt!', '2026-03-02 08:31:58', 'Abdullah Hamidi'),
