INSERT INTO `gpb_intrainmodul` (`id`, `mitisid`, `kurzbezeichnung`, `katalognummer`, `titel`, `anzahlue`, `vollzeit_wochenue`, `preis`, `beschreibung`, `voraussetzungen`, `lernziele`, `lerninhalte`, `nutzen`, `zertifid`) VALUES
(1, 6, '01-100-001', '42', 'Datenschutz und Sicherheit', 40, 0, 263.2, '', 'PC-Bedienung (ggf. 01-070-001 ECDL 1 PC Grundlagen)\n\nOnline-Teilnahme möglich', 'Sie erhalten einen praxisorientierten Einstieg in die Welt der digitalen Sicherheit. \nSie lernen Themen wie z. B. Cybercrime, Hacking oder Cracking kennen und erfahren, wie Sie sich gegen Angriffe aus dem Web effektiv schützen können.\n\nSie beschäftigen  sich mit  Sicherheitsmechanismen und  mit rechtlichen Aspekten des Themas Sicherheit und Datenschutz. \nSie lernen, wie Sie sich sicher im Internet bewegen und Ihre persönlichen Daten schützen,  damit die Anonymität Ihrer Daten jederzeit gewährleistet bleibt.', 'Umgang mit Daten und Sicherheit\nComputerkriminalität\nVerschlüsselung und Passwortschutz\nNetzwerkstrukturen\nSicherheit in Netzwerken\nSchadsoftware\nSchutz vor Viren und Malware\nSicher im Internet arbeiten\nVerantwortungsvoller Umgang mit dem Internet\nSichere Kommunikation im Internet\nDatensicherheitsmanagement', 'Sicherer Schutz der digitalen Daten, der Hardware und der sichere Umgang mit den Internet', 1),
(2, 7, '01-100-002', '41', 'Kommunizieren, Suchen und Finden im Internet', 40, 0, 263.2, '', 'PC-Bedienung (ggf. 01-070-001 ECDL 1 PC Grundlagen)\n\nOnline-Teilnahme möglich', 'Sie lernen, wie Sie im Internet surfen, eine E-Mail-Adresse anlegen, E-Mails versenden und empfangen sowie beantworten. Sie lernen Suchmaschinen zu nutzen, online einzukaufen bzw. Bankgeschäfte abzuwickeln. Soziale Netzwerke nutzen und über das Internet telefonieren erweitert die Nutzung herkömmlicher Kommunikationswege.', 'Einstieg ins Internet\nE-Mails\nSuchmaschinen einsetzen\nOnlineshopping und Onlinebanking\nÜber das Internet telefonieren\nSoziale Netzwerke\nKommunikation über Facebook\nInformationen aus dem Internet nutzen', 'Sicherer Umgang mit dem Internet', 1),
(3, 9, '01-200-001', '134', 'Webauftritte planen und umsetzen', 40, 0, 372.8, '', 'PC-Bedienung (ggf. 01-070-001 ECDL 1 PC Grundlagen)\n\nOnline-Teilnahme möglich', 'Sie erlernen mit diesem Weiterbildungsmodul alles rund um das Planen und Umsetzen einer Webseite.', 'Projektmanagement\nPlanung / Konzeption\nGestaltung\nUsability', 'Professionelle Beratung, Durchführung und Kontrolle von Onlineprojekten\nKompetente Betreuung und Bearbeitung von Webseiten/Internetpräsenzen', 1),
(4, 10, '01-200-002', '147', 'HTML', 40, 0, 372.8, 'HTML Grundlagen erlernen, um HTML 5 besser zu verstehen', 'Grundkenntnisse in der PC Bedienung\n\nOnline-Teilnahme möglich', 'Erstellen einer Website mit HTML', 'Die Websprache HTML kennen lernen \nWebseiten bauen\nOnline gehen\nBilder in Webseiten einfügen\nSeriöses HTML nach dem W3C-Standard\nWie stellen Sie Ihre Seiten ins Web', 'Firmen – und Produktpräsentationen im Internet\nBeratung, Durchführung und Kontrolle von Webprojekten\nBetreuung der firmeneigenen Internetpräsenz\nVeröffentlichen von Webseiten im Firmenintranet', 1),
(5, 11, '01-200-003', '130', 'CSS', 40, 0, 372.8, 'CSS Grundlagen erlernen, um CSS 3 besser zu verstehen', 'Grundlagen HTML\n\nOnline-Teilnahme möglich', 'Erstellen einer Website mit CSS', 'Die Websprache CSS kennen lernen \nErste Schritte mit CSS\nDas Boxmodell\nElemente anordnen\nElemente gestalten', 'Firmen – und Produktpräsentationen im Internet\nBeratung, Durchführung und Kontrolle von Webprojekten\nBetreuung der firmeneigenen Internetpräsenz\nVeröffentlichen von Webseiten im Firmenintranet', 1),
(6, 12, '01-200-004', '133', 'JavaScript', 80, 0, 745.6, 'Für Kunden aus dem Medienbereich', 'PC-Grundbedienung, HTML, CSS', 'Erlernen der Grundlagen des Programmierens dynamischer und interaktiver Webseiten für einen eigenen Internetauftritt mit Hilfe der clientseitigen Skriptsprache JavaScript', 'Grundlegend JavaScript-Anweisungen\nFunktionen, Methoden, Objekte\nSchleifen\nDas Document Object Model\nEreignisse', 'Firmen– und Produktpräsentationen im Internet\nUmgang mit JavaScript-Code\nDen Browser steuern\nSicherheiten von Webseiten im Internet', 1),
(7, 14, '01-200-006', '136', 'Homepage-Erstellung', 120, 0, 1118.4, '', 'Umgang mit PC oder Mac\nKenntnisse in Webdesign-, Layout-, Grafik- und/oder Bildbearbeitungsprogrammen\nMindest-Vorkenntnisse: 01-200-002 HTML, 01-200-003 CSS, 01-200-027 HTML5/CSS3\n\nOnline-Teilnahme möglich', 'Webseiten selbstständig und professionell planen, erstellen und gestalten', 'Konzept einer Webseite\nTechnische Komponenten \nNavigationsstrukturen\nInhaltsseiten erstellen\nEinsatz/Einfügen von Grafiken\nFormatierungen mit CSS', 'Professionelles Erstellen von Präsentationen für das Internet und Intranet', 1),
(8, 904, '03-060-005', '107', 'Xpert Business Finanzwirtschaft', 80, 0, 628.8, 'Die Finanzwirtschaft setzt fundiertes Wissen und gute Kenntnisse voraus, um dem Betrieb Kosten zu ersparen. Die Aufstellung und Beurteilung eines Finanzplanes ist eine unabdingbare Grundlage betriebswirtschaftlicher Entscheidungen. Günstige Geldanlagemöglichkeiten erhält nur, wer den Geld- und Kreditmarkt kennt und ihn beurteilen kann. Bei Kreditaufnahmen ist es unerlässlich, die Möglichkeiten der Kreditbeschaffung zu kennen, sie vergleichen und beurteilen zu können.', 'Dieser Kurs setzt die fachlichen und personalen Kompetenzen voraus, die in „Xpert Business\nFinanzbuchführung (1)“ [03-060-001] vermittelt werden. Um den Kurs erfolgreich absolvieren zu können, ist es erforderlich, dass die Teilnehmenden umfassende Transferleistungen erbringen können sowie über berufliche Erfahrungen im kaufmännischen Bereich verfügen. Dazu zählen auch entsprechende personale Kompetenzen. Sie sollten ihre Lernziele reflektieren, bewerten und auch\nselbstgesteuert verfolgen können.\n\nOnline-Teilnahme möglich\n\nDie Xpert Prüfung muss unter Aufsicht geschrieben werden. Ortsansässige Kunden können die Prüfung an einem GPB Standort ablegen. Nichtortsansässige Kunden müssen sich bei einer VHS ihrer Region selbst anmelden. Ein Lerberater kann dabei unterstützen.', 'Fachwissen auf dem aktuellen Stand;\nUmfang und Grenzen ihres Tätigkeitsgebiets kennen,;\nKenntnisse an Schnittstellen zu angrenzenden Gebieten haben und wissen, wann Fachleute dieser Gebiete erforderlich sind;\nDas Wissen erlangen, dass das Tätigkeitsgebiet z.B. durch rechtliche Änderungen und technologischen Fortschritt häufigen Veränderungen unterliegt und wie entsprechende Weiterbildung erfolgen kann.\nDie Grundlagen und Risiken des Zahlungsverkehrs (Inlandszahlungsverkehr, Auslandszahlungsverkehr) sowie Zahlungsmittel kennen, die vertikalen und horizontalen Finanzierungsregeln unterscheiden, Finanzierungsarten und Instrumente der Finanzplanung, des Cash Managements kennen.\nDie Kreditarten und -sicherheiten sowie Sonderformen der Finanzierung (Leasing/Factoring) kennen und Anlageformen von freier Liquidität erklären können\nDie Arten und Formen des halbbaren Zahlungsverkehrs kennen, die Finanzierungsarten und deren Möglichkeiten anwenden sowie den Gesamtkapitalbedarf ermitteln. \nFinanzierungspläne erarbeiten und auswerten können, unterschiedliche Kreditarten berechnen, vergleichen und beurteilen sowie die Eignung, die Kosten sowie die Liquiditätsvorteile und die Steuervorteile einschätzen und berechnen und Anlageformen von freier Liquidität unterscheiden und berechnen.', 'Inlands- und Auslandszahlungsverkehr, \nFinanz- und Liquiditätsplanung,\nLeasing und Factoring, \nKapitalbeschaffung und Kredite, \nAnlageformen', 'Die Finanzwirtschaft steht vor großen Veränderungen. Als Konsequenz aus der Finanz- und Staatsschuldenkrise gibt es viele neue Regeln, die das Bankensystem zukünftig sicherer und stabiler machen sollen. Hierfür müssen beispielsweise mehr Eigenkapital vorgehalten oder IT-Systeme so weiterentwickelt werden, dass Risiken künftig besser überwacht und schneller gemeldet werden können. Trotzdem wird die Finanzwirtschaft auch in Zukunft ein sehr wichtiger Wirtschaftszweig sein.\nMan kann davon ausgehen, dass die Finanzwirtschaft künftig wieder ausgewogener wachsen wird: Das klassische Kreditgeschäft ist ebenso wichtig wie das Kapitalmarktgeschäft. Darüber hinaus wird sich vieles erst im Wettbewerb zeigen - etwa, ob Kunden bereit sind, für ein gutes Filialnetz höhere Kosten zu bezahlen, oder ob die Direktbanken ihren Marktanteil auch in Zukunft ausbauen können.', 1),
(9, 19, '01-200-011', '137', 'Dreamweaver Teil 1', 40, 0, 372.8, 'Aktuelle Version CC\nEs gibt zur Zeit nur das erste Modul von Dreamweaver.', 'Kenntnisse der Windows- oder Macintosh-Oberfläche\n\nOnline-Teilnahme möglich\nAdobe Creative Cloud Lizenz erfoderlich.', 'Grundlegende Kenntnisse im Umgang mit Dreamweaver zur Erstellung von Webseiten erarbeiten', 'Site-Verwaltung\nHTML-Strukturen\nDas DOM\nCSS-Eigenschaften\nLayouts gestalten\nBilder,Video, Links\nFormulare\nOptimierung für mobile Endgeräte\nWebsites testen', 'Sie können Webseiten erstellen und bearbeiten.', 1),
(10, 23, '01-200-017', '135', 'Webdesign Grundlagen', 80, 0, 745.6, '', '01-200-002 HTML,\n01-200-003 CSS,\n01-200-027 HTML5 / CSS3\n01-210-008 + 009 Photoshop Teil 1 + Teil 2\n\nOnline-Teilnahme möglich', 'Sie eignen sich Grundlagen der Prinzipien professionellen Webdesigns an.', 'Konzeption\nBenutzerfreundlichkeit \nLayout und Komposition\nTypografie\nFarben\nGrafiken und Bilder', 'Anwendung fundierten Wissens bei der Planung und Erstellung von Webauftritten', 1),
(11, 26, '01-202-001', '213', 'Online-Marketing', 40, 0, 279.2, '', 'Betriebswirtschaftliche Grundkenntnisse (03-100-001/002)\nMarketing Grundlagen (03-200-001)\n\nBereitschaft zur umfangreichen Textlektüre\n\nOnline-Teilnahme möglich', 'Methoden und Tools für den Marketing-Erfolg im Internet', 'E-Mail-Marketing, \nOnline-PR, \nNewsletter-Marketing, \nSocial Media, SEO, SEA', 'Stellen im Unternehmen besetzen, die für den Onlineauftritt verantwortlich sind.\nSprung in die Selbständigkeit beispielsweise über einen Onlineshop.', 1),
(12, 32, '01-200-027', '131', 'HTML 5 und CSS 3', 80, 0, 745.6, '', 'Grundkenntnisse in HTML und CSS oder Modul 01-200-002 HTML und Modul 01-200-003 CSS\n\nOnline-Teilnahme möglich', 'standardkonforme  Webseiten bauen', 'Die neuen semantischen Strukturelemente in HTML5 \nHTML5-Formulare\nHTML, Sound und Video\nMit CSS3 Inhalte gestalten\nTools, Zentralisierung, Normalisierung\nDie neuen Selektoren \nFarbverläufe, Schriften\nEffekte, Animationen\nCSS3-Layouts', 'Webentwicklung und Gestaltung interaktiver Inhalte\nFirmen- und Produktpräsentationen im Internet\nBetreuung der firmeneigenen Internetpräsenz\nVeröffentlichen von Webseiten im Firmenintranet', 1),
(13, 34, '01-200-029', '208', 'Wordpress', 40, 0, 279.2, 'Version: Wordpress 6', 'Routinierter Umgang mit Microsoft Windows oder Mac OS\n\nOnline-Teilnahme möglich', 'Websites und Blogs einrichten und pflegen', 'WordPress installieren\ndas Dashboard\nSeiten erstellen und anpassen\nBlogs\nBilder, Audio und Video\nPlugins\nThemes nutzen\nSuchmaschinenoptinierung', 'Sie können Webseiten erstellen und pflegen.\nNutzung für Werbung, Präsentationen, Kommunikation und Marketing.', 1),
(14, 36, '01-205-002', '211', 'Typo3 für Redakteure', 40, 0, 279.2, '', 'Grundlegender Umgang mit PC, Browser und Internet\n\nOnline-Teilnahme möglich', 'Typische Arbeiten eines Redakteurs in einem modernen Web Content Management System erledigen', 'Grundverständnis der Arbeitsweise eines CMS\nKennen lernen des Backends\nSeiten anlegen\nInhaltselemente erstellen, bearbeiten, veröffentlichen\nweitere Backend-Module\nmehrsprachige Websites\neffektives Arbeiten im Backend', 'Gestaltung, Pflege und Verwaltung von Internetauftritten aus Anwendersicht \nBetreuung der firmeneigenen Internetpräsenz\nVeröffentlichen von Webseiten im Firmenintranet', 1),
(15, 37, '01-210-007', '153', 'Photoshop für Fotografen', 80, 0, 745.6, 'Aktuelle Version: CC', 'Photoshop Teil 1 und Teil 2\nVorteilhaft:  Camera Raw Grundlagen\n\nOnline-Teilnahme möglich\nAdobe Creative Cloud Lizenz erfoderlich.', 'Tägliche Retuschearbeiten eines Fotografen kennenlernen', 'Auswahlen und Masken\nKorrekturen und Einstellungsebenen\nFilter\nFarben und Konstraste\nBlendmodi \nSmartobjekte\nHautretusche\ninhaltsbasierte Technologien', 'Digitale Fotografien mit professionellem Werkzeug bearbeiten', 1),
(16, 38, '01-210-008', '147', 'Photoshop Teil 1', 40, 0, 372.8, 'Aktuelle Version: CC\nCS6 auf Wunsch möglich', 'Umgang mit PC oder Mac\n\nOnline-Teilnahme möglich:\nAdobe Creative Cloud Lizenz erfoderlich.', 'Werkzeuge und Techniken der Bildkorrektur kennenlernen', 'Arbeitsoberfläche\nDateiverwaltung\nGrundlagen der Bildbearbeitung und Retusche', 'Grundlegende Bildbearbeitung für Web und Print', 1),
(17, 39, '01-210-009', '148', 'Photoshop Teil 2', 40, 0, 372.8, 'Aktuelle Version: CC\nCS6 auf Wunsch möglich', 'Umgang mit PC oder Mac, Photoshop Grundkenntnisse (01-210-008 \nPhotoshop CC Teil 1)\n\nOnline-Teilnahme möglich:\nAdobe Creative Cloud Lizenz erfoderlich.', 'Werkzeuge und Techniken der Bildkorrektur\nkennenlernen', 'Licht und Schatten\nFarbkorrekturen\n\nRetusche und Montage-Techniken\n\nText', 'Fortgeschrittene Bildbearbeitung für Web und Print', 1),
