INSERT INTO `gpb_intrainpaket` (`id`, `mitisid`, `bereichid`, `kurzbezeichnung`, `bezeichnung`, `beschreibung`, `voraussetzungen`, `lernziele`, `lerninhalte`, `nutzen`, `preisproue`) VALUES
(1, 90, 4, 'M-01-001', 'Grundlagen Webseitenerstellung', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Grundlegende Kenntnisse im Umgang mit dem Computer', '* Fundiertes Wissen in der modernen Webseitenerstellung erlangen\n* Seriöses HTML nach dem W3C-Standard', '* Inhalte mit HTML auszeichnen \n* Formatieren mit CSS – Schriften, Farben, Hyperlinks, Elemente anordnen\n* semantischen Strukturelemente in HTML5 und CSS3-Layouts\n* Bilder, Sound und Videos in Webseiten einfügen\n* Veröffentlichen von Webseiten', 'Sie haben grundlegenden Fähigkeiten Firmen- und Produktpräsentationen auf Internetseiten zu pflegen oder beratend tätig zu sein. Sie können die Durchführung und Kontrolle von Webprojekten und firmeneigener Internetpräsenzen begleiten.', 0),
(2, 47, 4, 'M-01-003', 'Responsive Webdesign', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Grundlegende Kenntnisse im Umgang mit dem Computer', '* Webseiten Erstellen, Bearbeiten und Verwalten mit Dreamweaver \n* Entwerfen und Entwickeln von Webseiten für Desktop- Tablet- und Smartphone-Endgeräten', 'Dreamweaver:\n* Den Arbeitsbereich von Dreamweaver kennenlernen\n* Verschiedene Sites anlegen\n* HTML und CSS, Texte, Bilder sowie Links mit Dreamweaver einfügen\n* CSS-Layouts erstellen\nResponsives Webdesign:\n* Responsives und Adaptives Design\n* Gestaltungsraster für responsive Webseiten \n* Standards für reponsive Bilder\n* Media Queries\n* der Aufbau einer HTML5-Site\n* verschiedene Layoutmodelle\n* Web-Typografie \n* Navigations- und Barrierefreiheit', 'Als Webentwickler können Sie eigenständig anpassungsfähige Webseiten für verschiedene Ausgabegeräte erstellen.', 0),
(3, 53, 2, 'A-02-002', 'MS Office Grundlagen - Word, Excel, Access', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Idealerweise haben Sie einen mittleren Bildungsabschluss oder Berufserfahrung und können einen PC bedienen. Ausnahmen sind in Abstimmung mit dem Kostenträger und der GPB mbH möglich.', 'Sie erlernen die Grundlagen der Bedienung eines Betriebssystems und der ausgewählten MS-Office-Produkte und die sichere Bedienung der jeweiligen Programmoberflächen.', '* Texte eingeben, ändern, speichern, wiederfinden, gestalten und drucken\n* Tabellen anlegen, berechnen, formatieren, speichern, drucken, wiederfinden\n* Datenbanken nutzen durch Erstellen von Tabellen, Abfragen, Formularen und Berichten\n* Spezifisches Kennenlernen der anderen individuell ausgewählten MS-Office-Anwendungen', 'Nach erfolgreichem Abschluss der Weiterbildung meistern Sie die Grundbedienung des Betriebssystems und der Office-Anwendungen MS Word, MS Excel und MS Access. (Die Auswahl der Office-Anwendungen kann auch individuell geändert werden.) Sie verstehen die allgemeine Benutzungsphilosophie anderer Office Produkte.', 0),
(4, 54, 2, 'A-02-003', 'MS Office Aufbauwissen - Word, Excel, Outlook, Powerpoint', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Anwendbare Grundkenntnisse in den ausgewählten Office-Anwendungen, in denen Sie sich Aufbauwissen aneignen wollen.', 'Sie vertiefen Ihr Grundlagenwissen durch tieferen Einstieg in die MS Office-Anwendungen.', '* Spezielle, tiefgreifende Bedienung der einzelnen MS-Office-Produkte\n* Texte gestalten und drucken, Text- und Adressdateien erstellen und zu Serienbriefen verknüpfen. Autotext, Rechtschreibung-und Grammatikprüfung, Dokumentvorlagen nutzen (Word)\n* Effektives Arbeiten mit Mappen und großen Tabellen, Arbeiten mit Diagrammen, Erstellen von Pivot-Tabellen (Excel)\n* Planen von Präsentationen, Einbindung verschiedener Folienelemente, Steuerung von Bildschirmpräsentationen, Übergänge und Animationseffekte, Erstellung und Verwendung eigener Vorlagen und Master (Powerpoint)\n* Mails, Termingestaltung, effektives Arbeiten mit dem Kalender, Besprechungen organisieren (Outlook)\n* Nutzung der Hilfe-Funktion in den einzelnen Anwendungen', 'Der sichere Umgang mit dem Betriebssystem und den Office-Anwendungen. Sie sind tiefer in die Anwendungen eingearbeitet, können z. B. Serienbriefe schreiben oder auch Diagramme aus Tabellen erstellen.', 0),
(5, 55, 2, 'A-02-004', 'MS Office Aufbauwissen - Word, Excel, Access', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Anwendbare Grundkenntnisse in den ausgewählten Office-Anwendungen, in denen Sie sich Aufbauwissen aneignen wollen.', 'Sie vertiefen Ihr Grundlagenwissen durch tieferen Einstieg in die MS Office-Anwendungen.', '* Spezielle, tiefgreifende Bedienung der einzelnen MS-Office-Produkte\n* Texte gestalten und drucken, Text- und Adressdateien erstellen und zu Serienbriefen verknüpfen. Autotext, Rechtschreibung-und Grammatikprüfung, Dokumentvorlagen nutzen (Word) \n* Nutzung von Formatvorlagen zur effektiven Gestaltung großer Dokumentationen (Word)\n* Effektives Arbeiten mit Mappen und großen Tabellen, Arbeiten mit Diagrammen, Erstellen von Pivot-Tabellen (Excel)\n* Das Anlegen von Tabellen in Datenbanken , Herstellen von Beziehungen und Definieren von Abfragen (Access)', 'Der sichere Umgang mit dem Betriebssystem und den Office-Anwendungen. Sie sind tiefer in die Anwendungen eingearbeitet, können z. B. Serienbriefe schreiben, gegliederte Dokumentationen aufbereiten, Dokumentvorlagen erstellen und nutzen oder auch Diagramme aus Tabellen erstellen. Datenbanken können Sie strukturell entwickeln und die enthaltenen Daten aufbereiten.', 0),
(6, 56, 2, 'A-02-005', 'MS Office Anwender - Word, Excel, Access, Powerpoint', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Anwendbare Grundkenntnisse in den ausgewählten Office-Anwendungen, in denen Sie sich Aufbauwissen aneignen wollen.', 'In den ausgewählten Office-Anwendungen lösen Sie eigene Aufgaben.', 'Sie bearbeiten individuelle Themen im Bereich Aufbauwissen, in den Office-Anwendungen (Word,Excel, Access, Powerpoint), welche für Ihre Berufpraxis relevant sind.', 'Der sichere Umgang mit dem Betriebssystem und den Office-Anwendungen. Sie haben sich auf die Lösung ganz individueller berufsbezogener Aufgaben vorbereitet.', 0),
(7, 59, 2, 'A-03-001', 'Computer Grundlagen - Office und Internet', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Grundkenntnisse in der PC-Bedienung', 'Sicherheit im Umgang mit dem Computer und den MS Office-Standardanwendungen.', '* Computer-Grundlagen\n* Grundlagen MS Word\n* Grundlagen MS Excel\n* Grundlagen MS Outlook\n* Datenschutz und Sicherheit\n* Kommunizieren, Suchen und Finden im Internet\n* Mit MS Word Bewerbungsunterlagen erstellen', 'Sie kommen in jeder Tätigkeit und in allen Branchen mit der grundlegenden Bedienung des Computers zurecht. Neben den allgemeinen Kenntnissen in der Computerbedienung können Sie mit den jeweiligen Programmen Texte schreiben und bearbeiten, Tabellen berechnen, Mails schreiben und den Kalender führen. Sie surfen sicher und gekonnt im Imternet und kennen sich mit Datenschutz aus.', 0),
(8, 60, 1, 'A-04-001', 'Kaufmännische Grundlagen und PC-Nutzung für Einsteiger', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Grundkenntnisse in der PC-Bedienung', 'Kaufmännische Aufgaben lösen können, den PC und das Internet nutzen und sich auf den Einstieg bzw. Wiedereinstieg in das Berufsleben vorbereiten.', '* Kaufmännisches Rechnen\n* Computer-Grundlagen\n* Erstellung von Bewerbungsunterlagen\n* Nutzung des Internets', 'Sie beherrschen die Grundlagen im Umgang mit dem Computer und können im Internet effektiv recherchieren. Sie verfügen über gute Kenntnisse im kaufmännischen Rechnen und erstellen mit Unterstützung des Personal-Coachs ansprechende Bewerbungsunterlagen.', 0),
(9, 62, 1, 'A-04-002', 'Kaufmännische Assistenz', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Allgemeine Kenntnisse im Umgang mit dem Computer', 'Ein sicherer Umgang mit dem Computer und den Office-Anwendungen. DIN-gerechtes und schnelles schreiben des anfallenden Schriftverkehrs. Grundkenntnissen zum Thema Datenschutz und des Arbeitsrecht.', '* MS Word einschließlich Geschäfts- und Serienbriefe\n* MS Excel, Grund und Aufbauwissen\n* MS Outlook, Grund und Aufbauwissen\n* MS PowerPoint Grund und Aufbauwissen\n* Datenschutz und Sicherheit\n* Tastschreiben\n* Arbeitsrecht, Tarifrecht\n* Kaufmännischer Schriftverkehr DIN 5008', 'Sie können mit tiefgreifenden MS Office-Kenntnissen aufwarten. Als Assistent des Vorgesetzten bzw. als eigenverantwortlicher Mitarbeiter ist es Ihnen möglich die darzustellenden Aufgaben und Ergebnisse anschaulich zu präsentieren, Schriftstücke entsprechend der DIN zu schreiben und das im 10-Finger-Tastschreiben. Sie achten auf den Datenschutz und können Tipps zu arbeitsrechtlichen Fragen geben.', 0),
(10, 63, 1, 'A-04-003', 'Kaufmännische Führungskraft', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Grundlegende Kenntnisse im Umgang mit dem Computer und den MS Office-Anwendungen.', 'Kenntnisse und Fähigkeiten erlangen, um ein Team im kaufmännischen Bereich zu führen.', '* Aufbauwissen in MS Word, MS Excel, MS PowerPoint und MS Outlook. \n* Cloud Computing - Präsentieren mit Prezi\n* Büroorganisation und -führung\n* Bürowirtschaft\n* Arbeitsrecht, Tarifrecht\n* Sozialrecht\n* BGB, Vertragsrecht\n* HGB, Kaufleute, Unternehmensformen\n* Grundlagen Reisekostenabrechnung', 'Sie haben nach dem Lehrgang tiefgreifendes anwendungsbereites MS Office-Wissen und können betriebliche Aufgaben und Ergebnisse anschaulich präsentieren. In den Gebieten Bürowirtschaft, Büroorganisation und –führung, Arbeits- und Sozialrecht und allgemeinen rechtlichen Grundlagen verfügen Sie über das für Führungskraft nötige Wissen, um Ihr Team zu führen.', 0),
(11, 64, 1, 'A-04-004', 'Betriebswirtschaftliches Kontroll- und Rechnungswesen', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Ein sicherer Umgang mit dem Computer und gute kaufmännisch mathematische Kenntnisse (kaufmännisches Rechnen) werden vorausgesetzt.', 'Erarbeitung der Kenntnisse, die im betrieblichen Kontrollwesen notwendig sind.', '* Grundlagen der Betriebswirtschaftslehre\n* Grundlagen der Buchführung\n* Kosten- und Leistungsrechnung\n* Aufbaumodul MS Excel\n* Excel für Fibu und KLR\n* BWL Finanzierung\n* BWL Controlling\n* BWL Excel für Controlling\n* Excel für betriebswirtschaftliche Prozesse', 'In dieser Weiterbildung bekommen Sie Einblicke in die grundlegenden betriebswirtschaftlichen Abläufe. In den Bereichen Buchführung, Kosten- und Leistungsrechnung, Finanzierung und Controlling erlangen Sie fundierte Kenntnisse.', 0),
(12, 65, 1, 'A-04-005', 'Betriebswirtschaftliches Personalwesen/Personalbuchhaltung', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Allgemeine Kenntnisse im Umgang mit dem Computer, sowie Grundlagen im kaufmännischen Rechnen werden vorausgesetzt. Kenntnisse in der Finanzbuchhaltung sind von Vorteil.', 'Prozesse in der Personalwirtschaft , der Personalbuchhaltung, der Reisekostenabrechnung und der Einnahmen-Überschuss-Rechnung erlernen. Praktische Arbeit in den Anwendungen Lexware und Datev.', '* Personalwirtschaft\n* Grundlagen Personalbuchhaltung\n* Grundlagen Reisekostenabrechnung\n* Lexware Lohn und Gehalt\n* DATEV Lohn & Gehalt', 'Sie legen mit den Kenntnissen in der Personalwirtschaft und der manuellen Lohn- und Gehaltsrechnung den Grundstein für die Nutzung der kaufmännischen Lohn- und Gehaltssoftware. Mit den Lohn- und Gehaltsbuchungen in Lexware und DATEV können Sie mit den marktführenden Anwendungen sicher arbeiten. In den Themen Reisekostenabrechnung und Einnahmen-Überschuss-Rechnung sind Sie auf dem neusten Stand.', 0),
(13, 66, 1, 'A-04-006', 'Betriebswirtschaftliches Rechnungswesen', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Allgemeine Kenntnisse im Umgang mit dem Computer, sowie Grundlagen im kaufmännischen Rechnen werden vorausgesetzt.', '* Erlernen der theoretischen Grundlagen der Finanzbuchhaltung\n* Anwendung in den Buchhaltungsprogrammen Lexware und DATEV \n* Aneignung von gesetzlichen Grundlagen für den Einstieg in die EÜR\n* Erarbeitung von Kenntnissen zur Aufzeichnungs- und Erfassungspflicht von Geschäftsvorfällen\n* Erarbeitung aussagekräftiger Bewerbungsunterlagen', '* Grundlagen der Buchführung\n* Lexware Grundlagen Buchhalter\n* DATEV Rechnungswesen mit DATEV Pro\n* DATEV Rechnungswesen Anwendungstraining\n* Einnahme-Überschuss-Rechnung\n* MS Word mit Erstellung von Bewerbungsunterlagen', 'Um Unternehmensprozesse wirtschaftlich zu steuern, sind fundamentale Kenntnisse aus dem betrieblichen Rechnungswesen notwendig. Einerseits dient es dem Unternehmer den Erfolg seines Unternehmens zu ermitteln, anderseits ist es die Grundlage zur Ermittlung der Steuern. Sie haben sicheres Wissen zu aktuellen handelsrechtlichen und steuerrechtlichen Themen, die die Einnahmen-Überschuss-Rechnung (EÜR) tangieren.', 0),
(14, 67, 1, 'A-05-001', 'Lexware-Anwender', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Allgemeine Kenntnisse im Umgang mit dem Computer, sowie Grundlagen im kaufmännischen Rechnen werden vorausgesetzt.', 'Aneignung von Grundkenntnissen in der Finanz- und der Personalbuchhaltung als Grundlage für aufbauende Themen in den Lexwareanwendungen Buchhaltung, Lohn und Gehalt sowie Warenwirtschaft.', '* Grundlagen der Buchführung\n* Grundlagen Personalbuchhaltung\n* Lexware Grundlagen Buchhalter\n* Lexware Faktura/Auftrag/Warenwirtschaft\n* Lexware Lohn und Gehalt\n* Lexware Anwendungstraining BH + LuG + WW', 'Um Unternehmensprozesse wirtschaftlich zu steuern, sind fundamentale Kenntnisse aus dem betrieblichen Rechnungswesen notwendig. Sie können in kleinen und mittleren Unternehmen im Bereich Finanzbuchhaltung, im Bereich Lohnbuchhaltung und in der Warenwirtschaft die Aufgaben mit der Lexware-Anwendersoftware erledigen.', 0),
(15, 68, 1, 'A-05-002', 'DATEV-Anwender', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Allgemeine Kenntnisse im Umgang mit dem Computer, sowie Grundlagen im kaufmännischen Rechnen werden vorausgesetzt.', 'Aneignung von Grundkenntnissen in der Finanz- und der Personalbuchhaltung als Grundlage für aufbauende Themen in den DATEV-Anwendungen Buchführung, Rechnungswesen, Lohn und Gehalt.', '* Grundlagen der Buchführung\n* Grundlagen Personalbuchhaltung\n* DATEV Rechnungswesen mit DATEV Pro\n* DATEV Rechnungswesen Anwendungstraining\n* DATEV Lohn & Gehalt', 'Um Unternehmensprozesse wirtschaftlich zu steuern, sind fundamentale Kenntnisse aus dem betrieblichen Rechnungswesen notwendig. Sie können in kleinen und mittleren Unternehmen im Bereich Finanzbuchhaltung und Lohnbuchhaltung die Aufgaben mit der DATEV-Anwendersoftware erledigen.', 0),
(16, 73, 1, 'A-06-001', 'EBC*L Europäischer Wirtschaftführerschein - Stufe A', 'Prüfung: ext. Zertifizierung + interne Prüfung\nAbschluß: Trägerzertifikat und Herstellerzertifikat EBC*L (Europäischer Wirtschaftsführerschein)', 'Allgemeine Kenntnisse im Umgang mit dem Computer und im kaufmännischen Rechnen.', 'Erlernen der wichtigsten betriebswirtschaftlichen Kenntnisse und Vorbereitung auf die EBC*L-Prüfung.', '* EBC*L A - Bilanzierung\n* EBC*L A - Unternehmensziele und Kennzahlen\n* EBC*L A - Kostenrechnung\n* EBC*L A - Wirtschaftsrecht\n* EBC*L A - Prüfungsvorbereitung', 'Mit dem Europäischen Wirtschaftsführerschein (EBC*L) weisen Sie ein nach einheitlichem Standard zertifiziertes betriebswirtschaftliches Basiswissen nach. »Nicht-Betriebswirte« bekommen die Gelegenheit, betriebswirtschaftliches Basiswissen mit einem in verschiedenen Ländern Europas anerkannten Zertifikat bestätigt zu bekommen.', 0),
(17, 74, 1, 'A-06-002', 'Vorbereitung kaufmännische Zertifizierung Fibu', 'entweder mit Lexware XOR Datev. Bitte ein Modul aus dem Angebot eliminieren, damit die Paketdauer stimmig ist', 'Allgemeine Kenntnisse im Umgang mit dem Computer', '', '', '', 0),
(18, 78, 1, 'A-04-007', 'Betriebswirtschaftliche Grundlagen - Marketing', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Allgemeine Kenntnisse im Umgang mit dem Computer, sowie Grundlagen im kaufmännischen Rechnen werden vorausgesetzt.', 'Aneignung von allgemeinen Grundkenntnissen der Betriebswirtschaft und im speziellen im Bereich Marketing.', '* Unternehmen zwischen Beschaffung und Absatzmarkt\n* Zielsysteme von Unternehmen \n* Marketing als Grundsatz der Unternehmensführung\n* Aufgaben und Ziele des Marketings\n* Marktforschung, Marktprognose\n* Marketinginstrumente\n* Produktpolitik\n* Preispolitik\n* Kommunikationspolitik\n* Distributionspolitik\n* Marketing-Mix', 'Sie lernen in diesem Kurs die Grundlagen der Unternehmensführung bezogen auf das Marketing kennen. Sie werden damit in die Lage versetzt, die Marketing-instrumente beruflich einzusetzen und damit Ihre Produkte und Leistungen erfolgreich auf dem Markt zu positionieren.', 0),
(19, 79, 1, 'A-04-008', 'Projektmanagement incl. MS Project', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Allgemeine Kenntnisse im Umgang mit dem Computer und betriebswirtschaftliche Grundkenntnisse werden vorausgestzt.', '* Erarbeitung der Grundlagen des Projektmanagements von der Projektidee bis zum Projektabschluss.\n* Solide Kenntnisse zum Umgang mit MS Project', '* Grundlagen des Projektmanagements\n* Projekte initialisieren und planen\n* Projektcontrolling\n* Änderungen und Risiken bearbeiten\n* Projektabschluss\n* PM-Software A-Plan\n* Grundlagen der Programmbedienung MS Projekt\n* Erstellung von Projekten\n* Ressourcen, Termine verwalten\n* Projekte steuern und verfolgen\n* Kosten überwachen', 'Sie wissen, wie sich Projekte erfolgreich von der Idee bis zum Übergang in den Regelbetrieb initiieren, planen, und durchführen lassen. Praktisch können sie die Projekte mit MS Projekt PC-gestützt bearbeiten.', 0),
(20, 88, 1, 'E-01-001', 'RENO-Assistenz', 'Prüfung: interne Prüfung\nAbschluß: Trägerzertifikat', 'Allgemeine Kenntnisse im Umgang mit dem Computer und im kaufmännischen Rechnen werden vorrausgestzt.', 'RENO-spezifische Buchführung, sichere Nutzung von MS Word und 10-Fingertastschreiben.', '* Kaufmännischen Rechnens\n* Grundlagen des Rechnungswesens\n* Erfolgsermittlung durch Einnahmen-Überschussrechnung\n* Kostenblatt und Beleggeschäftsgang\n* Einnahmen- Überschussrechnung nach amtlich vorgeschriebenem Vordruck\n* Schreiben und Gestalten von MS Wordtexten, Erstellen von Dokumentvorlagen, nutzen von Autotexten und fertigen von Serienbriefen.\n* 10-Finger-Tastscheiben', '* Einsatz von Kenntnissen im kaufmännischen Rechnen in RENO – Kanzleien\n* Sichere Anwendung von MS Word für RENO-Fachangestellte \n* Nutzung des 10-Finger-Tastscheibens beim Erstellen von Fachtexten', 0),
