(58, 181, 2, 'A-02-008', 'Bewerben mit Word', '', 'keine', 'Bewerbungsunterlagen in Word erstellen\nInternet als Informationsquelle für Online-Bewerbungen nutzen', 'Word-Grundlagen\nStärkenanalyse\nErstellen von Lebenslauf, Deckblatt, 3. Seite\nAnschreiben formulieren und erstellen unter\nBerücksichtigung der DIN Norm\nUnsere Vermittlungscoaches unterstützen Sie bei Ihrer Bewerbung!', 'Aussagekräftige und individuelle Bewerbungen anfertigen können', 0),
(59, 185, 1, 'A-06-006', 'Geprüfte Fachkraft Xpert Business - Internes Rechnungswesen', 'Wenn das aktuelle Paket  gemeinsam mit Paket A-06-002 [Vorbereitung kaufmännische Zertifizierung FiBu] gebucht wird, bitte das Modul 03-060-001 [ Xpert Business Finanzbuchführung 1], wegen Doppelbelegung  eliminieren\n\n(Modul-)Paketnr.:38', '', '', '', '', 0),
(60, 188, 1, 'A-06-007', 'Geprüfte Fachkraft (Xpert Business) - Lohn und Gehalt (Lexware)', '', '', '', '', '', 0),
(61, 189, 1, 'A-06-008', 'Geprüfte Fachkraft (Xpert Business) - Lohn und Gehalt (Datev)', '', '', '', '', '', 0);
