(63, '2025-02-10 KDB_BQ_151  WVB_BQ_151  VFA_BQ_32  Geschäftsvorgänge und Auftragsbearbeitung', '2025-02-10', '2025-02-21', 67, 1, 1, 766, 143, 'ok', 'Die Gruppe ist insgesamt motiviert und im Durchschnitt leistungsstark. Der Schwierigkeitsgrad der Klausur entspricht den Anforderungen der jeweiligen Kammer.', 1, '', '', 1, -1, 0, 1, 0),
