INSERT INTO `gpb_kurs_kurzbericht` (`kursid`, `zusammenfassung`, `inhaltsgestaltung`, `methoden`, `eindruck`, `todos`) VALUES
(1, 'Dies war ein toller Kurs', '', '', '', ''),
(11, 'Lorem ipsum dolor sit amet, consetetur sadipscing elitr, sed diam nonumy eirmod tempor invidunt ut labore et dolore magna aliquyam erat, sed diam voluptua. At vero eos et accusam et justo duo dolores et ea rebum. Stet clita kasd gubergren, no sea takimata sanctus est Lorem i', 'r invidunt ut labore et dolore mag', 'imata sanctus est Lo', 'am voluptua. At vero e', 'res et ea rebum. Stet clita '),
(17, 'lorem ipsum', '', '', '', ''),
(30, 'n.', 'njj', 'bj', 'n', ''),
(23, 'Kennenlernen - das Institut, die Mitarbeiter, die Prozesse, die Anforderungen.\nHarmonische Gruppendynamik, das Mit- und Untereinander, Teambuilding und Motivation.\nLernen, Input, Output, Spaß und emphatischer Umgang miteinander.', '', '', 'Recht inhomogen. Einige wenige Extrovertierte dominieren die Gruppe.\nViele eher stille Personen fühlen sich vielleicht in Zukunft dadurch belastet?', ''),
(40, 'Die Einführungswoche dient dazu, sich mit den Gegebenheiten der Ausbildung sowie der Schule vertraut zu machen.\n', 'Vorträge sowie PowerPoint-Präsentationen und Workshops', 'Vorträge, SGL, Feedbackrunden', '', ''),
(45, 'Grundlagen der Gestaltung,\nGrundelemente,\nBewegungsrichtung,\nGestalt Gesetze,\nBlick Führung und\nWahrnehmung,\nGestaltungsraster goldener schnitt/ 1/3 Teilung -\nFarben, bedeutung und\nzusammenspiel , Kontraste und Harmonien,\nGrundlagen der Kommunikation,\nSemiotik - welt der zeichen,\nund zum Abschluss die Semiotische Analyse als einzelarbeit.', 'siehe tagespplan / Klassenbuch', 'Frontalunterricht - analoge Übungsblätter - digitale Übungsblätter (Acrobat Reader oder vollverion) tägliche fallbeispiele aus der Werbung (Google Bildersuche) zum besprechen - praktische aufgaben, Lernkarten zum verinnerlichen -\n', 'Die KLasse ist seht motiviert, im umgang miteinader aufmerksam und freundlich. Es herrscht ein positives und unterstützendes klima. Es war eine angenehme und erfolgreiche woche.', 'wie immer wäre ein woche konzeption und entwurf toll, aber dafür fehlen den TN leider auch noch die Fertigkeiten in den nötigen Programmen. Aber auch analog wäre eine solche möglich! - Retrostyle\nEvtl. könnte die Klasse das mit Herrn Khorasani gemachte Projekt auch nochmal gestalterisch auf den Prüfstand stellen.'),
(35, 'Kennenlernen - das Institut, die Mitarbeiter, die Prozesse, die Anforderungen.\nHarmonische Gruppendynamik, das Mit- und Untereinander, Teambuilding und Motivation.\nLernen, Input, Output, Spaß und emphatischer Umgang miteinander.', '', '', '', ''),
(41, 'Die Teilnehmer*innen wurden thematisch und inhaltlich auf die Umschulung vorbereitet und persönlich wie als Gruppe in die Strukturen des Instituts eingewiesen. Sie wurden in den notwendigen Bereichen belehrt und in den Rahmenbedingungen (Anwesenheiten etc.) gebreeft. Im Feedbackgespräch kamen durchweg positive Äußerungen über die Inhalte zu den Strukturen sowie zu den Coachings in den einzelnen Bereichen. Der Unterricht erfolgte in Vollzeit im 9+0 - Modell.', 'Es wurden alle wichtigen Thematiken für die Einweisungen in die Umschulung vermittelt. Zusätzlich gab es Gruppencoaching in der Thematik Persönlichkeit, Persönlichkeitsentwicklung, Kommunikation, Lerntypen und Lernmethoden und Grundlagen für einen erfolgreichen Abschluss des eigens gewählten neuen Berufsweges.', 'Klassisch gehaltener Unterricht in der Einführungswoche, in dem Coachings eingeflossen sind.', 'Die Gruppe macht einen motivierten und aufgeschlossenen Eindruck, hat sich sehr gut zusammengefunden, was für die kommenden Module eine gute und wichtige Grundlage ist. Sie sind offen und bringen sich aktiv in die Wissensvermittlung mit ein.', 'Keine besonderen Hinweise.'),
(47, 'Siehe Tagesbericht. HD', 'Der Unterricht wurde wie von der GPB vorgeschrieben absolviert.', 'Vorlesung. Seminar.', 'Gut, keine Probleme.', '-'),
(39, 'Testeintrag', '', '', '', ''),
(36, 'Dieses Modul hat den Umgang und die Berechnung mit verschiedenen Zahlensystemen zum Inhalt,\nDesweiteren allgemeine Mathematik, Verkettung von Logikgattern und binäre Kodierung weiterer Datenformate.\n', 's. Tagesplan', 'Präsentation und Demonstration durch den Dozenten, Eigen- und Gruppenarbeit an Aufgaben und individueller Trainerunterstützung', 'Sehr motiviert und i.A. mit gutem Verständnis für das Thema\nWeniger als 67% der IL-Aufgaben erledigt:\nAaron Kastl 24%, Emanuel Kronas 66%, Tommy Fitzner 34%, ', '---'),
(37, 'Recht: auch wichtig für die Prüfung.\nRecht: deutlich wichtig für den Beruf, für den wirtschaftlichen Ertrag des Berufs.\nRecht: nachhaltig wichtig für das weitere, und für das übrige, Leben; und für die anderen Menschen.', 'Keine mindernden Abweichungen, gegebenen Ausbildungsberufen folgend Gewichtung und Ergänzung, besprochen und entsprechend umgesetzt. Einige prüfungsrelevante Inhalte aus dem WiSoR4-Modul nachgereicht.', 'Grundsätzlich: (7+2) Teilnehmerzentriertes Lehrgesprächin virtueller Präsenz mittels BBB nebst Angeboten zur Gruppenarbeiten (vgl. bitte insoweit die Protokollierungen im IL-Kurs), eigene Lehrmaterialien, ergänzende Materialien, anwendbare Moderationstechniken; Skript; modifiziertes ppt.-Skript. Übungsfallstudien nebst Auswertung; affektiv intrinsische Ergänzungen zur Steigerung der Ernsthaftigkeit;', 'Teilnehmerspezifisch nehme ich Bezug auf die Gespräche mit Frau ILin.\n\nFrageverhalten überwiegend gut, insgesamt gute Mitarbeit, insbes. relariv häufige Nachfragen, ausführliche Lehrvorträge erwiesen sich als zielführend. Sicherlich ist es zutreffend, die Damen und Herren dort abzuholen, wo sie beginnen; alle, nicht nur viele, sollten aber dann auch mitgehen.\n\nGruppenarbeit wurde regelmäßig nicht erwünscht. Angeleitetes Arbeiten war prägend, wenige Teilnehmer vermieden es teilweise, eigeninitiativ Strukturen sich zu erarbeiten, die Übungen wurden überwiegend gut bearbeitet. Ergänzend nehme ich Bezug auf die mdl. Auswertungen.\n\nAllgemein waren gute Umgangsformen festzustellen. [Leider eher bei anderen Kursen seltener: für Antworten wurde Dank ausgesprochen.]\n\nInsgesamt eine gute Klasse, mit Motivationspotential bei einzelnen Teilnehmern. Einige Anstrengung wird wohl aufzuwenden sein, um die Klasse auf diesem positiv anmutenden Weg zu halten, dies gilt auch für das gegenwärtige Ausbildungsstadium. Wohl mag Potential in den hier gegenständlichen Disziplinen gegeben sein. Sollte bei den wenigen Teilnehmern, die es angeht, möglicherweise aus der Stille Desinteresse an der eigenen Ausbildung sprechen, wären ernstliche Vorhaltungen zu geben.\nHerrn Kollegen Faeßer-Eitle ist zuzustimmen: " ... Andere Teilnehmer haben möglicherweise Verständnisprobleme was Berufsausbildung bedeutet und voraussetzt ..."\n\nInsges., vorbehaltlich mehr besserer Erkenntnis, eine noch gute Woche. Von den Teilnehmern wurde Freundlichkeit gegeben und gewürdigt. Die Notwendigkeit des Erwerbs wissensbezogener Erkennungsfähigkeiten und die Spezifika in der zentrierten Anwendung habe ich dargestellt.\n\nHinweis: "Bestätigung" vorbehaltl. darstellgbedingter Verknappungen. Höchst vorsorglich: im Bestreitensfalle wird urkundlicher und zeugenschaftlicher Beweis angeboten. \n', 'Klausur im Folgemodul. Ob in eine Fachrechtsklausur entspr. Inhalte einbezogen werden können, steht zu prüfen und zu entscheiden.'),
(48, 'Freies Zeichnen üben und mit einfachen Techniken verbessern, um die Scheu vor dem Zeichnen verlieren.', 'Wiederholung des als (eigentlich) bekannt vorausgesetzten Schulstoffs (Formate, Zeichentechniken, Gestaltgesetze, Gestaltungselemente). Vertiefung neu gewonnener Zusammenhänge anhand theoretischer Fragestellungen und praktischer Umsetzungen.', 'Interaktiver Frontalunterricht für die Gestaltungs-Basics zwingend notwendig. Intensive Arbeit mit praxisnahen Beispielübungen (auch für Theoriethemen). Kleinere Projektarbeiten (Freihandzeichnen). Selbstständige Umsetzungen ähnlicher Gestaltungsausgaben.\n', 'Große Klasse. Überwiegend interessierte und motivierte Teilnehmer, sehr gute Disziplin und Pünktlichkeit! Sehr gute Arbeitsatmospäre und Mitarbeit. Zum Teil schwache zeichnerische Fähigkeiten. ', 'Zeichnen, zeichnen, zeichnen!'),
(46, 'Das Modul behandelt Grundlagen zu Markt und Marketing im Unternehmen, Markt- und Kundenbeziehungen, Markenstrategien, den relevanten Markt, den Marketingmix, sowie Produktpolitik.', 'Lernvorträge und Diskussionen', 'Vorträge, SGL, Aufgaben & Skripte, sowie Moodle', '', ''),
(54, 'Aufbauorganisation und Ablauforganisation verständlich erklärt.', 'Wie mit Hr. Volesky besprochen und lt. Lehrplan.', 'Onlineunterricht moodle, BigBlueButton).', 'Keine.', 'Ablauforganisation (2) in GP 1, Intensivseminar, Prüfungsvorbereitung.'),
(52, 'Grundlagen der Gestaltung,\nGrundelemente,\nBewegungsrichtung,\nGestalt Gesetze,\nBlick Führung und\nWahrnehmung,\nGestaltungsraster goldener schnitt/ 1/3 Teilung -\nFarben, bedeutung und\nzusammenspiel , Kontraste und Harmonien,\nGrundlagen der Kommunikation,\nSemiotik - welt der zeichen,\nund zum Abschluss die Semiotische Analyse als einzelarbeit.', 'siehe tagespplan / Klassenbuch', 'Frontalunterricht - analoge Übungsblätter - digitale Übungsblätter (Acrobat Reader oder vollverion) tägliche fallbeispiele aus der Werbung (Google Bildersuche) zum besprechen - praktische aufgaben, Lernkarten zum verinnerlichen -\n', 'Klasse unharmonisch,\nMitarbeit bei etlichen kernthmenbezogenen praktischen Übungen (Gestaltungsanalysen durch Anwendung des Tagesthemas online) schlecht und nur gut nur bei sehr wenigen.\nDesinteresse war leider sehr gross.\nTransferleistung Gestaltung / Berufsbild gelang Trotz Einführung nicht.\nEs schienen einige TN das Ziel des Kurses nicht zu verstehen (zu wollen).\nAW schlecht. Viele Krankenstände. \n', 'wie immer wäre ein woche konzeption und entwurf toll, aber dafür fehlen den TN leider auch noch die Fertigkeiten in den nötigen Programmen. Aber auch analog wäre eine solche möglich! - Retrostyle\nEvtl. könnte die Klasse das mit Herrn Khorasani gemachte Projekt auch nochmal gestalterisch auf den Prüfstand stellen.'),
(42, 'Grundlagen des Rechts', 'siehe Tagesberichte;', 'vorrangig Frontalunterricht im Homeoffice; tägliche Übungen zur Vertiefung und Wiederholung der Inhalte; Konsultationsmöglichkeiten mit dem Trainer;\n', 'Alle TeilnehmerInnen sind sehr bemüht, natürlich mit unterschiedlichem Erfolg. Der überwiegende Teil ist motiviert und ehrgeizig. Die Teilnahme ist top, auch die Mitarbeit. Insgesamt herrscht eine tolle Atmosphäre und das Unterrichten macht richtig Spaß!', 'keine Hinweise;'),
(59, 'Grundlagen der Betriebs- und Volkswirtschaftslehre einfach und verständlich aufbereitet.\n', 'Wie mit Hr. Volesky besprochen und lt. Lehrplan.', 'Online (moodle/BBB).', 'Keine.', 'Prüfungsvorbereitung.'),
(43, 'In dem zweiwöchigen Modul wurden alle im IHK-Rahmenlehrplan vorgegebenen Inhalte vermittelt und vertieft. Dabei wurde nicht nur auf die wirtschaftliche Struktur im Staat, sondern auch die Einflüsse im sozialen und politischen Bereich des Staates eingegangen und welche Auswirkungen die ihm zur Verfügung stehenden Instrumente haben. Aber auch die europäische und globale Sicht in den wirtschaftlichen Bereichen spielt hierbei ebenso eine wichtige Rolle. Die Teilnehmenden erhielten einen umfassenden Einblick in die Wirtschafts- und Sozialstrukturen des Staates, der Europäischen Union und in globaler Hinsicht.', 'Bei der inhaltlichen Gestaltung wurde auf die vorgegebenen Inhalte der IHK geachtet und mit vermittelt. Hierzu gehören alle im oberen Bereich erwähnten Inhalte.', 'Die Wissensvermittlung erfolgte in der klassischen Unterrichtsform, in Vollzeit und zusätzlich wurde der Kleingruppenunterricht angeboten und genutzt, um die IL-Aufgaben zu erledigen und zum Zweck zusätzlicher Erläuterungen.', 'Die Klasse macht einen sehr motivierten Eindruck und ist sehr gut angekommen. Das erste Modul absolvierten sie interessiert und aufgeschlossen. Es kam während der Wissensvermittlung auch zu verschiedenen, für die Wissensvermittlung bereichernden Gesprächen.', 'Alles in Ordnung.'),
(53, 'Arbeitsorganisation im Learning by Doing\nProjektarbeit und lebendiger Austausch', '', 'Vortrag, Teamarbeit, Kleingruppengespräche, Feedback', 'sehr engagiert und zielorientiert\nTolle Teamarbeit', ''),
(49, 'Kommunikation Modelle und Psychologie im Betrieb oder der Behörde\nmit vielen Übungen und Fallbeispielen', '', 'Vortrag, Kleingruppenarbeit, Coaching, Präsentation, Feedback', 'Motiviert und offen für Neues', ''),
(32, 'Siehe Tagesbericht.', 'Der Unterricht wurde wie in der Modulbeschreibung vorgeschrieben absolviert. Keine Abweichungen.', 'Vorlesung. Seminar. Betreutes Selbststudium.', 'Gut, keine nennenswerten Probleme.', '-'),
(56, 'Einführung in die betriebswirtschaftliche und volkswirtschaftliche Wirtschaftskunde mit Kennenlernen der Faktoren Bedürfnisse, Güter, Produktionsmittel, und deren Bedeutung in verschiedenen Wirtschaftssystemen, Vergleich von Wirtschaftssystemen, Konjunkturzyklus, Einflussmöglichkeiten und die Bedeutung des Bruttoinlandsproduktes (BIP).', 'Die Inhalte wurden hauptsächlich anhand der Unterlagen WISO für Kaufleute im Büromanagement unterrichtet. ', 'Präsentationsgestütztes Lehrgespräch mit Einzel- oder Partnerübungen\nTutorials', 'Die Zusammensetzung der Klasse aus unterschiedlichen Berufen in denen die WSO-Inhalte in den Prüfungen variieren ist herausfordernd.\n\nDie Organisation dieses Moduls war u.a. aufgrund von hohem Krankheitsstand (Teilnehmer, Kollegen, Team) sehr mühsam. Die Nutzung des GPB digital (neues Moodle) hatte Tücken z.B. war der Zugriff auf den Kurs für die TN teilweise nicht möglich. ', 'Preiskalkulationen'),
(63, 'Kaufvertragsrecht', 'siehe Tagesberichte;', 'vorrangig Frontalunterricht im Homeoffice; tägliche Übungen zur Vertiefung und Wiederholung der Inhalte; Konsultationsmöglichkeiten mit dem Trainer;', 'Alle TeilnehmerInnen sind bemüht, allerdings mit unterschiedlichem Erfolg. Die Teilnahme ist top, auch die Mitarbeit. Insgesamt herrscht eine tolle Atmosphäre und das Unterrichten macht richtig Spaß!', 'keine Hinweise'),
(69, 'In Ergänzung zu WiSoR 1 entsprechend Curriculum', 'keine Abweichung', 'Seminaristischer Vortrag\nDiskussionen in der Gruppe\nEinzelübungen und Vorträge', 'gute Lernatmosphäre', 'o.B.'),
(66, 'Kennenlernen - das Institut, die Mitarbeiter, die Prozesse, die Anforderungen.\nHarmonische Gruppendynamik, das Mit- und Untereinander, Teambuilding und Motivation.\nLernen, Input, Output, Spaß und emphatischer Umgang miteinander.', '', '', 'Auch hier teilweise ein Motivationsgefälle von EABs zu den Umzuschuldenden.\nKann in Zukunft Konflikte auslösen, aber die Klasse hat einen angenehmen und freundlichen Umgang miteinander.', ''),
(67, 'Die Einführungswoche dient dazu, sich mit den Gegebenheiten der Ausbildung sowie der Schule vertraut zu machen.\n', 'Vorträge sowie PowerPoint-Präsentationen und Workshops', 'Vorträge, SGL, Feedbackrunden', '', ''),
(62, '', 'keine Abweichung!', 'Frontalunterricht, Gruppengespräche, Übungen. ', 'Ausgezeichnet in jeder Hinsicht!', '-'),
(60, 'Die Welt in Zahlen - Kaufmännisches Rechnen', '* inhaltliche Gestaltung nach Vorgabe Lerninhalte für das Modul "Kaufmännisches Rechnen"\n* Verwendung des Buches "Rechnen für kaufmännische Berufe" sowie Material "Kaufmännisches Rechnen 1, 2, 3"', '* Einweisungen\n* Vortrag\n* Wiederholungen der Theorie von bekannten Themenbereichen\n* Wiederholungs- und Anwendungsübungen mit Auswertungen\n* IL-Aufgaben mit Auswertungen\n* zwei Teil-LEK', '* die gesamte Gruppe funktioniert ordentlich und gut\n* seltene, meist bedingte Verspätungen\n* gute, stabile Anwesenheit der TN und gute Arbeit/Mitarbeit\n* Bereitwilligkeit zum Üben auch bei vielen Übungen gut\n* Leistungsspektrum zwar differenziert, aber nicht zu stark\n* reges Interesse bei neuen, unbekannten Themen und bei Vermittlung von Tricks/Kniffen ;-)', '* immer wieder Anwendung des Rechnens, wenn möglich in allen weiteren Modulen\n* Schwerpunkt: Prozentrechnung und Kalkulationen'),
(51, 'TN erlenen die Grundlagen des Vertragsrechtes, des HGB inkl. Unternehmensformen und das allgemeine Arbeitsrecht', 'laut Bericht', 'Frontalunterricht - Präsenz - z.T. Hybrid, wegen Krankheit', 'keine Besonderheiten oder Auffälligkeiten -  Anwesenheit z.T. prüfen', 'weiter nach Modulplanung'),
(58, 'Arbeitsorganisation im Learning by Doing\nProjektarbeit und lebendiger Austausch', '', 'Vortrag, Teamarbeit, Kleingruppengespräche, Feedback', 'sehr engagiert und zielorientiert\nTolle Teamarbeit', ''),
(77, '', 'keine', 'Vortrag und Übung', 'super!', ''),
(65, 'Siehe Tagesbericht.', 'Der Unterricht wurde wie von der GPB vorgeschrieben absolviert.', 'Vorlesung. Seminar.', 'Gut, keine Probleme.', '-'),
(29, 'Siehe Tagesbericht. HD', 'Der Unterricht wurde wie von der GPB vorgeschrieben absolviert.', 'Vorlesung. Seminar.', 'Gut, keine Probleme', '-'),
(73, 'Siehe Tagesbericht.', 'Der Unterricht wurde wie von der GPB vorgeschrieben absolviert. K. A..', 'Vorlesung. Seminar. IL und KGU.', 'Gut, keine Probleme.', '-'),
(26, 'Siehe Tagesbericht.', 'Der Unterricht wurde wie in der Modulbeschreibung vorgeschrieben absolviert.', 'Vorlesung. Seminar.', 'Gut, keine Probleme.', '-'),
(75, 'Das Modul behandelt Grundlagen zu Markt und Marketing im Unternehmen, Markt- und Kundenbeziehungen, Markenstrategien, den relevanten Markt, den Marketingmix, sowie Produktpolitik.', 'Lernvorträge und Diskussionen', 'Vorträge, SGL, Aufgaben & Skripte, sowie Moodle', '', ''),
(76, 'Kursinhalt wie im Curriculum Wisor 1 vorgegeben', 'keien Abweichungen', 'Seminaristisches Vortrag\nDiskussion\nEinzelübungen (Reporterstellung)', 'gute Lernatmosphäre', 'o.B.'),
(78, 'Grundlagen im Umgang mit Microsoft Excel und der Formeleingabe mit verbreiteten Rechenverfahren (auch Prozentrechnung). Im weiteren Verlauf der Umgang mit Grundfunktionen und der WENN-Funktion.', 's. Tagesplan', 'Frontal Theorie und Präsentation anhand von Beispielen. Vertiefen mit Übungen und Unterstützung durch den Dozenten\n', 'Motiviert und Pünktlich, Guter Klassenverband\nWeniger als 67% der IL-Aufgaben erledigt:\nHashemi Sayed 36%, Jas Ephraim 46%, Karasahin Marcel 53%, ', '---'),
(64, 'Die TN lernen die Bedeutung von eigen erstellten Bewerbungsunterlagen kenn. Sie beschäftigen sich mit der Erstellung individueller Unterlagen u.a. mit der Hilfe von KI gestützten Wissenstools.', '- keine Abweichung vom Lehrplan', '- frontal Wissensvermittlung via Lese- und Lehrunterlagen mit Hilfe visuellen Arbeitsmitteln\n- eigenverantwortliche Aufgaben mit Dokumentationshorizont zur Aufgabenumsetzung\n- ergänzende Wissensaneignung via Lehrvideos, Podcast oder durch teambildende Aufgabenstrukturen\n- Verwendung KI-gestützter Anwendungstools', 'Teilnehmer haben angemerkt, dass das Modul "Bewerbungstraining" zu früh kommt. Sie gehen fast alle erst in 1 Jahr ins Praktikum. Teilnehmer waren sehr unzufrieden, dass Erstauszubildenden und Umschüler in einer Gruppe sind - das Niveau ist zu unterschiedlich. Inhomogene Gruppe, Lebenserfahrungen Inhaltlich in der  Erwartungshaltung sowie Wissenstechnisch', '- keine weiteren Angaben'),
(83, 'TN erlernen die Grundlagen des Vertragsrechtes, des HGB inkl. Unternehmensformen und das allgemeine Arbeitsrecht', 'laut Bericht', 'Frontalunterricht mit Übungen speziell auch für VFA-ler inkl. Auswertung', 'keine Besonderheiten oder Auffälligkeiten -  Anwesenheit z.T. prüfen', 'weiter nach Modulplanung'),
(79, 'Entwicklung und Verwendung von relationalen Datenbanken.', 'Grundlagen relationaler Datenbanken, Beziehungen von Tabellen, Entwurf von Datenbanken mit ERM, Normalisierung von Tabellen\nVerwendung von Datenbanken mit SQL, Auslesen von Daten ', 'Vortrag mit Veranschaulichungen über Beamer, Verteilung von Beispielen als Dateien, täglicher Quiz und Übungen', 'Im gesamten arbeitet die Klasse gut mit. ', ''),
(82, 'Das Modul Arbeitsorganisation beschäftigt sich mit Zielen, Planung, Organisation, Strukturen und Abläufen sowie Controlling im Unternehmen.', 'Lernvorträge und Diskussionen', 'Vorträge, SGL, Aufgaben & Skripte, sowie Moodle', '', ''),
(70, 'Grundlagen für betriebs-/volkswirtschaftliche Module z.B. Finanzbuchhaltung, KLR, GESAU.\nKenntnisstand der Teilnehmer in Bezug auf wirtschaftlich mathematische Fragestellung wird angeglichen/abgestimmt.\n', 'siehe Lehrplan', 'Dozentenvortrag,\nLehrgespräch,\nPräsentation,\nÜbungen.', 'Sehr engagierte motivierte Gruppe mit positiver(zielorientierter) Gruppendynamik.\nDie Gruppe ist fleißig, engagiert, hinterfragt kritisch konstruktiv , ', 'weiter nach Plan'),
(84, 'Die TN erlernen die grundlegende Funktionsweise der Finanzbuchhaltung, eingebettet in das Rechnungswesen von Unternehmen.', '- keine wesentlichen Abweichungen', '- präsente Ausbildung mit ausbildungsbegleitende Übungsaufgaben\n- selbständiges Umsetzung von vorgegebenen Rahmenbedingungen\n- Teamarbeit mit punktueller Auswertung und richtungsweisenden Umsetzungen\n- Eigenverantwortlich, -orientiert, -organisiert, -lernend', '- bis auf Einige/Wenige welche sich Ausruhen auf was auch immer\n- sehr Interessiert, Lösungsorientiert, Austauschfähig', '- typische buchhalterische Vorgänge bei den Personalbuchungen\n- Jahresabschlussbuchungen; ARA, PRA, s.Verbindlichkeiten, s.Forderungen, Rückstellungen'),
(87, 'Dieses Modul hat den Umgang und die Berechnung mit verschiedenen Zahlensystemen zum Inhalt,\nDesweiteren allgemeine Mathematik, Verkettung von Logikgattern und binäre Kodierung weiterer Datenformate.', 's. Tagesplan', 'Präsentation und Demonstration durch den Dozenten, Eigen- und Gruppenarbeit mit Aufgaben und Tests sowie individueller Trainerunterstützung', 'Größtenteils motiviert und konzentriert, guter Klassenverband, teilweise gibt es Schwierigkeiten mit der Anwesenheit und Pünktlichkeit.\nWeniger als 67% der IL-Aufgaben erledigt:\nFynn Kraft 44%, Lukas Struck 0%, ', '---'),
(74, 'Der Kurs umfasst traditionelle wie neue Marketingmethoden um die Kunden besser zu verstehen und immer mehr un einem stark wettbewerbsintensiven Markt an Boden zu gewinnen.', '-', 'Durch viel Stoff Übungen über die Tage ', 'Sehr motiviert offen und engagiert', '-'),
(72, 'von Dreisatz bis Zinsrechnung - \nGrundlagen des kaufmännischen Rechnens inkl. Handelskalkulation', '1. Dreisatz: gerade, ungerade, zusammengesetzt; 2. Prozentrechnung: Prozentwert, Grundwert, Prozentsatz, verminderter/vermehrter Grundwert; 3. Verteilungsrechnung; 4. Durchschnittsberechnung: einfacher/gewogener Durchschnitt; 5. Preiskalkulation (Handel): Bezugskalkulation, Vorwärts-, Rückwärts- und Differenzkalkulation, Kalkulationsvereinfachung: Kalkulationszuschlag, Kalkulationsfaktor, Handelsspanne (optional: Kalkulationsabschlag) 6. Zinsrechnung: Zinsen, Kapital, Zinssatz, Zeit, deutsche Zinsmethode (30/360, optional weitere) 7. Umrechnung des Skontoprozentsatz (kfm. Überschlagsrechnung und auf Effektivzinssatz) 8. Effektivzinsberechnung', 'Präsenzunterricht mit kleinen Lehrvorträgen, Unterrichtsgespräche mit praktischen Anwendungsbeispielen der Theorie, gemeinsamen Übungen und Aufgaben, deren Lösung im Anschluss gemeinsam besprochen wurde, außerdem über moodle bereitgestellte Dateien\nIL mit der Möglichkeit am/n Folgetag/en nachzufragen ', 'insegesamt willige, disziplinierte Klasse mit guter Mitarbeit - manche (insbesondere Hani Awni) weniger diszipliniert und eher abwesend beim Onlineunterricht', 'Verstehen von Aufgabenstellungen und Anwenden von Gelerntem in anderem Kontext'),
(90, 'Siehe Tagesbericht. HD', 'Der Unterricht wurde wie in der GPB-Modulbeschreibung vorgesehen absolviert. Keine Abweichungen.', 'Vorlesung. Seminar. Betreutes Selbststudium. KGU. IL.', 'Gut, keinerlei Probleme.', '-'),
(96, 'Erlernen von Grundkompetenzen Excel.\nBasiskompetenzen\nFormatierungen\nFunktionen\nDiagramme\n', 'intrain Modul', 'betreutes Selbstlernen', '', ''),
(81, 'Keine Angst vor (großen) Zahlen -- Kaufmännische Mathematik verstehen', '* inhaltliche Gestaltung nach Vorgabe Lerninhalte für das Modul "Kaufmännisches Rechnen"\n* Verwendung des Buches "Rechnen für kaufmännische Berufe" sowie Material "Kaufmännisches Rechnen 1, 2, 3"', '* Einweisungen\n* Vortrag\n* Wiederholungen der Theorie von bekannten Themenbereichen\n* Wiederholungs- und Anwendungsübungen mit Auswertungen\n* IL-Aufgaben mit Auswertungen\n* zwei Teil-LEK', '* die gesamte Gruppe funktioniert relativ ordentlich und gut\n* unschön: zu häufige Verspätungen\n* gute, stabile Anwesenheit vom Kern der TN und gute Arbeit/Mitarbeit\n* Bereitwilligkeit zum Üben, auch bei vielen Übungen, gut \n* differenziertes Bild bei der Bearbeitung der IL-Aufgaben\n* Leistungsspektrum und -potenzial differenziert, dadurch Verzögerungen\n* reges Interesse bei neuen, unbekannten Themen und bei Vermittlung von Tricks/Kniffen ;-)', '* das Thema "Preiskalkulation" konnte inhaltlich nicht bearbeitet werden (Zeitmangel)\n* immer wieder Anwendung des Rechnens, wenn möglich in allen weiteren Modulen\n* Schwerpunkt: Prozentrechnung, Zinsrechnen und Kalkulationen'),
(92, 'Recht: auch wichtig für die Prüfung.\nRecht: deutlich wichtig für den Beruf, für den wirtschaftlichen Ertrag des Berufs.\nRecht: nachhaltig wichtig für das weitere, und für das übrige, Leben; und für die anderen Menschen.', 'Keine mindernden Abweichungen, gegebenen Ausbildungsberufen folgend Gewichtung und Ergänzung, besprochen und entsprechend umgesetzt. Einige prüfungsrelevante Inhalte aus dem WiSoR4-Modul nachgereicht.', 'Grundsätzlich: (7+2) Teilnehmerzentriertes Lehrgesprächin virtueller Präsenz mittels BBB nebst Angeboten zur Gruppenarbeiten (vgl. bitte insoweit die Protokollierungen im IL-Kurs), eigene Lehrmaterialien, ergänzende Materialien, anwendbare Moderationstechniken; Skript; modifiziertes ppt.-Skript. Übungsfallstudien nebst Auswertung; affektiv intrinsische Ergänzungen zur Steigerung der Ernsthaftigkeit;', 'Teilnehmerspezifisch nehme ich Bezug auf die Gespräche mit Frau ILin.\n\nFrageverhalten ordentlich bis gut, insgesamt ebensolche Mitarbeit, ausführliche Lehrvorträge erwiesen sich als zielführend. Sicherlich ist es zutreffend, die Damen und Herren dort abzuholen, wo sie beginnen; alle, nicht nur viele, sollten aber dann auch mitgehen.\n\nGruppenarbeitsräume wurden nicht erwünscht und genutzt. Angeleitetes Arbeiten war prägend; die Übungen wurden überwiegend ordentlich bis gut bearbeitet. Ergänzend nehme ich Bezug auf die mdl. Auswertungen.\n\nGute Umgangsformen waren festzustellen. [Leider eher bei anderen Kursen seltener: für Antworten wurde regelmäßig Dank ausgesprochen.]\n\nInsgesamt eine gute Klasse, die gleichwohl in kleineren Anteilen einer gewissen motivationsbegründenden Betreuung bedarf.\n\nInsges., vorbehaltlich mehr besserer Erkenntnis, eine ordentliche bis gute Woche. Von den Teilnehmern wurde auch Freundlichkeit gegeben und gewürdigt. Die Notwendigkeit des Erwerbs wissensbezogener Erkennungsfähigkeiten und die Spezifika in der zentrierten Anwendung habe ich dargestellt.\n\nHinweis: "Bestätigung" vorbehaltl. darstellgbedingter Verknappungen. Höchst vorsorglich: im Bestreitensfalle wird urkundlicher und zeugenschaftlicher Beweis angeboten.\n', 'Knappe Ergänzungen, Inhalte begründend und herleitend, aus der Wirtschaftslehre und aus der (Staats-)Geschichte, wurden begrüßt und erschienen als erforderlich. Danke für die Einteilung und Organisation, verwaltungsbezogen.'),
(97, 'Grundlagen der Personalwirtschaft: Definition Personalwirtschaft, Definition Personal,\nPersonalplanung, Personalbedarfsermittlung, Personalbeschaffung, Personaleinsatz,\nPersonalentwicklung, Personalfreisetzung, Personalführung, Personalverwaltung', 'zzgl. Personaleinsatzplanung', 'Wissensstand vermittelt, Interesse und Motivation durch Beispiele aus der Praxis oder gezielte\nFragen, Lernen angeregt und unterstützt, Feedback zum Gelernten erfragt\n', 'grundsätzlich angenehmes Arbeiten, Lernlevel der Klasse sehr gemischt - einige sind wissensdurstig und wollen viel lernen, andere haben wenig oder gar kein Interesse, leider sind auch in dieser Klasse wieder die Sprachschwierigkeiten ein Problem!!! ', 'Vertiefung des gesamten Wissens, Lohnarten komplett (z. B. Akkordlohn-Berechnung)'),
(98, 'Siehe Tagesbericht.', 'Das Modul wurde wie von der GPB vorgeschrieben absolviert. Keine Abweichungen.', 'Vorlesung. Seminar. ', 'Gut. Keine Probleme.', '-'),
(95, 'Entwicklung und Verwendung von relationalen Datenbanken mit SQL.', '- Entwicklung von Datenbanken mit SQL\n- ganzheitliche Aufgabe zu Datenbanken in Form einer Projektarbeit\n- IHK-Aufgaben zu Datenbanken\n- Implementierung von SQL in Webanwendungen', 'Vortrag mit Veranschaulichungen über Beamer, Verteilung von Beispielen als Dateien, täglicher Quiz und Übungen', 'Im gesamten arbeitet die Klasse gut mit und ist interessiert und aufmerksam. Vor allem in der Projektarbeit entwickelte sich eine eigenständige Motivation.', ''),
(101, 'Business English for B2B correspondence and Letter Writing, Vocational English for your field.', 'the Building Blocks of Business Letter Writing, Correspondence for Business Transactions, Business English, English for their specific Occupation.', 'Task-Based Learning.', 'Gute Klasse', 'Vertiefen vom Berufs-English in ihrem Fachbereich.'),
(108, 'Sicher im Umgang mit Zahlen! Gut für Beruf und Privatleben!!!', 'Wie mit Hr. Volesky besprochen und lt. Lehrplan.', 'Online (moodle, BigBlueButton)', 'Keine.', 'Prüfungsvorbereitung und in jedem Modul in dem gerechnet werden muss.'),
(91, 'Grundlagen für betriebs-/volkswirtschaftliche Module z.B. Finanzbuchhaltung, KLR, GESAU.\nKenntnisstand der Teilnehmer in Bezug auf wirtschaftlich mathematische Fragestellung wird angeglichen/abgestimmt.\n', 'siehe Lehrplan', 'Dozentenvortrag,\nLehrgespräch,\nPräsentation,\nÜbungen.', 'Sehr engagierte motivierte Gruppe mit positiver(zielorientierter) Gruppendynamik.\nDie Gruppe ist fleißig, engagiert, hinterfragt kritisch konstruktiv , ', 'weiter nach Plan'),
