(800, 'Desktop Anwendungen erstellen mit C#', '', '', '', ''),
(865, 'Grundlagen der Entgeltabrechnung\n- Bruttolohnermittlung, gesetzliche Abzugsbeträge für lfd. Bezüge und Einmalzahlungen\n- Brutto-/Nettoabzüge\n- besondere Abrechnungsgruppen ', 'gemäß Lehrplan', 'online Unterricht via bbb und mit Einsatz von über moodle bereitgestellte Dateien und Links; Präsentation + Unterrichtsgespräch, Erkär-Videos, Aufgaben, mit anschließender gemeinsamer Auswertung der Lösungen und praktische Anwendungsbeispiele; IL mit der Möglichkeit am/n Folgetag/en nachzufragen', 'angenehme Klasse mit interessierten Telnehmenden und guter Mitarbeit', 'Anwendung von Gelerntem in anderem Kontext;\nrichtige Interpretation komplexer Fragestellungen'),
(211, 'C# und Unity', 'Vorstellung Unity u. C#', 'Erklärungen und Live Coding', 'OK, teils sehr interessiert, teils weniger interessiert o. etwas überfordert', ''),
(907, 'Rechtliche Rahmenbedingungen\nOrganisation der Abläufe im Kassenbereich \nKassenbericht, Abrechnungen und Berechnung der Tageslosung\nServiceleistungen im Kassenbereich', 'Inhalte lt. Tagesbericht, keine Abweichung vom Rahmenlehrplan', 'Vorstellung der Vorgehensweise bei der Lösung prüfungsrelevanter Aufgaben\nVorstellung ausgewählter Schwerpunktthemen\nPraktische Übungs- und Anwendungsaufgaben\nAuswertungen und Zusammenfassungen\nindividuelle Konsultationen\n', 'Gesamteindruck der Gruppe: gut\nzielgerichtetes Arbeiten der TN\nangenehme und ergebnisorientierte Lernatmosphäre\n', 'Eigenständiges Erarbeiten von Lösungen\nSelbstkontrolle eigener Lösungen\n'),
(238, 'Übungen zur Wiederholung/Festigung der Inhalte der Module KLR 1 und KLR 2 ', 'Keine Abweichungen', 'Seminaristische Vorträge\nÜbungen mit Auswertungen in der Gruppe', 'o.B.', 'o.B.'),
(861, 'Siehe Tagesbericht.', 'Der Unterricht wurde wie in der GPB-Modulbeschreibung vorgesehen absolviert. K. A..', 'Vorlesung. Seminar. Betreutes Selbststudium. Projektarbeit im Team mit gemeinsamer Auswertung der Ergebnisse (Powerpoint-Präsentation inkl. Handout und Hausarbeit).', 'Gut, keine Probleme. Sehr engagiert, gute Anwesenheit.', '-'),
(955, 'Grundlagen der Betriebs- und Volkswirtschaftslehre einfach und verständlich aufbereitet.\n', 'Wie mit Hr. Volesky besprochen und lt. Lehrplan.', 'Online (moodle/BBB).', 'Keine.', 'Prüfungsvorbereitung.'),
(878, 'Alle zentralen Inhalte der Kosten- und Leistungsrechnung wurden vollständig vermittelt. Der Schüler arbeitete in einer realitätsnahen Unternehmensumgebung, in der er eigenständig komplexe Sachverhalte analysieren, Lösungen entwickeln und begründete Entscheidungen treffen musste. Dadurch wurde theoretisches Fachwissen konsequent mit praktischen Arbeitsprozessen verknüpft.', '', 'Der Schüler arbeitete während des gesamten Unterrichts in einer praxisnah gestalteten Unternehmensumgebung. Dort konnte er sein Wissen täglich anwenden und musste aus der Perspektive der Nova Trend eigenständig zu fundierten Entscheidungen gelangen. Auf diese Weise erlebte er die Kosten- und Leistungsrechnung in ihrer realen Ausprägung innerhalb des Tagesgeschäfts. Gleichzeitig wurden Unternehmensentscheidungen sowie die zugrunde liegenden Regeln des Controllings für ihn unmittelbar erfahrbar.', 'Die Anwesenheit und Motivation einzelner Schüler war stellenweise unzureichend. Insgesamt hat die Arbeit mit der Klasse jedoch große Freude bereitet: Der überwiegende Teil der Lernenden zeigte sich engagiert, und die Zusammenarbeit verlief flüssig und konstruktiv.', ''),
(926, 'Die 6 Schritte des Bewerbungsprocederes von Analyse bis Arbeitsvertrag sowie erstellen der Bewerbungsunterlagen und Adressrecherche', 's. Tagesplan', 'Frontalunterricht mit Präsentation und Phasen zur Erstellung der Unterlagen mit Trainerunterstützung', 'fröhlicher im Allgemeinen motivierter Klassenverband, etwas unwillig beim Erstellen der Bewerbungsunterlagen.\nJosef Sobolieva war nicht willens Bewerbungsunterlagen zu erstellen, \nRoksana Kubacka hatte am letzten Tag zuhause technische Probleme, so das sie ihre Unterlagen nicht zur Sichtung vorlegen konnte\n\n', '---'),
(892, 'In diesem Modul soll aus verschieden Modulen das Wissen zusammengeführt werden um die Geschäftsfälle entsprechend buchen zu können.', 'laut Bericht', 'laut Bericht', 'EABler keine Anwesenheit und wenn keine Mitarbeit - Ergebnis der Klausur war erwartbar', 'weiter nach Planung'),
(869, 'Thema war das Zivilrecht, das Handels- und Gesellschaftsrecht und das Arbeitsrecht.', 'Grundlage des Unterrichtes waren die ausgegebenen Skripten und Übungsaufgaben', 'unterrichtet wurde durch Lehrvortrag sowie gemeinsame Übungen der Teilnehmer - teils jeweils allein, teils in Gruppen', 'Die Teilnehmer waren sehr motiviert und haben interessiert und durchgängig sehr gut mitgearbeitet.', 'Schreiben von Prüfungsklausuren');
INSERT INTO `gpb_kurs_kurzbericht` (`kursid`, `zusammenfassung`, `inhaltsgestaltung`, `methoden`, `eindruck`, `todos`) VALUES
(929, 'Recht: auch wichtig für die Prüfung.\nRecht: deutlich wichtig für den Beruf, für den wirtschaftlichen Ertrag des Berufs.\nRecht: nachhaltig wichtig für das weitere, und für das übrige, Leben; und für die anderen Menschen.', 'Keine mindernden Abweichungen, gegebenen Ausbildungsberufen folgend Gewichtung und Ergänzung, besprochen und entsprechend umgesetzt. Wegen der besonderen Einsatzsituation Anpassungen an das spez. Berufsbild.', 'Grundsätzlich: (7+2) Teilnehmerzentriertes Lehrgespräch in virtueller Präsenz mittels BBB nebst Angeboten zur Gruppenarbeiten (vgl. bitte insoweit die Protokollierungen im IL-Kurs), eigene Lehrmaterialien, ergänzende Materialien, anwendbare Moderationstechniken; eigene Skripte; modifiziertes ppt.-Skript. Übungsfallstudien nebst Auswertung; affektiv intrinsische Ergänzungen zur Steigerung der Ernsthaftigkeit;', 'Teilnehmerspezifisch nehme ich Bezug auf die Gespräche mit Herrn IL.\n\nFrageverhalten teilweise gut, ebensolches  gutes Nachfrageverhalten, insgesamt ordentliche Mitarbeit, ausführliche Lehrvorträge erwiesen sich als zielführend. Sicherlich ist es zutreffend, die Damen und Herren dort abzuholen, wo sie beginnen; alle sollten aber dann auch mitgehen.\n\nGruppenarbeitsräume wurden nicht erwünscht und genutzt. Angeleitetes Arbeiten war prägend; die Übungen wurden überwiegend gut bearbeitet. Ergänzend nehme ich Bezug auf die mdl. Auswertungen.\n\nGute Umgangsformen waren allgemein festzustellen. [Leider eher bei anderen Kursen seltener: für Antworten wurde Dank ausgesprochen.]\n\nInsgesamt eine Klasse mit differnzierter Zusammensetzung, einige wenige Damen und Herren verblieben still, andere arbeiteten gut mit. Gute Auswertungen der IL-Aufgaben.\n\nDeutliches Motivationspotential bei wenigen Teilnehmern ist gegeben. Sollte bei den wenigen Teilnehmern, die es angeht, möglicherweise aus der Stille Desinteresse an der eigenen Ausbildung sprechen, wären ernstliche Vorhaltungen zu geben.\nHerrn Kollegen Faeßer-Eitle ist zuzustimmen: " ... Andere Teilnehmer haben möglicherweise Verständnisprobleme was Berufsausbildung bedeutet und voraussetzt ...".\n\nInsges., vorbehaltlich mehr besserer Erkenntnis, eine noch gute Woche. Von den Teilnehmern wurde auch Freundlichkeit gegeben und gewürdigt. Die Notwendigkeit des Erwerbs wissensbezogener Erkennungsfähigkeiten und die Spezifika in der zentrierten Anwendung habe ich dargestellt.\n\nHinweis: "Bestätigung" vorbehaltl. darstellgbedingter Verknappungen. Höchst vorsorglich: im Bestreitensfalle wird urkundlicher und zeugenschaftlicher Beweis angeboten.\n', 'Zuerst danke für die Einteilung; sodann: die besondere Ersatzfunktion ergab, daß grdsl auch das UWG in dieser Fachrichtg gegeben werden sollte.'),
(919, '', 'Beendigung des Moduls Wohnungseigentum; Vorstellung der WQ und Bedeutung in der praktischen Prüfung', 'Aufgaben, Übungen, selbstgesteuertes Lernen', 'Anwesenheitsdisziplin lässt nach', '---'),
(751, 'Einkünfte aus Nichtselbständiger Arbeit nach § 19 ESTG', 'Arbeit mit dem Lehrbuch\nArbeit mit dem Gesetzbuch\nVortrag frontal', 'Klasse ist überwiegend lernwillig. Schwierigkeiten sind immer noch bei der Arbeit mit dem Gesetzbuch zu sehen, bei der konsequenten Nacharbeit der behandelten Paragrafen und bei der Formulierung von Begründungen.', 'Es zeichnet sich zunehmend eine Diskrepanz aus den "alten" und den "neuen"  Teilnehmern ab. Die "alten" würden gern im Thema weitergehen, die "neuen" müssen erstmal die Grundlagen verstehen. ', 'Konsequentes Arbeiten mit dem Gesetzbuch und mehr Nacharbeit des Erlernten in der IL-Zeit. Die IL werden noch nicht konsequent genug ausführlich bearbeitet. '),
(893, 'ARBEITSORGANISATION: Aufbau- und Ablauforganisation, Arbeitsorganisation\nGESCHÄFTSPROZESSE: Definition, Merkmale, Elemente, Ziele, Arten, Prozessmanagement, Aufbau- und Ablauforganisation im Zusammenhang mit Geschäftsprozessen, IST-Zustand der Geschäftsprozesse im Unternehmen und Erhebungsmethoden, Darstellung von Geschäftsprozessen, Prozessoptimierung und -verbesserung, \nPROCESS MAPPING: Prozesslandkarten, Grundlegende Symbole, Flussdiagramnme, Ereignisgesteuerte Prozessketten (EPK), Swimlane-Diagramme, BPMN-Diagramme\nEREIGNISGESTEUERTE PROZESSKETTE: Definition, Zweck, Prozessoptimierung, Anwendung, Symbole, Aufbau, Beispiele\nQUALITÄTSMANAGEMENT: Definition, QM und TQM, Ziele, das QM-Handbuch, Audits, Rollen, Normen und Standards, Zertifizierung', ' Inhaltliche Gestaltung in Anlehnung an das Fachbuch "BüroWelt"', 'Frontalunterricht, Blended Learning, Partner- und Gruppenarbeit ->Wissensstand vermitteln,\nMotivation durch Beispiele aus der Praxis oder gezielte Fragen, Lernen anregen und\nunterstützen, Wissen durch tägliche Wiederholung festigen, Feedback zum Gelernten erfragen,\ndiverse schriftliche Übungen, IHK-Prüfungen lösen', 'In der SQ ist die Zusammenarbeit immer gut, da man sich schon kennt. :-)', 'In der Prüfungsvorbereitung sollte nur noch auf die relevanten Themen der Prüfung eingegangen\nwerden!'),
(930, 'Studioproduktion /Alex Workshop', 'Redaktionelle Vorbereitung und Durchführung einer Studioproduktion zu Gast bei Alex Berlin', 'Workshop, Gruppenarbeit, Praxis', 'sehr gut ', 'Video/ Studiotechnik'),
(959, 'Gestaltung nutzerzentrierter digitaler Produkte unter Berücksichtigung von Usability, UX-Design und UI-Design.\n\nWiederholung: Zur Visualisierung und Validierung von Designkonzepten werden Mockups mit dem Design-Tool Figma erstellt, angepasst an verschiedene Endgeräte wie Desktop und Smartphone, um responsive Layouts zu gewährleisten. Dabei ist die Konsistenz der Gestaltung ein zentrales Prinzip, das durch einheitliche Design-Elemente und -Richtlinien die Benutzerführung erleichtert.\n\nAufbauend auf den Mockups wird ein interaktiver Prototyp in Figma entwickelt, der die Benutzerinteraktionen simuliert.\n\nDie Umsetzung erfolgt durch die technische Realisierung der Designvorlagen mittels HTML5 und CSS3, wobei moderne Webstandards, Accessible Rich Internet Applications und Responsive Webdesign-Techniken zum Einsatz kommen, um eine plattformübergreifende und barrierearme Webpräsenz sicherzustellen.', '', '', '', ''),
(965, 'Produktpräsentation-Warenpräsentation /Schaufenstergestaltung', '', '', '', ''),
(964, 'In diesem Modul lag der Fokus auf der Postproduktion eines Musikvideos. Die Lernenden bearbeiteten vorhandenes Bild- und Tonmaterial und setzten daraus ein stimmiges, rhythmisches Gesamtprodukt um. Zentrale Inhalte waren Videoschnitt, Farbkorrektur, einfache Effekte, Titling sowie die Synchronisation von Bild und Musik. Ziel war es, ein fertiges Musikvideo zu exportieren, das sowohl technisch sauber als auch gestalterisch überzeugend ist.', '- Stärkerer Fokus auf praktische Schnittarbeit statt theoretischer Einführung\n- Vertiefung von Rhythmusgefühl im Schnitt und Timing zur Musik\n- Individuelle Betreuung je nach Leistungsstand\n- Gemeinsame Analyse von Rohschnitten und Zwischenergebnissen ', '- Learning by Doing: eigenständige Arbeit am Schnittprojekt\n- Kurze Inputs zu spezifischen Themen (z. B. Farbkorrektur, Export-Settings)\n- Einzelcoachings zur gezielten Problemlösung\n- Gruppenfeedback anhand von Zwischenschnitten\n- Arbeit mit realistischem Zeitdruck, um Produktionsbedingungen zu simulieren', 'Die Klasse arbeitete insgesamt engagiert und praxisorientiert. Auffällig war die hohe Motivation, eigene kreative Entscheidungen umzusetzen.\n\nBesonderheiten und Herausforderungen:\n- Unterschiedliche Vorkenntnisse im Schnitt führten zu stark variierenden Arbeitstempi\n- Teilweise Unsicherheiten bei technischen Grundlagen (Codecs, Framerates, Export)\n- Sehr positive Dynamik beim gegenseitigen Feedback', 'In nachfolgenden Modulen sollten folgende Punkte weitergeführt oder vertieft werden:\n\n- Drehen mit Klappe und Timecode\n- Color Grading mit klarer gestalterischer Zielsetzung\n- Workflow-Sicherheit (Datenorganisation, Synchronisation, Versionierung, Exporte)\n- Vertiefung der Zusammenarbeit zwischen Bild- und Tonpostproduktion'),
(958, 'Einführung in Typografie (Mikrotypografie), Schriften - wie man sie voneinander unterscheidet (Merkmale) und in welchen Bereichen man sie anwenden kann. Kurzeinführung in InDesign.  \nErarbeitung einer der Schriftgruppen nach der DIN-Schriftklassifizierung jeweils in Einzelarbeit. ', '', 'Vortrag u. Präsentation durch Dozentin / Kursteilnehmer*innen, praktische Übungen,\nRecherche und Präsentationserstellung in Einzelarbeit', '', ''),
(943, 'English lessons with concentration on legal terminology comprising grammar overview and comprehensive exercises, reading comprehension, essay writing, and legal email and letter correspondence.', '', '', '', ''),
(887, 'Vorbereitung auf den schriftlichen Teil der Abschlussprüfung', 'Bearbeitung von Musterklausuren zur Wiederholung und Vertiefung der prüfungsrelevanten Inhalte', 'Durch die wiederholte Bearbeitung von Fallübungen auf Prüfungsniveau sollen die Teilnehmer lernen, selbständig einschlägige rechtliche Vorschriften zu nutzen und ihre Konzentrationsfähigkeit und ihr Abstraktionsvermögen weiterzuentwickeln. Durch die ausführliche Fallbesprechung nebst Musterlösungen werden die Teilnehmer in die Lage versetzt, ihr eigenes Wissen und Können fallbezogen zu überprüfen und selbständig zu ergänzen.', 'positiver Gesamteindruck - hohe Lernmotivation', 'Bearbeitung von Originalprüfungen zum Training des individuellen Zeitmanagements'),
(877, '-PHP Einführung\n-Variable, Datentyp, Kontrollstrukturen, Funktionen\n-OOP\n-PHP und HTML Formulare\n-PHP und MySQL\n-Session und Cookies\n-Validierung und Sicherheit', '', '', '', ''),
(961, 'Ihr gesamter Übungspool für diese Woche umfasst etwas mehr als 30 praktische Übungen zu allen Modellierungsarten, die für Ihre Berufsgruppe von Bedeutung sind und größtenteils Bestandteil von IHK-Prüfungen waren.', '', '', '', ''),
(904, '-Was ist IT-Projektmanagement?\n\n--IT-Projektmanagement umfasst die Planung, Steuerung und Umsetzung von IT-Projekten.\n\n-Typische Ziele\n--Projekt termingerecht abschließen\n--Budget einhalten\n--Fachliche & technische Anforderungen erfüllen\n--Risiken früh erkennen und steuern\n--Zufriedene Stakeholder (Kunden, Management, Nutzer)\n\n\n', '', '', '', ''),
(916, 'Arbeitsrecht zur Prüfungsvorbereitung\nmit Bundesgesetzen und TVL Berlin', '', '', 'Teilweise Lücken in der Klausurvorbereitung', 'Klausuren !'),
(935, 'Entwicklung und Verwendung von relationalen Datenbanken mit SQL.', '- Verwendung von Datenbanken mit SQL\n- Entwicklung von Datenbanken mit SQL\n- IHK-Aufgaben zu Datenbanken\n', 'Vortrag mit Veranschaulichungen über Beamer, Verteilung von Beispielen als Dateien, täglicher Quiz und Übungen', 'Im gesamten arbeitet die Klasse gut mit und ist interessiert und aufmerksam. \n', 'Bayir - kaum da\nSygulla - gar nicht anwesend\n'),
(951, 'Veranstaltungstechnische Grundlage und wichtige Begriffe aus dem Segment in Hinblick auf Veranstaltungsplanung,\nAuf Grundlage des Rahmenlehrplanes und Prüfungen der letzten Jahre.', 'Bereiche der Veranstaltungstechnik.\nWichtige gesetzliche Vorgaben zur Planung und dem Einsatz von Veranstaltungtechnik auf Veranstaltungen.\nKunde einschlägiger Fachbegriffe.\nKommunikation mit Technikdienstlesitern.\n', 'Vortrag und Erläuterungen durch Dozenten. Eigene Ausarbeitung neue Themen seitens der Teilnehmer.\nPraxisbeispiele zu Übungszwecken. Beispiele der Teilnehmer.', 'Pümktlichkeit und Anqwesenheit nicht gegeben.', 'Anwendung des erlernten.'),
(942, 'Siehe Tagesbericht. HD', 'Der Unterricht wurde wie von der GPB (Modulbeschreibung) vorgeschrieben absolviert. K. A..', 'Vorlesung.', 'Sehr gut, starke Anfängerklasse. Sehr erfreulich.', '-'),
(864, 'Kanzleiorganisation + Lohn & Gehalt', 'laut Absprache Besprechung prüfungsrelevanter Themen', 'Vermittlung neuer Inhalte frontal, viele Übungsaufgaben mit Auswertung', 'nette Klasse, allerdings zum überwiegenden Teil mit Sprachproblemen', 'wird fortgesetzt'),
(954, 'Kennenlernen - das Institut, die Mitarbeiter, die Prozesse, die Anforderungen.\nHarmonische Gruppendynamik, das Mit- und Untereinander, Teambuilding und Motivation.\nLernen, Input, Output, Spaß und emphatischer Umgang miteinander.', '', '', '', ''),
(80, 'Ziel der Qualifizierung ist die Vorbereitung auf eine berufliche Weiterbildung (Umschulung oder Ausbildung). Es werden Deutsch-Grundlagen vertieft, sodass eine erfolgreiche Ausbildung möglich wird.', 'Zusätzlich zum Lehrplan: - Fokus auf Schreibübungen, um individuelle Schwierigkeiten zu erkennen - Übungen zu Grammatik und Rechtschreibung nach individuellem Bedarf - Übungen zur Erweiterung des Wortschatzes - Erarbeiten von Referaten/Vorträgen - Phonetik', 'Lerner:innen-zentrierter Ansatz - individuelle Aufgaben sowie Partner- und Gruppenübungen - TN-Vorträge vor der Gruppe ', 'TN verfügen z.T. über Deutschkenntnisse auf sehr hohem/muttersprachlichen Niveau - sehr soziale Gruppe, TN fanden sehr schnell offenen Umgang miteinander - schriftlich wurden Lücken (in Bezug auf Rechtschreibung, Wortschatz, Grammatik) sichtbar', ''),
(941, 'Grundrechenarten und Dreisatz', 'siehe Tagesberichte', 'Die Inhalte wurden sowohl frontal als auch im selbstorganisierten Lernen und in Gruppenarbeit vermittelt bzw. erarbeitet. Wiederholungen, Zusammenfassungen sowie die Lösung von Aufgaben mit anschließender Besprechung rundeten die Wissensvermittlung ab.', 'tolle Truppe, außerordentlich motiviert und engagiert.', 'keine Hinweise'),
(944, 'Öffentliches Baurecht\nFlächennutzungsplan\nBebauungsplan\nQualifizierter Bebauungsplan\nVOB\nGewährleistungsfristen\nSicherheitseinbehalt', '', '', '2/3 der Klasse beteiligen sich aktiv am Unterricht.', ''),
(684, 'Netzwerkgeschichte und Überblick 2. Layer I – die physikalische Schicht des OSI-Modells 2.1. Medien im Überblick 2.2. Koaxialverkabelung 2.3. Strukturierte Gebäudeverkabelung (UVG) 2.4. Glasfaserverkabelung 2.5. Verlegung, Handhabung, High-Speed-Verfahren und Gesamtverkabelung 2.6. Kabeltypen und -kategorien und Steckertypen 2.7. Transceiver 2.8. Zugriffsverfahren 3. Layer II – die Sicherungsschicht 3.1. Adressen des Layers II 3.2. Bridges und Switches 3.3. Loops und Spanning Tree 3.4. Layer II-Pakete\n\n4.7. Quality of Service (QOS) 4.8. Das Domain Name System 4.9. Single-, Broad- und Multicast 4.10.\n5. Layer IV – die Transportschicht 5.1. Ports und Sockets 5.2. TCP und UDP5.3. Sicherheit auf Layer III und IV 5.3.1 Router und Firewall 5.3.2. Firewallzonen und -philosophien 5.3.3. NAT, PAT und Masquerading\n6. Virtuelle Netze (VLANs) 6.1. Einsatzgebiete und technische Realisierung 6.2. Vorteile und Grenzen von VLANs 7. Version 6 7.1. Unicast-, Multicast-, Anycast-Adressen 7.2. ICMPV6 7.3. Adressvergabe unter IPV6 7.4. QoS, DNS und DHCP unter IPV6 7.5. Praxis und Übungen aus Lehrbuch-Kapitel 14 8. Szenarien Planung und Beispiele\n8.1. Netzwerke im privaten Bereich, in kleinen und mittleren Un-ternehmen 8.2. Planung eines Netzwerks\n9. Fehleranalyse\nÖffentliche Netze und Dienste\n1. VPN einschl. Verschlüsselungsmechanismen 2. Funknetze und Betriebsmodi, 3. Voice over IP\n4. Netzzugangsszenarien: 4.1. ISDN/Telefon 4.2. DSL/ADSL 4.3. Stand- und Mietleitungen\n5. Gebäudeverbindungen, Hardware, Kombi-Geräte\n', 'Keine', 'Lehrgespräch und 4 Stufen-Methode', 'Gut', ''),
(966, '2. Woche Konzeption: größere Brötchen backen als bei der 1. Woche.', 'Zusätzlich das Thema Briefing angesprochen und die Bestandteile erläutert. ', 'Frontalunterricht, Präsentationen, Einzel- und Gruppengespräche, individuelle Forderung und Förderung.', 'Sehr angenehme kleine Gruppe, sehr gute Anwesenheit und Mitarbeit. ', '-'),
(921, 'Systematische Einführung in das Umsatzsteuerrecht', 'Tatbestandsmerkmale steuerbarer Umsätze sachverhaltsbezogen prüfen und anwenden; wichtige Steuerbefreiungen anwenden; Bemessungsgrundlagen ermitteln, Steuersätze anwenden; Entstehung der Steuer bestimmen und Steuerschuldner nennen; Vorschriften zum Vorsteuerabzug anwenden; Voranmeldungen und Jahreserklärungen erstellen. siehe Tagesberichte!', 'Durch die wiederholte Bearbeitung von Fallübungen auf Prüfungsniveau sollen die Teilnehmer lernen, selbständig einschlägige rechtliche Vorschriften zu nutzen und ihre Konzentrationsfähigkeit und ihr Abstraktionsvermögen weiterzuentwickeln. Durch die ausführliche Fallbesprechung nebst Musterlösungen werden die Teilnehmer in die Lage versetzt, ihr eigenes Wissen und Können fallbezogen zu überprüfen und selbständig zu ergänzen.', 'positiver Gesamteindruck - hohe Lernmotivation', ''),
(963, '', '', '', 'Die Fraktion der unaufmerksamen Teilnehmende setzt das gleiche Verhalten fort. \nErstaunlich, dass die Teilnehmende, die keine Klausuren bestanden haben und weit über 10% Fehlzeiten haben und bereits in Dezember hätten eine Abbruchsempfehlung bekommen sollen, noch da sind! ', ''),
(957, 'Vermittlung der Grundlagen zu den Aspekten Licht, Sehen, Farbe. Relevant für alle Berufsbilder für ein solides Verständnis der Grundlagen und Zusammenhänge mit dem Ziel der Fähigkeit zur fachlichen Kommunikation.', 'Präsentationen, praktische Bespiele, Übersetzung in die reale Anwendung', 'Präsentation über Beamer, Erläuterung zur Präsentation, Literatur zum weiteren Selbststudium', 'Die Gruppe ist ein unerwartetes positives Beispiel das sowohl Pünktlichkeit wie auch Anwesenheit und Mitarbeit funktionieren kann. Sehr schön.', 'Da die Gruppe ausschließlich aus BuT und eCom besteht sind die Grundlagen hier mehr als ausreichend gelegt. Für BuT sollte die praktische Anwendung von Beleuchtungsqualität, Einstellungen der Kameratechnik sowie Einrichtung von Schnittarbeitsplatz und Konfiguration von Farbeinstellungen für den Videoschnitt (bzw. Bildnachbearbeitung) weiter vertieft werden.'),
(939, 'Steuerrecht im Überblick mit Handouts', 'Abgabenordnung\nKörperschaftssteuerrecht\nGewerbesteuerrecht\nUmsatzsteuer\nEinkommenssteuer\nKapitalertragssteuer\n\nÜbungen', 'Seminaristische Vorträge\n\nEinzelübungen', '\nTourismuskaufleute sehr engagiert\nImmobilienkaufleute bis auf Ausnahmen desinteressiert', 'o.b.'),
(946, 'In diesem Modul soll aus verschieden Modulen das Wissen zusammengeführt werden um ein Controlling durch das Kosten- und Leistungsrechnen entsprechend durchführen zu können.', 'laut Bericht', 'laut Bericht', 'EABler keine Anwesenheit und wenn nur online und keine Mitarbeit', 'weiter nach Planung'),
(956, 'Die 6 Schritte des Bewerbungsprozederes von Analyse bis Arbeitsvertrag sowie erstellen der Bewerbungsunterlagen und Adressrecherche', 's. Tagesplan', 'Frontalunterricht mit Präsentation und Phasen zur Erstellung der Unterlagen mit Trainerunterstützung', 'fröhlicher im Allgemeinen motivierter Klassenverband,\nLiam Blaney zeigte mir gegenüber eine persönliche Haltung die eine Zusammenarbeit zum Erstellen bzw. optimieren der Bewerbungsunterlagen unmöglich machte', '---'),
(934, 'Die Welt in Zahlen - Kaufmännisches Rechnen', '* inhaltliche Gestaltung des Grundlagenmoduls anhand Vorgabe Modulinhalte und Lehrbuch "Rechnen für kaufmännische Berufe"', '* Einweisungen/Vorträge\n* Wiederholungen\n* wiederholendes Unterrichtsgespräch\n* Übungs- und Anwendungsaufgaben mit gemeinsamer Auswertung\n* IL-Aufgaben mit täglicher Auswertung\n* Lernerfolgskontrolle', '* die gesamte Gruppe funktioniert ordentlich und gut\n* gute, stabile Anwesenheit der TN und gute Arbeit/Mitarbeit\n* Leistungsspektrum zwar differenziert, aber nicht zu stark\n* reges Interesse bei neuen, unbekannten Themen und bei Vermittlung von Tricks/Kniffen ;-)\n* teilweise nur mäßige Mitarbeit, konzentriert sich auf einige TN\n* 2 Tage online-Unterricht gut angenommen', '* es sollte immer wieder und viel gerechnet werden, so das die Kenntnisse nicht wieder "einstauben"'),
(894, '- Die Teilnehmer erhalten Einblicke in die Bedeutung und deren Besonderheiten des Marketings´s im Gesundheitswesen.', '- keine wesentliche Abweichung vom Lehrplan', '- frontal Wissensvermittlung via Lese- und Lehrunterlagen mit Hilfe visuellen Arbeitsmitteln\n- eigenverantwortliche Aufgaben mit Dokumentationshorizont zur Wissensfestigung\n- ergänzende Wissensaneignung via Lehrvideos, Podcast oder durch teambildende Aufgabenstrukturen\n- eigenständige Projektarbeit zu diesem Thema\n- Prüfungsrelevantes, Unternehmensanalysierendes, PR-Maßnahme - definierendes Projekt', '- sehr Interessiert, bemüht das Wesentliche sich zu erarbeiten auch wenn es viel ist\n- leichte Defizite in der Selbstorganisationsphase\n- immer besserer Umgang mit KI (Copilot, NootbokLM u.a.)', '- keine weiteren Angaben'),
(947, 'Personalbeschaffungswege, Personalauswahlverfahren\nStellenbeschreibung und Stellenausschreibung\nBewerbungsunterlagen, Inhalte Arbeitsvertrag\nStellenbesetzungsplan\nPersonaleinsatzplanung\nMöglichkeiten zur Beendigung von Arbeitsverhältnissen\nArbeitspapiere', 'Inhalte lt. Tagesbericht, keine Abweichung vom Rahmenlehrplan', 'Vorstellung der Vorgehensweise bei der Lösung prüfungsrelevanter Aufgaben\nVorstellung ausgewählter Schwerpunktthemen\nPraktische Übungs- und Anwendungsaufgaben\nAuswertungen und Zusammenfassungen\nindividuelle Konsultationen\n', 'Gesamteindruck der Gruppe: gut\nzielgerichtetes Arbeiten der TN\nangenehme und ergebnisorientierte Lernatmosphäre\n', 'Eigenständiges Erarbeiten von Lösungen\nSelbstkontrolle eigener Lösungen\n'),
(998, 'Grundlagen der Betriebs- und Volkswirtschaftslehre einfach und verständlich aufbereitet.\n', 'Wie mit Hr. Volesky besprochen und lt. Lehrplan.', 'Online (moodle/BBB).', 'Keine.', 'Prüfungsvorbereitung.'),
(937, 'EXCEL Grundlagen: Einleitung, Benutzeroberfläche, Registerkarten, Arbeitsmappen und Arbeitsblätter, Zellinhalte eingeben, Zellformatierung, Erklärung Mauszeiger, Arbeiten mit Formeln und Funktionen, Hauptfunktionen, Hauptrechenarten, Grundrechenarten, Zellen, Zeilen und Spalten markieren und bearbeiten, Zellbezüge (relativ, absolut, gemischt), Shortcuts, Dateiformate, Druckeinrichtungen, Fenster fixieren  ', '', 'Frontalunterricht, Blended Learning, Wissensstand vermitteln, Lernen anregen und\nunterstützen, Wissen durch tägliche Wiederholung festigen, Feedback zum Gelernten erfragen,\ndiverse schriftliche Übungen, IHK-Prüfungen lösen', 'Sehr angenehmes Arbeiten. ', 'Die Excel-Funktionen für die AP1 Prüfung vertiefen.'),
(968, 'Grundlagen der Gestaltung von einfachen Print-Layouts mit Adobe Indesign', 'Grundlagen der Layoutgestaltung müssen von Grund auf an vermittelt werden. Intensive Erarbeitung der Zusammenhänge der wichtigsten Basics am Beispiel Indesign (Seitengestaltung, Bild-Text-Integration, Bildplatzierung und Text-Formatierung).', 'interaktiver Frontalunterricht (via BBB) - dauerhaft praxisorientiert (die TN müssen die ganze Zeit praktisch mitarbeiten) - kleinere selbstständige Projektaufgaben.', 'Mittelgroße Gruppe. Etwas zähe Arbeitsweise, bedingt durch BBB (einige TN haben kein Mikro). Sehr pünktliche TN, gute praktische Mitarbeit an allen Tagen. Aktive mündliche Mitarbeit nur mit 3 bis 4 TN. Etwas eingeschränkte Stoffvermittlung durch Online-Unterricht.', 'Grundlagen Layout, Typografie und (gute!!) Gestaltung. Unbedingt Vertiefung der Basics Photoshop und lllustrator!'),
(970, 'EXCEL Grundlagen: Einleitung, Benutzeroberfläche, Registerkarten, Arbeitsmappen und Arbeitsblätter, Zellinhalte eingeben, Zellformatierung, Erklärung Mauszeiger, Arbeiten mit Formeln und Funktionen, Hauptfunktionen, Hauptrechenarten, Grundrechenarten, Zellen, Zeilen und Spalten markieren und bearbeiten, Zellbezüge (relativ, absolut, gemischt), Shortcuts, Dateiformate, Druckeinrichtungen, Fenster fixieren  ', '', 'Frontalunterricht, Blended Learning, Wissensstand vermitteln, Lernen anregen und\nunterstützen, Wissen durch tägliche Wiederholung festigen, Feedback zum Gelernten erfragen,\ndiverse schriftliche Übungen, IHK-Prüfungen lösen', '', ''),
(938, 'Zielgruppe: \nPersonen, die nur über wenig Erfahrung in der Arbeit mit einem Textverarbeitungsprogramm verfügen und den ICDL erwerben möchten.\n\nLernziel:\nErlangung von Basiswissen zur Arbeit mit einem Textverarbeitungsprogramm, Sichere Anwendung der wichtigsten Funktionen des Textverarbeitungsprogramms\nMS Word 2019, Vorbereitung auf die Absolvierung der ICDL-Prüfung Modul Textverarbeitung\n\nLerninhalte:\nTexte eingeben und überarbeiten, Zeichen-, Absatz- und Seitenformatierung, Objekte und Tabellen einfügen und bearbeiten, Layout bearbeiten, Seriendruck', '-', 'inTrain', '', ''),
(936, 'intrain', 'intrain', 'intrain', '', ''),
(973, 'Einführung in die betriebswirtschaftliche und volkswirtschaftliche Wirtschaftskunde mit Kennenlernen der Faktoren Bedürfnisse, Güter, Produktionsmittel, und deren Bedeutung in verschiedenen Wirtschaftssystemen, Vergleich von Wirtschaftssystemen, Konjunkturzyklus, Einflussmöglichkeiten und die Bedeutung des Bruttoinlandsproduktes (BIP).', 'Die Inhalte wurden hauptsächlich anhand der Unterlagen WISO für Kaufleute im Büromanagement unterrichtet. ', 'Präsentationsgestütztes Lehrgespräch mit Einzel- oder Partnerübungen\nTutorials\nonline-Übungen Multiple Choice\nÜbungsprüfungen', 'Die Klasse hat engagiert am Thema mitgearbeitet. Die technische Unterstützung durch Moodle war nicht immer gegeben, daher gab es viel Improvisation\n', 'Rechtsformen\nBerechnungen'),
(995, '-UML 2\n--Klassendiagramm\n--Zustandsdiagramm\n--Sequenzdiagramm\n\nInkl. IHK Übungen', '', '', '', ''),
(991, 'In diesem zweiwöchigen Intensivkurs lernen Sie, komplexe Systeme klar zu strukturieren und tragfähige Lösungen zu entwickeln. Von der Anforderungserhebung über Stakeholder-Analyse und Priorisierung bis zu Prozess-, Use-Case- und Datenmodellen (z. B. BPMN/UML) — Sie wenden bewährte Methoden direkt auf realistische Fallstudien an. Sie üben Interviews, Prototyping und Dokumentation, erkennen Risiken früh und übersetzen Business-Ziele in umsetzbare Spezifikationen. Am Ende verfügen Sie über einen praxiserprobten Werkzeugkasten für Systemanalyse sowie ein greifbares Portfolio an Ergebnissen, das Sie sofort im Projektalltag einsetzen können.', 'Es gab keine Abweichungen vom Lehrplan. Alle Themen wurden behandelt.', 'Die von mir im Frontalunterricht erläuterten und vorgezeigten Lehrinhalte werden in Einzelarbeit praktisch vom Schüler angewendet.', 'Mein Gesamteindruck von der Klasse ist positiv. Es gibt keine Besonderheiten oder Schwierigkeiten.', 'Die Folgemodule sollten messbare Anforderungen, saubere Modelle und lückenlose Nachverfolgbarkeit  festigen. Daten- und Architekturaspekte, Prototyping/UX, API-Integration, Sicherheit/Compliance sowie agiles Backlog-Management sollten vertieft werden.'),
(940, 'Betriebliche Kommunikation im Learning by doing in Projektarbeit mit Präsentation', '', 'Vortrag\nKleingruppenarbeit\nGespräche in den Gruppen\nPräsentation\nSchrtftliche Auswertung', 'Im Wesentlichen motiviert\nDankbar, dass mit ihnen gesprochen wurde', ''),
(972, 'Einführung in MS Word\nZeichenformatierung, Absatzformatierung; Rahmen und Schattierung, Tabulatoren, Listen, Tabellen, Layout, Formen, Bilder, Serienbriefe, Suchen und ersetzen, Formatvorlagen, Zwischenablage,\nGeschäftsbrief 5008', '', '', '', ''),
(967, 'Vorbereitung auf den schriftlichen und mündlichen Teil der Abschlussprüfung', 'Bearbeitung von Musterklausuren zur Wiederholung und Vertiefung der prüfungsrelevanten Inhalte', 'Durch die wiederholte Bearbeitung von Fallübungen auf Prüfungsniveau sollen die Teilnehmer lernen, selbständig einschlägige rechtliche Vorschriften zu nutzen und ihre Konzentrationsfähigkeit und ihr Abstraktionsvermögen weiterzuentwickeln. Durch die ausführliche Fallbesprechung nebst Musterlösungen werden die Teilnehmer in die Lage versetzt, ihr eigenes Wissen und Können fallbezogen zu überprüfen und selbständig zu ergänzen.', 'positiver Gesamteindruck - hohe Lernmotivation', ''),
(795, 'In den kommenden zwei Wochen tauchen wir gemeinsam tief in die administrativen und rechtlichen Prozesse des Personalmanagements ein. Von der präzisen Kalkulation von Angeboten bis hin zur rechtssicheren Abwicklung von Krankheitstagen und der Entgeltabrechnung – dieses Modul vermittelt euch das essenzielle Handwerkszeug für eure tägliche Arbeit als Personalverantwortliche.\n\nIhr werdet lernen, wie das deutsche Sozialversicherungssystem funktioniert und wie ihr euch in komplexen Situationen (z. B. bei Langzeiterkrankungen) souverän und gesetzeskonform verhaltet.', 'siehe Tagesbericht', 'frontal, online, Fälle, Gruppenarbeiten, Diskussionen, Vorträge', '', 'Vertiefung Lohn- und Gehaltsabrechnung erstellen'),
(945, 'In den kommenden zwei Wochen widmen wir uns einem spannenden und praxisnahen Thema: Wir kombinieren Projektmanagement direkt mit dem Komplexauftrag.\n\n', 'siehe Tagesbericht', 'frontal, online, Gruppenarbeiten', '', ''),
