INSERT INTO `gpb_kurs_tagesbericht` (`kursid`, `tag`, `themen`, `kguil`, `bemerkungen`) VALUES
(77, '2025-02-17', 'Einführung Illustrator, wozu Illustrator, Arbeitsoberfläche, Datei öffnen, RGB Arbeitsbereich, CMYK Arbeitsbereich, eigenen Arbeitsbereich anpassen, Steuerungsleiste, Menüleisten, Werkzeugleiste, Voreinstellungen, Eigenschaftspalette, GPU/CPU Ansicht, Pfadansicht, erste Arbeiten mit unterschiedlichen Linienstärken, Flächen und Konturen, Raster: Rastereinstellung, Rasteransicht, am Rasterausrichten, erste Übungen: Flächen und Linien, einfaches Transformieren (Skalieren, Drehen, Spiegeln, Verschieben (mathematisch und als Duplikat), Linien und Objekte mit Konturen, Transformieren Palette – Was passiert, wenn Konturen nicht mit skaliert werden und wo kann ich es einstellen\n', 'Vertiefung', ''),
(77, '2025-02-18', 'Wiederholung des Vortages, Auswertung der eingereichten Arbeiten, Farbe in Illustrator, RGB, CMYK Mischmodi Wiederholung, Grundformen (Kreis, Rechteck etc.), Grundformen verändern mit Hilfe der Ankerpunkte und des Direktauswahlwerkzeuges, Ankerpunkte runden, Ankerpunkte eckig gestalten, Ankerpunkte zusammenführen, Ankerpunkte ausrichten, Ankerpunkte löschen und hinzufügen, Ebenen und die Ebenenhierarchie, Objekte anordnen in Illustrator, Objekte ausrichten in Illustrator, Was ist eine schöne Linie? Übergang zur Pfadansicht, Text in Illustrator, Text in Pfad umwandeln – Erklärung der unterschiedlicher Medienziele (warum Text in Pfade konvertiert werden muss etc./Beispiel Plotten und Druck), freies Arbeiten anhand vorgelegter Beispiele als Inspiration – erste Illustrationen mit Grundformen, weitere Übungen', 'Vertiefung', ''),
(77, '2025-02-19', 'Wiederholung des Vortages, Auswertung der eingereichten Arbeiten, Zeichenstiftwerkzeug, unterschiedliche Möglichkeiten des Zeichenstiftwerkzeuges, Linien, Linienführung mit dem Zeichenstiftwerkzeug, erneut: Was ist eine schöne Linie? Grafik mit Linien, , erste Illustrationen mit dem Zeichenstiftwerkzeug, Umwandeln von Linien, Boolesche Operatoren (Pathfinder) für Objekte und umgewandelte Linien, Hilfslinien, intelligente Hilfslinien', 'Vertiefung', ''),
(77, '2025-02-20', 'Wiederholung des Vortages, Auswertung der eingereichten Arbeiten, komplexe Logogestaltung: Was ist ein Logo, Geschichte, Arten und des Logos, Kriterien des Logos, Goldener Schnitt, Übungen kompakte Logogestaltung zum vorgegebenen Thema (2 Logos müssen erstellt werden) oder nach Bedarf Entwicklung des eigenen Logos', 'Vertiefung', ''),
(77, '2025-02-21', '... weiter mit der Logogestaltung ... ', '', ''),
(77, '2025-02-24', 'Besprechung der Logos, Gestaltung passender Visitenkarten mit dem erstellten Logo (ein Logo muss ausgesucht werden), Thema Überdrucken, Thema Linien im Druck, Thema Schwarz im Druck, Farbprofil downloaden und installieren und zuweisen, Druckdatei für Visitenkarten richtig anlegen (Größe, Beschnitt, Sicherheitsabstand), Größe der Schrift auf den Visitenkarten etc.\n\nTeilaufgabe Klausur Part 1', 'Vertiefung', ''),
(77, '2025-02-25', 'Besprechung der erstellten VK, Angleichen-Werkzeug, Verlaufseinstellungen, eigenes Muster erstellen, Mustereinstellungen etc., Pinsel, Pinselspitzen, Strichstärken Pinsel, Pinseleinstellungen (glätten, Pixelabstand etc.), Transparenzen, arbeiten im Objekt-Maskenmodus, Schnittmasken erstellen, Masken erstellen über Transparenzpalette, Bild nachzeichnen automatisch und manuell, auch eigene Bitmap in PS erstellen und dann Bild nachzeichnen - für den T-Shirt Druck, Muster erstellen, Arbeiten im Zeichenmodus, Maskenarbeit, Muster erstellen, Angleichenwerkzeug', 'Vertiefung', ''),
(77, '2025-02-26', 'Arbeiten mit dem Breitenwerkzeug - Erstellen einer Grafik - s/w, 2 Farben und 5 Farben, Arbeiten im RGB Modus – Erstellen einer Grafik für eine Webseite – hier lag der Tonus auf dem RGB Modus, die unterschiedlichen Farben in diesem Modus und das Abspeichern einer PNG-Datei für das Internet, des Weiteren wurde das Objekt ausschließlich mit Hilfe der Eigenschaftspalette (nummerische Eingabe) sowie eines neu eingestellten Rasters erzeugt', 'Vertiefung', ''),
(77, '2025-02-27', 'erstellen einer Vektorgrafik als Buchcover zum Thema "Lost"', 'Vertiefung', ''),
(77, '2025-02-28', 'Klausur 90min', '', ''),
(128, '2025-04-07', 'Skript Kommunikationsmodelle\nBetriebliche Kommunikation\nKundenkommunikation\n\nAufgabe 1 zu den Kommunikationsmodellen,\nBeispiele aus dem Büroleben, mit Lösungen zu Kommunikationsstörungen\n\n', 'Präsentationsgestaltung', ''),
