(161, '2025-05-06', 'Massenspeicher (Aufbau HDD/SSD, Busse und Anschlüsse, Partitionierung, Formatierung (High-/Lowlevel), Dateisysteme und Adressierung (CHS, LBA), S.M.A.R.T.', 'IL: Glossareintrag wie Frontal besprochen  ', ''),
(161, '2025-05-07', 'Massenspeicher  Fortsetzung,\nRAID (Vor-/Nachteile von JBOS, NRAID, 0, 1, 1+0, 5, angeschnitten 3, 4, 6), Parität, Hotspare,', 'IL: Glossareintrag wie Frontal besprochen  ', ''),
