INSERT INTO `gpb_kurs_tagesbericht` (`kursid`, `tag`, `themen`, `kguil`, `bemerkungen`) VALUES
(306, '2025-08-04', 'Einführung in Grundlagen der visuellen Gestaltung (Zeichnen I) - Zeichnerische Techniken I - freies Zeichnen von einfachen Grundformen I (Linie, Gerade, Strahl, Strecke) - Übung "Rubinsche Vase" (Symmetrie und Asymmetrie) - Gestaltungselemente beim Zeichnen von Objekten: Größe, Form, Richtung, Position - freies Zeichnen von einfachen Grundformen II (Dreieck, Kreis), Übung "Polygon"-Pferd (Kreisformen und Linien kombinieren) - Übung "Linien-Landschaft I" - diverse Übungen', 'IL-Übung 1: "Linien-Landschaft I" ', ''),
(306, '2025-08-05', 'Wdhlg. vom Vortag und Auswertung IL-Aufgabe - Formate und DIN-Formate - Goldener Schnitt und Fibonacci-Folge - Proportionen des menschlichen Gesichts I (frontal) - Skizzieren von Porträts mit Hilfe der lockeren "Strick"-Technik (zeichnen, ohne abzusetzen) - Vereinfachung und Abstraktion I - diverse Übungen\n', 'IL-Übung 2: de face-Zeichnung "Kopf" in der "Strick"-Technik', ''),
(306, '2025-08-06', 'Wdhlg. vom Vortag und Auswertung IL-Aufgabe - freies Zeichnen von einfachen Grundformen IV - Proportionen des menschlichen Gesichts II (profil) - Licht- und Schattensetzung für einfache plastische Wirkung (Wischtechnik und Schraffur-Technik) I - Schraffur-Arten und -Techniken - Erzeugung von Strukturen mit grafischen Mitteln - Schraffur, Struktur, Textur - Vereinfachung und Abstraktion II - diverse Übungen', 'IL-Übung 3: de face-Zeichnung "Kopf" in der "Wisch"-Technik', ''),
(306, '2025-08-07', 'Wdhlg. vom Vortag und Auswertung IL-Aufgabe - Licht- und Schattensetzung für einfache plastische Wirkung (Wischtechnik, Punktier-, Radier- und Schraffur-Technik) II - Unterteilung und Gliederung am Beispiel menschlicher Körper mit einfachen Grundformen I - Profilansicht (vereinfachte Figur-Grundstrukturen)', 'IL-Übung 4: Frontal-Zeichnung "Figur" in Wisch-Radier-Technik ', ''),
(306, '2025-08-08', 'Wdhlg. vom Vortag und Auswertung IL-Aufgabe - diverse vorbereitende Übungen - Abschluss-Test (60 min)', '–', ''),
