(525, '2025-10-06', 'TAG ! Einführung Reisegeografie DEUTSCHLAND:\n\nTHEMA:Orientierung und Geografische Grundbegriffe\n\nÜbersicht, Lage, Geografie, Topografie, Klima, beste Reisezeiten,\nGeschichte, Kultur, Anreise-Verkehrsmittel, \n\nWichtige Reiseziele: Städte-Bade-Wander-tourismus, Zielgruppen,\nRaum , Region\n\nVerkaufsargumente\n\nÜbersicht:Bundesländer mit Landeshauptstädten, incl 3-letter codes\nAirports\n\nAnrainerstaaten\n\nGroßlandschaften, Flüsse, Berge, Seen, Meere, Inseln, Raumstrukturen,\nBallungsräume, Wattenmeer\n\nErreichbarkeiten\n\nMerkmale zum Naturraum(Relief,Flora,Fauna) und tourist.relevante\nklimatische Besonderheiten, am Beispiel Nord-Ostsee-\nMecklenb. Seenplatte-, Harz-, Schwarzwald\nTouristische Highlights, Besonderheiten,Kultur,Architektur,Kulinarik\n\nWissenstest: Destinationen ', 'IL-Aufgabe lt Lernbox Wissenstest Zielgebiete Deutschland,\nHighlights, Besonderheiten, Anreise', 'ONLINE-UNTERRICHT, via BBB\n\nHilfsmittel: Lernbox, Moodle, Arbeitszettel, Hand Outs, Internet, Kartenmaterial.\n\nLERNZIELE::Orientierung auf Karten, Kennzeichnungen von Flüssen,Städten,Landschaften,Grundbegriffe Raum, Region,\nMikro-Makro-Ebene.\n\nTRAINER-VORTRÄGE:Erklärungen/Präsentationen(Kurzinput)\n\nUNTERRICHTSGESTALTUNG:\nFragen-Antworten\nSituationsaufgaben,30 Minuten Mein Bundesland\nAnnotieren mit 3 Blickwinkel:Wirtschaft-Umwelt-Kultur\nKartenbearbeitungen\nEinzelarbeiten 15-30 Minuten\n\nLERNZIELKONTROLLE/WISSENSTEST 30 Minuten Lage und Begriffsdefinitionen,Anreise,Empfehlungen,Angebote,Insider-Tipps\n\nMATERIALIEN:: Arbeitsblätter, Lernbox,interaktive Karte, Deutschland-Karte\nHand Outs\n\nBesprechungen/Korrekturen'),
(525, '2025-10-07', 'TAG 2 THEMA: Urbanisierung und Städtelandschaften\n\nGroßstädte,,Infrastruktur, Verkehr, Anreise, Attraktionen\n\nWichtige Städte : Berlin-Hamburg-München-Köln-Frankfurt, Einfluss von\nIndustrie und Tourismus.\n\nNachhaltigkeit\n\nZielgruppen und Reisemotive\n', 'IL-Aufgabe lt Lernbox Städte in Deutschland Berlin , Hamburg, München', 'LERNZIELE: Verständnis:Verkehrsinfrastruktur  Autobahnen-Bahn-Flug-Bus\nStadttypen,\nBegriffsdefinitionen\n\nUNTERRICHTSGESTALTUNG:\nTrainer-Vortrag\nEinzelarbeit:40 Minuten Datenkarten zu 3 Städten Hauptmerkmale\nSituationsaufgabe:30 Minuten Angebotserstellung\nFragen-Antworten\n\nMATERIALIEN: Hand out Städteinfos und Lernbox\n\nBesprechung Reflexion Vor-und-Nachteile Städtetourismus\n'),
(525, '2025-10-08', 'TAG 3 THEMA:Geografie der Natur-und Kulturlandschaften\n\nNationalparks, Naturschutzgebiete, Biosphärenreservate \nam Beispiel Spreewald, Schorfheide-Chorin\n\nTouristische Infrastruktur, Unterkünfte, Verpflegung, Anreise,\nBräuche und Traditionen.', 'IL-Aufgabe Präsentation Spreewald', 'LERNZIELE:Zuordnung von Landschaftstypen, UNESCO-Weltkulturerbe,\nErklärungen Unterschiede LANDSCHAFTEN:Mittelgebirge, Alpenvorland, Alpen,Flusstäler,Küstenlandschaften\n\nUNTERRICHTSGESTALTUNG:\nTrainer-Präsentationen\nEinzelarbeiten, Recherchen,Lernboxbearbeitungen\n\nLernzielcheck:Nord/Ostsee/Harz/Schwarzwald\n\nMATERIALIEN:Arbeitsblätter, Lernbox,Hand Outs'),
(525, '2025-10-09', 'TAG 4 THEMA: Tourismus und Wirtschaftsräume\n\nWirtschaftsregionen:Ruhrgebiet(Industrielandschaft), Bayern(High- Tech)\n\nTourismustypen:Kulturtourismus, Naturtourismus, Industriemuseum, \nGedenkstätten.\n\n\nAngebotserstellung: Reiseziele nach Reisearten\nAllgem. Fragen/Wiederholung zum Reiseland Deutschland\n\n', 'IL-Aufgabe: Vorbereitung auf die morgige Klausur\nTHEMA: Auf den Spuren der Stadt Potsdam, lt. Lernbox', 'LERNZIELE:Verständnis von Strukturwandel, Tourismusstrategien,Zielgruppen,Reisemotive\n\nUNTERRICHTSGESTALTUNG:\nTrainer-Vortrag\nEinzelarbeit 30-45 Minuten Fallstudie einer Region, am Beispiel Ruhrgebiet\nSituationsaufgabe:ca 25 Minuten, Plan einer kurzen Regionalreise\nNachhaltigkeit ,ÖPNV\nPräsentation\nAngebotserstellung  30 Minuten\nAllgem. Wiederholungen Tage 1-4\n\nMATERIALIEN:Arbeitsblätter, Video'),
(525, '2025-10-10', 'Datum: 10.10.25 Titel: Klausurtag – Präsentation : Auf den Spuren der Stadt Potsdam\n\nAnwendung:Aufgabenstellung lt. Lernbox\n\nAblauf und Inhalte:\n\nForm: Klausur ca. 90 Minuten\nInhalte der Prüfung:\nTheoretische Grundlagen zu Regionen und Wirtschaftsräumen\nZuordnungs- und Analyseaufgaben zur Regionen  \nKurze Fallstudie (Ausgangslage, Faktoren, Maßnahmen, Bewertung) zur  ausgewählten Region\nKartografische Aufgabe: Bestimmung von Verkehrsachsen, Ballungsräumen sowie Naturschutzgebieten/ UNESCO-Stätten\nE-mail Versendung', '', 'Arbeits- und Lernformen:\n\nEinzelarbeit unter Prüfungsbedingungen Zeitvorgabe: 90 Minuten\nKlausur mit gemischten Aufgabenformen: kurze Antworten, Zuordnungen, Fallstudie, kartografische Aufgabe\nPräsentation\nBesprechung/Auswertung/Notenvergabe\nVerabschiedung'),
(488, '2025-09-29', '* Einweisung in das Lernmodul, Erklärung der Notwendigkeit, Klärung von offenen Fragen\n* Einführungsvortrag zum Thema "Betriebliches Rechnungswesen"\n* Von der Inventur über das Inventar zur Bilanz (Die Inventur)\n* Übungen Ermittlung Inventurbestände und-Werte\n* Von der Inventur über das Inventar zur Bilanz (Das Inventar)\n', '* KGU: Übungsbeispiel zur Erstellung eines Inventars\n\n* IL: Wiederholungsaufgaben zu Inhalten Tag 1', '* Einweisung\n* Vortrag\n* selbständiges Bearbeiten von Übungen\n* gemeinsame Auswertung \n* IL-Aufgabe'),
(488, '2025-09-30', '* Einweisung in den Tagesablauf; Klärung von offenen Fragen\n* Auswertung der IL-Aufgabe\n* WarmUp-Übung Dienstag\n* Wiederholungsübung\n* Führung eines Inventars\n* Die Bilanz (Aufbau, Merkmale, Bestimmungen § 266 HGB)\n* Übungen Bilanzerstellung', '* KGU: Übung Bilanzerstellung und Ermittlung Eigenkapital (IHK)\n\n* IL: Anwendungsaufgaben zu Themen Tag 1 und 2', '* Einweisung\n* Vortrag\n* selbständiges Bearbeiten von Übungen\n* gemeinsame Auswertung \n* IL-Aufgabe'),
(488, '2025-10-01', '* Einweisung in den Tagesablauf; Klärung von offenen Fragen\n* Auswertung der IL-Aufgabe\n* WarmUp-Übung Mittwoch\n* Wiederholungsübung\n* Bestandskontenkreis in der Finanzbuchhaltung, Führung der Bestandskonten\n* Einfache Geschäftsbuchungen\n* Bilanzveränderungen (4Grundfälle)', '* KGU: Übung Bilanzveränderungen\n\n* IL: Übung Bilanzveränderungen', '* Einweisung\n* Vortrag\n* selbständiges Bearbeiten von Übungen\n* gemeinsame Auswertung \n* IL-Aufgabe');
INSERT INTO `gpb_kurs_tagesbericht` (`kursid`, `tag`, `themen`, `kguil`, `bemerkungen`) VALUES
(488, '2025-10-02', '* Einweisung in den Tagesablauf; Klärung von offenen Fragen\n* Auswertung der IL-Aufgabe\n* WarmUp-Übung Mittwoch\n* Das System der Steuern in der Finanzbuchhaltung (Vor- und Umsatzsteuer)\n* Berechnungen und Buchungen von Steuern\n* Vorsteuerüberhang bzw. Umsatzsteuerzahllast', '* KGU: Geschäftsfälle mit Steuern bearbeiten und Vst-ÜH bzw. Ust-ZL ermitteln\n\n* IL: Geschäftsfälle mit Steuern bearbeiten und Vst-ÜH bzw. Ust-ZL ermitteln', '* Einweisung\n* Vortrag\n* selbständiges Bearbeiten von Übungen\n* gemeinsame Auswertung \n* IL-Aufgabe'),
