(562, '2025-10-20', '8:15 Uhr - 9:00 Uhr: Einweisung in das Modul und den heutigen Tag\n9.00 Uhr - 14:15 Uhr: Bearbeitung der Themen Grundlagen Rechtsordnung, Rechtssubjekte, Rechts- und Geschäftsfähigkeit, Rechtsobjekte\n14:15 Uhr - 15:00 Uhr: Besprechung individueller Fragen\n', 'IL-Aufgaben (moodle Kurs)\nKGU: 8+1', 'Frontalunterricht, Selbstlernphasen, Übungsphasen, Auswertungen'),
(562, '2025-10-21', '08:15 Uhr - 14:15 Uhr: Bearbeitung der Themen Rechtsgeschäfte, Willenserklärungen, Formvorschriften\n14:15 Uhr - 15:00 Uhr: Besprechung individueller Fragen', 'IL-Aufgaben (moodle Kurs)\nKGU: 8+1', 'Frontalunterricht, Selbstlernphasen, Übungsphasen, Auswertungen'),
(562, '2025-10-22', '08:15 Uhr - 14:15 Uhr: Bearbeitung der Themen Anbahnung und Zustandekommen Kaufvertrag\n14:15 Uhr - 15:00 Uhr:  Besprechung individueller Fragen\n', 'IL-Aufgaben (moodle Kurs)\nKGU: 8+1', 'Frontalunterricht, Selbstlernphasen, Übungsphasen, Auswertungen'),
