(557, '2025-10-22', 'Beziehungen von Tabellen, Primärschlüssel/Fremdschlüssel, Datentypen und NULL-Werte bei Fremdschlüsseln, Häufigkeit von Beziehungen 1:n', 'Fragen und Übungen zu Beziehungen und Fremdschlüsseln ', ''),
(557, '2025-10-23', 'Beziehungen von Tabellen, Häufigkeit n:m, Primärschlüssel/Fremdschlüssel, Beziehungstabellen, Primärschlüssel in Beziehungstabellen', 'Fragen und Übungen zu n:m Beziehungen ', ''),
