(557, '2025-10-27', 'Datenbanken planen, Entity Relationship Model (ERM)/-Diagramm (ERD), Entitäten/Relationships/Attribute, Kardinalität von Relationships, Regeln zur Überführung eines ERD in Tabellen', 'Fragen und Übungen zu ERM/ERD ', ''),
(557, '2025-10-28', 'Besprechung der komplexen Übung ERM, kundenorientierte Ergänzungen und Anpassungen, Regeln: wann werden Relationships und Attribute zu Entities, Chen Notation und Krähenfuß Notation', 'IHK Aufgaben zu ERM', ''),
(557, '2025-10-29', 'Besprechung von ERM-IHK-Aufgaben, Prüfung der Fehleranfälligkeit von Tabellen, Redundanzen, Sinn der Normalisierung von Tabellen, 1.- 3. Normalform, Anwendung der Normalformen', 'Fragen und Übungen zu Normalisierung ', ''),
