INSERT INTO `gpb_kurs_tagesbericht` (`kursid`, `tag`, `themen`, `kguil`, `bemerkungen`) VALUES
(543, '2024-11-14', 'Eric Berné (Egogramm) Grundinfos und kurze Einführung in die Transaktionsanalyse - Das Egogramm (Auswertung am Beispiel - die sechs Persönlichkeiten und deren Auswirkungen auf das Miteinander)', 'Individuelle, persönliche Feedbacks auf das Egogramm  ', ''),
(543, '2024-11-15', 'BBB Testlauf - Johari Fenster (Gruppendynamiken und persönlicher Fokus) - Berné und Harris "i am ok - you are ok"', '', ''),
(544, '2024-11-18', 'Introduction.\nDiagnostics test.\nGrammar: Verbs Do, Be, and Have\nGrammar: Present simple, Positive, Negative and Interrogative forms.\nExercises.\nGrammar: Present, Past, and Future chart.\nGrammar: Present tenses.\nPresent tenses exercise.\nDates, times and amounts in US English and British English.\nClass discussion on: Should mobile phones be allowed during class?', 'Written opinion essay on: Should mobile phones be allowed during class? 150 words minimum. Students are encouraged to use MS Word spellcheck when they are finished. ', ''),
(544, '2024-11-19', 'Grammar: Capitalization rules in English.\nCapital letters and full stops exercise.\nReading comprehension essay with multiple choice quiz: Retirement age in Germany.\nGrammar: Genitive form or Possessive.\nExercises.\nUseful phrases in English for writing business letters and emails.\nDifferences in addressing persons in US English and British English.\nBusiness email assignment: Customer complaint.\nGrammar: Past tenses.\nPast tenses exercises.\nGrammar: Demonstrative pronouns - This, that, these and those.\nDemonstrative pronouns exercise.\nClass discussion on: Being competitive.', 'Written opinion essay on: Competition. 150 words minimum. Students are encouraged to use MS Word spellcheck to proof their essays. ', ''),
(544, '2024-11-20', 'Grammar: Pronouns.\nPronouns exercises.\nOther types of pronouns.\nOther types of pronouns exercises.\nReading comprehension essay with multiple choice quiz: Vaping.\nBusiness email assignment: Warranty case.\nGrammar: Prepositions.\nPrepositions exercises.\nGrammar: Articles.\nArticles exercises.\nClass discussion on: Consumerism.', 'Written opinion essay on: What makes people successful? 150 words minimum. Students are encouraged to use MS Word spellcheck to proof their essays.  ', ''),
(544, '2024-11-21', 'Comparative and superlative adjectives.\nExercises.\nGrammar: Modal verbs.\nModal verbs exercises 1 and 2.\nReading comprehension essay with multiple choice quiz: Advantages and disadvantages of immigration.\nBusiness email assignment: Quotation.\nClass discussion on: What makes people successful?\n', 'Written opinion essay on: What makes people successful? 150 words minimum. Students are encouraged to use MS Word spellcheck to proof their essays.  ', ''),
(544, '2024-11-22', 'Grammar: Future tenses.\nFuture tenses exercises.\nMixed tenses exercises.\nReading comprehension essay with multiple choice quiz: Ergonomics in the workplace.\nGrammar: Conjunctions.\nConjunctions exercises.\nPronouns review.\nClass discussion on: Public TV mandatory tax in Germany.\n', '', ''),
(549, '2025-01-06', 'Einstieg in das Modul Wirtschaftskunde;\nBedürfnisse, Bedarf, Nachfrage;\nkurz freie und knappe Güter;\nökonomisches Prinzip;\nWirtschaftseinheiten und ihr Handeln;\n5. Methoden der Bedarfsdeckung\n6. Wirtschaftspolitik mit Stabilitätsgesetz\n', 'Aufgabenstellung zum individuellen Lernen: Güter und Güterarten/Zusatzmaterial und Aufgabenstellungen;\nKGU: Klärung von Fragen\n ', 'Darstellung der Ziele und Schwerpunkte für das Modul. Absprache zur organisatorischen Vorgehensweise.\nEinweisung der Teilnehmer/-innen zum individuellen Lernen;\nLösung von Aufgaben zur Wiederholung und Vertiefung der Inhalte; '),
(549, '2025-01-07', 'Fortsetzung zum Vortag;\nProduktionsfaktoren aus volks- und betriebswirtschaftlicher Sicht; Modell des Wirtschaftskreislaufs; Kombination und Substitution betriebswirtschaftlicher PF;', 'Aufgabenstellung zum individuellen Lernen: Test wirtschaftliche Grundlagen 1;\nKGU: Vertiefung zu Wirtschaftsordnungen/Wirtschaftspolitik und Produktionsfaktoren; ', 'Lösung von Aufgaben zur Wiederholung und Vertiefung der Inhalte; '),
(549, '2025-01-08', 'Markt und Preis; Marktarten nach der Zahl der Marktteilnehmer; Gesetz der Nachfrage und Gesetz des Angebotes; Kriterien des vollkommenen Marktes; Preisbildung am vollkommenen Markt;', 'Aufgabenstellung zum individuellen Lernen: Test wirtschaftliche Grundlagen 2;\nKGU Vertiefung zu Markt und Preis; ', 'Lösung von Aufgaben zur Wiederholung und Vertiefung der Inhalte; '),
(549, '2025-01-09', 'Fortsetzugn zu Punkt 8 und Lösung weiterer Aufgaben;\nStabilitätsgesetz und marktkonforme Maßnahmen des Staates;\n', 'Aufgabenstellung zum individuellen Lernen: Test zum Thema Markt und Preis;\nKGU Vertiefung zu Markt und Preis; ', 'Lösung von Aufgaben zur Wiederholung und Vertiefung der Inhalte;'),
(549, '2025-01-10', 'Übungstag zur Zusammenfassung und Wiederholung der bisherigen Inhalte;', '', ''),
(549, '2025-01-13', 'Krisenprozesse der Wirtschaft, Begriff, Merkmale und Indikatoren;\n', 'Nutzung des Kleingruppenunterrichts zur Klärung von Fragen sowie zur Lösung weiterer Aufgaben entsprechend des Wissensstandes;\nIm individuellen Lernen ist ein Test in Moodle zu lösen.  ', ''),
(549, '2025-01-14', 'EZB Ziele und Aufgaben; Geldpolitisches Instrumentarium;\nBruttoinlandsprodukt, Begriff, real und nominal, Entstehungs-, Verwendungs- und Verteilungsrechnung;\n', 'Im individuellen Lernen sind Aufgaben zur Konjunktur zu lösen.\nNutzung des Kleingruppenunterrichts zur Klärung von Fragen sowie zur Lösung weiterer Aufgaben entsprechend des Wissensstandes; ', ''),
(549, '2025-01-15', 'Nominal- und Reallohn, Kaufkraft des Geldes;\nInflation und Deflation;\nKooperation und Konzentration in der Wirtschaft;', 'Nutzung des Kleingruppenunterrichts zur Klärung von Fragen sowie zur Lösung weiterer Aufgaben entsprechend des Wissensstandes;\nIm individuellen Lernen ist ein Test in Moodle zu lösen.  ', ''),
(549, '2025-01-16', 'Arbeitsteilung international, überbetrieblich und innerbetrieblich;\nZusammenfassung/Wiederholung der Inhalte, Lösung von Aufgaben und Besprechung der Lösungen;', 'Klärung von Fragen sowie zur Lösung weiterer Aufgaben entsprechend des Wissensstandes;\nIm individuellen Lernen sind Aufgaben als Word-Dokument zu lösen und hochzuladen. ', ''),
(549, '2025-01-17', 'Lösung weiterer Aufgaben bzw. individuelle Klausurvorbereitung, Test in Moodle zur Lernerfolgskontrolle;', '', ''),
(550, '2024-12-09', 'Begrüßung der Teilnehmenden\nAnwesenheiten und Vorgaben der IHK\nAufbau der Umschulung/Erstausbildung\nVorstellung der Institutsleitung und des Kundenservice\nVorstellungsrunde Dozent und Teilnehmende\nBelehrungen (Hausordnung, Datenschutz, Arbeits- und Brandschutz)\nRundgang durch das Haus und Brandsammelplatz', '', ''),
(550, '2024-12-10', 'Mathematik-Test (Grundrechenarten, Dreisatz, Prozentrechnung und Bruchrechnung - zur Eigenreflektion mit Auflösung)\nPersönlichkeit - Anteile und Merkmale\nInnere Motivatoren\nRespekt und Umgang miteinander, Vorurteile und deren Überwindung\nStärken und Schwächen, Talente\nWeg der Umschulung und Erstausbildung (IHK-Normen)', '', ''),
(550, '2024-12-11', 'TEAM - Was macht ein Team aus? - Gruppendynamiken, Vorteil für die Gruppe und jeden Einzelnen, Teamstrukturen\nEinführung in Moodle und helpdesk\nÄußere Motivatoren, Zusammenspiel von inneren und äußeren\nPrioritäten - alte und neue Prioritäten\nZiele erfolgreich erreichen (Zielpyramide)\nGoldene Regeln der Erstausbildung, ebenso Umschulung\nFragerunde (Beantwortung von aufgekommenen Fragen)', '', ''),
(550, '2024-12-12', 'Potenziale - Reanimieren und leben\nKommunikation - verbale - horizontale und vertikale, Grundlagen und Fehlerquellen, Absender und Empfänger, Wut und Zorn, Konfliktsituationen, Verhalten am Telefon, Kommunikation im TEAM;\n- nonverbale - Grundlagen und Anzeichen in verschiedenen Situationen, positive Beeinflussung durch die Körpersprache\nLerntypen und Lernmethoden (auditiv, visuell und kinästhetisch)\n', '', ''),
(550, '2024-12-13', 'Einführung in One Drive und Microsoft Office 365\nFeedbackrunde zwischen den Teilnehmenden und Dozenten\nAbschlussmotivation durch den Dozenten\nWillkommensessen im "Tapas y mas"', '', ''),
(28, '2024-12-16', 'Einführung Betriebliche Kommunikation\nGruppenarbeit: Erarbeitung und Vorstellung einer Firmenkommunikation aus eigener Erfahrung\nSkript Kommunikationsmodelle\nBeginn der Projektarbeit: Brainstorming\n', 'Projekt: Externe und interne Kommunikation einer Firma ', ''),
