(573, '2025-10-30', 'Kommunikationspolitik\nZiele, Gestaltung der Werbung, AIDA-Formel, Grundsätze\nInhalte Werbeplan\nÖffentlichkeitsarbeit\nSponsoring und weitere Kommunikationsinstrumente\n', 'IL: Übung Werbeplan, Lösen der Aufgaben 3-6 und 8-10, Band 2, Seiten 165/166\nKGA: Gemeinsame Klärung von Fragen zur Kommunikationspolitik, Verkaufsförderung \n', 'individuelle Konsultation\nAuswertungen und Zusammenfassung\nAuswertung der IL-Aufgaben\n'),
(573, '2025-10-31', 'Wettbewerbsrechtliche Grenzen durch die Einhaltung des Gesetzes gegen den unlauteren Wettbewerb\nAufgaben 1, 3-5 und 7-9, Band 2, Seiten 166-175 \n(aus Zeitgründen informativ)\nWeiterführung der Inhalte zur Kommunikationspolitik', 'nein', 'individuelle Konsultation\nAuswertungen und Zusammenfassung \nAuswertung der IL-Aufgaben\n'),
(573, '2025-11-03', 'Distributionspolitik\nAbsatzwege\nOnline-Marketing\nInfluenser-Marketing\nVergleich Handelsvertreter und Reisender\n', 'IL: Kostenvergleich Handelsvertreter und Reisender, \n4 Aufgaben\nKGA: Klärung von Fragen zur den Distributionsorganen', 'individuelle Konsultation\nAuswertungen und Zusammenfassung \n'),
