INSERT INTO `gpb_kurs_tagesbericht` (`kursid`, `tag`, `themen`, `kguil`, `bemerkungen`) VALUES
(1192, '2026-03-26', 's.o \n\nWiederholung Grundrechte', 'WDH', ''),
(1192, '2026-03-27', 'Bundesorgane Art 38-66 GG\nGestzgebung Art 70 ff KK', '', ''),
(1070, '2026-03-02', 'Kapitel 1 – Grundlagen zu Programmen und Programmiersprachen (inkl. EVA-Prinzip, Sprachklassifikationen; Überblick aus „Bevor Sie beginnen“)\nKapitel 2 – Darstellungsmittel für Programmabläufe (PAP, DFD, Struktogramme, Pseudocode, Entscheidungstabellen, UML) + Kapitel 3 – Werkzeuge der Softwareentwicklung (Überblick)\n', 'Begriffsklärung und Beispiele zu Algorithmus ↔ Programm; Einordnung von Sprachgenerationen/-typen; gemeinsame Besprechung der Abschnitte 1.1–1.11.\nGemeinsames Erarbeiten der Notationen (PAP, Struktogramm, ET) und ihrer Einsatzzwecke; kurzer Rundgang durch Editor/IDE/Übersetzungskonzepte.\nSchrittweises Durchgehen: Projekt/Klasse in Eclipse anlegen; Compiler/Interpreter-Abläufe vergleichen.\nÜbungen Kap. 1 (1.12) bearbeiten (Fragen zu Datenverarbeitung/Sprachen).\nKap. 2 – Übung (2.8): Struktogramm & Entscheidungstabelle. Kap. 3: Lesen 3.1–3.3/3.5–3.6 (Grundaufbau, Kompilieren/Ausführen).\n', ''),
(1070, '2026-03-03', 'Kapitel 3 – Werkzeuge (vertieft: IDE, Java/Eclipse-Beispiel, Skripte)\nKapitel 4 – Zahlensysteme und Zeichencodes (Dezimal/Dual/Hex, Bits & Bytes, ASCII/Unicode)\n', 'Rechenwege (Umrechnungen, Paritätsbit), Zeichencodes (ASCII → Unicode) im Plenum; kurze Rechenrunden in Kleingruppen.\nÜbungen Kap. 3 (3.9); z. B. einfaches Ausgabebeispiel kompilieren/ausführen.\nÜbungen Kap. 4 (4.5): Umrechnungen, Add./Subtr. im Dualsystem, Byte-Größen. \n', ''),
(1070, '2026-03-04', 'Kapitel 5 – Grundlegende Sprachelemente (Syntax/Semantik, EBNF/Syntaxdiagramme, Datentypen, Variablen/Konstanten, Operatoren/Ausdrücke)\n\n', 'Gemeinsame Klärung der Syntax-Schreibweisen (EBNF), Datentypüberblick und typische Operatoren/Ausdrücke.\nÜbungen Kap. 5 (5.8) (nach Lektüre 5.1–5.7).\n', ''),
(1070, '2026-03-05', 'Kapitel 6 – Kontrollstrukturen (Bedingungen, Verzweigungen inkl. switch, Schleifen: for/while/do-while; Übersicht)\nKapitel 7 – Elementare Datenstrukturen (Arrays 1D/2D, Zeichenketten/Records, Zeiger/Referenzen)', 'Beispiele zu If/Switch und zu zähler-/kopf-/fußgesteuerten Schleifen; Besprechung typischer Stolpersteine.\nArray-Zugriffsmuster, Indexierung (0-basiert), Record/Referenz-Gedankenmodell; Einsatzszenarien.\nÜbungen Kap. 6 (6.13); u. a. kleine Aufgaben zu Verzweigungen/Schleifen.\nÜbungen Kap. 7 (7.7): Suche in Array, 2D-Aufgaben, Sieb des Eratosthenes.\n', ''),
(1070, '2026-03-06', 'Kapitel 8 – Methoden, Prozeduren und Funktionen (Unterprogramme, Parameterübergabe by value/by reference, Rückgabewerte)\nKapitel 9 – Einführung in die OOP (Klassen/Objekte, Attribute/Methoden, Konstruktoren, Vererbung, Polymorphie)\nKapitel 10 – Algorithmen (iterativ/rekursiv, generisch) + Kapitel 11 – Spezielle Algorithmen (Suche/Sortieren, Dateien) + Kapitel 12 – Grundlagen der Softwareentwicklung (Lebenszyklus, Vorgehensmodelle, CASE, Qualitätskriterien) – Überblick & Anwendung', 'Signaturen/Parameterlisten, Aufruf-/Abarbeitungslogik; Vergleich Prozedur vs. Funktion.\nOOP-Kernprinzipien (Datenkapselung, Vererbung, Polymorphie) anhand der Kapitelstruktur; kleine Klassendesigns in Gruppen.\nVergleich Iteration vs. Rekursion; Sortier-/Suchideen und Dateizugriff besprechen; Software-Lebenszyklus & Modelle (Wasserfall/Spirale/Agil) im Überblick.\nÜbungen Kap. 8 (8.6): kleine Methoden/Parameter-Aufgaben (inkl. Min/Power).\nÜbungen Kap. 9 (9.12): Klassenstruktur entwerfen; kleines Vererbungs/Polymorphie-Beispiel (Rectangle/Cuboid/Pyramid).\nÜbungen Kap. 10 (10.6) und Kap. 11 (11.11) (z. B. GGT, KingChess, Messwerte sortieren); optional Kurzlektüre Kap. 12 (12.8 Übung).', ''),
(1070, '2026-03-09', 'Wiederholung Kapitel 6–8 (Kontrollstrukturen, Arrays/elementare Datenstrukturen, Unterprogramme)', 'Gemeinsames Lösen ausgewählter Übungen zu Kap. 6 (Verzweigungen, Schleifen) und Kap. 7 (Array-Zugriffe) aus dem Skript; Lösungsideen vergleichen; typische Fehler (Off-by-one, Abbruchbedingung, Indexbereich) besprechen.\nRestliche Übungen zu Kap. 6–7 aus dem Skript fertig bearbeiten; danach Übungen zu Kap. 8 (Parameter, Rückgabewert) selbstständig lösen und mit KGU-Lösungsweg abgleichen.', ''),
(1070, '2026-03-10', 'Objektorientierung festigen – Kapitel 9', 'In Gruppen eine oder zwei der Übungen zu Kap. 9 (Klassenmodell, Attribute/Methoden, ggf. einfache Vererbung) gemeinsam modellieren; Klassendiagramm bzw. Strukturskizze an der Tafel entwickeln; Musterlösung aus Skript besprechen.', ''),
(1070, '2026-03-11', 'Objektorientierung festigen – Kapitel 9', 'Übrige Übungen zu Kap. 9 aus dem Skript selbstständig durchrechnen/implementieren; besonders auf Zugriffsrechte, Konstruktoraufrufe und Methodenaufrufe achten; kurze schriftliche Reflexion: „Welche Teile des Klassendiagramms waren direkt aus der Aufgabenstellung ableitbar?“', ''),
(1070, '2026-03-12', 'Algorithmen & spezielle Verfahren – Kapitel 10 und 11', 'Beispielalgorithmus aus Kap. 10 (iterativ ↔ rekursiv) im Detail durchgehen; anschließend eine oder zwei Übungen zu Kap. 11 (laut Skript – z. B. Suchen/Sortieren/Dateien, so wie dort vorgegeben) gemeinsam lösen und Laufzeit/Schrittfolge diskutieren. Fokus: „Wie komme ich von der Problemformulierung im Skript zur Kontrollstruktur?“\nAlle restlichen Übungen zu Kap. 10 und die noch offenen Übungen zu Kap. 11 aus dem Skript bearbeiten; dabei Variante „mit/ohne Hilfsstruktur“ vergleichen; eigene Tests/Vergleichsein- und -ausgaben anlegen (nach Vorgaben im Skript).', ''),
(1070, '2026-03-13', 'Abschluss & Softwareentwicklung – Kapitel 12 + Aufräumen offener Übungen', '', ''),
(1209, '2026-03-23', 'Vorstellung des Projekts: Erstellung von 4 Demoreels (Trennung, Geschwister, Klopfen vs. Klingeln, Hexenkessel)\nZiel: Entwicklung von insgesamt 10 Schnittfassungen \nMaterialverteilung\nErstellung des Proxy-Workflows\nEinführung in Arbeitsstruktur und Zeitplanung (14 Tage)\nBeginn der Erstellung individueller Postproduktionspläne', 'KGU, IL', ''),
(1209, '2026-03-24', 'Fertigstellung und Abstimmung der Postproduktionspläne\nFestlegung von Schnittprioritäten und Variantenideen\nÜbersicht zur Verteilung der Schnittfassungen innerhalb der Gruppe\nSynchronisation\nSichtung des Rohmaterials und erste inhaltliche Einordnung\nErste Rohschnitt-Ansätze einzelner Szenen\nKlärung technischer Workflows (Projektstruktur, Organisation)', 'KGU, IL', ''),
(1209, '2026-03-25', 'Beginn des systematischen Rohschnitts an den Demoreels\nFokus auf inhaltliche Klarheit und Szenenstruktur\nErste Unterschiede zwischen Varianten werden erarbeitet\nIndividuelle Betreuung bei Schnittentscheidungen\nAustausch innerhalb der Gruppe zu Ansätzen und Lösungen', 'KGU, IL', ''),
(1209, '2026-03-26', 'Weiterarbeit an den Schnittfassungen\nErste Feedbackrunde mit Dozentin\nAnalyse von Rhythmus, Timing und Figurenwirkung\nAnpassung der Schnitte auf Basis des Feedbacks\nZiel: klare Differenzierung zwischen den Varianten', 'KGU, IL', ''),
(1209, '2026-03-27', 'Weiterentwicklung der Schnittfassungen (Feinschnitt-Ansätze)\nVorbereitung auf Feedback mit Schauspielern\nFokus auf Wirkung der Szenen (Casting-Relevanz)\nReflexion: Welche Version funktioniert für welchen Zweck?\nOptimierung von Schnittentscheidungen und Dramaturgie', 'KGU, IL', ''),
(1214, '2026-03-23', '[! Vorsicht, werte Kollegen: beim Zwischenspeichern, Mittwoch fertig, alles weg - was soll das? Back-Button kann evtl helfen; zur Sicherheit strg+c der Einzelfelder ...; jedoch: weswegen ist, zumid. dieses, so nachlässig programmiert?]\n\nModulvorstellung und -abstimmung, Einordnungen\nPersönlkR u RaeB, nebst schematischer Darstellg,\nStart UrhR (Zweck, ..., Grdl, ...), § 2 II knapp\nSchutzobj UrhR\nverwandte SchutzRe\n§§ 2-6 UrhR, Einzelanwendgn', 'Fragen, Vertiefg; IK: vgl. IL-Kurs; einige Zusatzthemen ', '[! Vorsicht, werte Kollegen: beim Zwischenspeichern, Mittwoch fertig, alles weg - was soll das? Back-Button kann evtl helfen; zur Sicherheit strg+c der Einzelfelder ...; jedoch: weswegen ist, zumid. dieses, so nachlässig programmiert?]\n\nbitte die det. Verlaufsnotierungen in der "Verlaufsseite" zum je gegenständlichen Datum im IL-Kurs beachten, iü BBB-spezifizierte Darstellungs- und Darreichungsformen, je mit ausgewerteten Ergebnissen; insbes. Voice-Chat als Präsenzelement  '),
