(1189, '2026-03-27', 'Wdhlg. vom Vortag - Auswertung IL-Aufgabe - Wdhlg. Flächenteilung in der Perspektive V - Flächenteilungen in der Perspektive kombinieren und selbstständig anwenden V  - diverse Übungen', 'Abschlussaufgabe (2 h)', 'online via BBB\nInteraktiver Frontalunterricht\npraktische Selbstlernphase (IL-Aufgabe)'),
(1079, '2026-03-02', 'Grundlagen der Buchführung, Inventur - Inventar - Bilanz, Aktiva und Passiva, Bestandskonten und ihre zu- und Abgänge, Berechnung des Saldos / Schlussbestandes, Beispiele von der Eröffnungs- zur Schlussbilanz', 'IL-Aufgabe ist ein Test in der Lernplattform Moodle;', 'Einführung zum Modul; Erläuterung der Ziele und Schwerpunkte; \nPhasen des Frontalunterrichts lösen sich mit der selbständigen Erarbeitung von Inhalten ab; Lösung von Aufgaben in Gruppen- und Einzelarbeit und deren Auswertung;'),
(1079, '2026-03-03', 'weiter Bestandskonten, Umsetzung von Geschäftsfällen, Buchungssätze / Führen de Grundbuches, EBK und SBK', 'IL-Aufgabe ist ein Test in der Lernplattform Moodle;', 'Phasen des Frontalunterrichts lösen sich mit der selbständigen Erarbeitung von Inhalten ab; Lösung von Aufgaben in Gruppen- und Einzelarbeit und deren Auswertung;'),
(1079, '2026-03-04', 'Erfolgskonten als Unterkonten des Eigenkapitals; Zusammenfassung der Erfolgskonten im Gewinn- und Verlustkonto und Übertrag des GuV-Saldos ins Eigenkapital; Beispiele vom EBK zum SBK', 'IL-Aufgabe ist ein Test in der Lernplattform Moodle;', 'Phasen des Frontalunterrichts lösen sich mit der selbständigen Erarbeitung von Inhalten ab; Lösung von Aufgaben in Gruppen- und Einzelarbeit und deren Auswertung;'),
(1079, '2026-03-05', 'Spezifik des Umgangs mit Waren im Handel - Einführung der Erfolgskonten Wareneingang und Warenverkauf, Ermittlung der Bestandsveränderung im Warenbestand, Beispiele', 'IL-Aufgabe ist ein Test in der Lernplattform Moodle;', 'Phasen des Frontalunterrichts lösen sich mit der selbständigen Erarbeitung von Inhalten ab; Lösung von Aufgaben in Gruppen- und Einzelarbeit und deren Auswertung;'),
(1079, '2026-03-06', 'weitere Beispielaufgaben zur Buchung auf Bestands- und Erfolgskonten inkl. Warenkonten', '', ''),
(1079, '2026-03-09', 'Aufgaben zur Erarbeitung von Buchungssätzen zum Bestands- und Erfolgskontenkreis;\nDie Umsatzsteuer im Unternehmen.', 'IL-Aufgabe ist ein Test in der Lernplattform Moodle;', 'Phasen des Frontalunterrichts lösen sich mit der selbständigen Erarbeitung von Inhalten ab; Lösung von Aufgaben in Gruppen- und Einzelarbeit und deren Auswertung;'),
(1079, '2026-03-10', 'Fortsetzung zum Thema Umsatzsteuer und Lösung einer Vielzahl von Aufgaben;', 'IL-Aufgabe ist ein Test in der Lernplattform Moodle;', 'Phasen des Frontalunterrichts lösen sich mit der selbständigen Erarbeitung von Inhalten ab; Lösung von Aufgaben in Gruppen- und Einzelarbeit und deren Auswertung;'),
(1079, '2026-03-11', 'Abschreibung auf Sachanlagen, Methoden sowie Berechnung von Abschreibungssätzen und Abschreibungsbeträgen;', 'IL-Aufgabe ist ein Test in der Lernplattform Moodle;', 'Phasen des Frontalunterrichts lösen sich mit der selbständigen Erarbeitung von Inhalten ab; Lösung von Aufgaben in Gruppen- und Einzelarbeit und deren Auswertung;'),
(1079, '2026-03-12', 'Fortsetzung zum Thema Abschreibung, insbesondere mit Abschreibung von GWG;', 'IL-Aufgabe ist ein Test in der Lernplattform Moodle;', 'Phasen des Frontalunterrichts lösen sich mit der selbständigen Erarbeitung von Inhalten ab; Lösung von Aufgaben in Gruppen- und Einzelarbeit und deren Auswertung;'),
