--
-- Struktur des Views `gpb_klasse_view`
--
DROP TABLE IF EXISTS `gpb_klasse_view`;

CREATE ALGORITHM=UNDEFINED DEFINER=`web32`@`localhost` SQL SECURITY DEFINER VIEW `gpb_klasse_view` AS select `k`.`id` AS `id`,`k`.`mitisid` AS `mitisid`,`k`.`bezeichnung` AS `bezeichnung`,`k`.`beginn` AS `beginn`,`k`.`ende` AS `ende`,`k`.`ort` AS `ort`,`k`.`moodleid` AS `moodleid`,`k`.`berufid` AS `berufid`,`b`.`familieid` AS `familieid`,concat(`f`.`kuerzel`,concat(' / ',`b`.`kuerzel`)) AS `berufkuerzel`,(select count(distinct `ktn`.`tnid`) from `gpb_klasse_tn` `ktn` where `ktn`.`klasseid` = `k`.`id` and `ktn`.`einstieg` <> '0000-00-00') AS `anzahlTN`,(select count(distinct `ktn`.`tnid`) from `gpb_klasse_tn` `ktn` where `ktn`.`klasseid` = `k`.`id`) AS `anzahlAnmeldungen` from ((`gpb_klasse` `k` left join `gpb_beruf` `b` on(`b`.`id` = `k`.`berufid`)) left join `gpb_berufsfamilie` `f` on(`f`.`id` = `b`.`familieid`));

-- --------------------------------------------------------

--
-- Struktur des Views `gpb_kurs_view`
--
DROP TABLE IF EXISTS `gpb_kurs_view`;

CREATE ALGORITHM=UNDEFINED DEFINER=`web32`@`localhost` SQL SECURITY DEFINER VIEW `gpb_kurs_view` AS select `k`.`id` AS `id`,`k`.`titel` AS `titel`,`k`.`beginn` AS `beginn`,`k`.`ende` AS `ende`,`k`.`raumid` AS `raumid`,`k`.`kurzbericht_ok` AS `kurzbericht_ok`,`k`.`tagesbericht_ok` AS `tagesbericht_ok`,`k`.`moodleid` AS `moodleid`,`k`.`modulid` AS `modulid`,`k`.`notenstatus` AS `notenstatus`,`k`.`notenerklaerung` AS `notenerklaerung`,`k`.`bewertungoffen` AS `bewertungoffen`,`k`.`planungnotiz` AS `planungnotiz`,`k`.`planungfarbe` AS `planungfarbe`,`k`.`zeugnisrelevant` AS `zeugnisrelevant`,`k`.`zeugnisgewichtung` AS `zeugnisgewichtung`,`k`.`einzeltage` AS `einzeltage`,`k`.`sichtbar` AS `sichtbar`,`k`.`mini` AS `mini`,`m`.`titel` AS `modultitel`,`m`.`kuerzel` AS `modulkuerzel`,`m`.`dauer` AS `moduldauer`,`r`.`ort` AS `ort`,`r`.`tuer` AS `raum`,ifnull(`r`.`anzahlPlaetze`,-1) AS `anzahlPlaetze`,exists(select 1 from `gpb_pruefungsvorbereitung` where `gpb_pruefungsvorbereitung`.`kursid` = `k`.`id` limit 1) AS `istPV`,exists(select 1 from `gpb_ihkprojektantragsformular` where `gpb_ihkprojektantragsformular`.`kursid` = `k`.`id` limit 1) AS `hatProjektantrag`,exists(select 1 from `gpb_ihkprojektantrag` where `gpb_ihkprojektantrag`.`kursid` = `k`.`id` limit 1) AS `hatProjektantragDaten` from ((`gpb_kurs` `k` left join `gpb_modul` `m` on(`m`.`id` = `k`.`modulid`)) left join `gpb_raum` `r` on(`r`.`id` = `k`.`raumid`));

-- --------------------------------------------------------

--
-- Struktur des Views `gpb_massnahme_view`
--
DROP TABLE IF EXISTS `gpb_massnahme_view`;

CREATE ALGORITHM=UNDEFINED DEFINER=`web32`@`localhost` SQL SECURITY DEFINER VIEW `gpb_massnahme_view` AS select `m`.`id` AS `id`,`m`.`mitisid` AS `mitisid`,`m`.`titel` AS `titel`,`m`.`kuerzel` AS `kuerzel`,`m`.`berufid` AS `berufid`,`m`.`beginn` AS `beginn`,`m`.`ende` AS `ende`,`b`.`familieid` AS `familieid`,concat(`f`.`kuerzel`,concat(' / ',`b`.`kuerzel`)) AS `berufkuerzel`,(select count(distinct `mtn`.`tnid`) from `gpb_massnahme_tn` `mtn` where `mtn`.`massnahmeid` = `m`.`id` and `mtn`.`einstieg` <> '0000-00-00') AS `anzahlTN`,(select count(distinct `mtn`.`tnid`) from `gpb_massnahme_tn` `mtn` where `mtn`.`massnahmeid` = `m`.`id`) AS `anzahlAnmeldungen` from ((`gpb_massnahme` `m` left join `gpb_beruf` `b` on(`b`.`id` = `m`.`berufid`)) left join `gpb_berufsfamilie` `f` on(`f`.`id` = `b`.`familieid`));

-- --------------------------------------------------------

--
-- Struktur des Views `gpb_selfkurs_view`
--
DROP TABLE IF EXISTS `gpb_selfkurs_view`;

CREATE ALGORITHM=UNDEFINED DEFINER=`web32`@`localhost` SQL SECURITY DEFINER VIEW `gpb_selfkurs_view` AS select `sk`.`id` AS `id`,`sk`.`titel` AS `titel`,`sk`.`moodleid` AS `moodleid`,(select count(0) from `gpb_selfkurs_tn` `sktn` where `sktn`.`selfkursid` = `sk`.`id`) AS `anzahlTN` from `gpb_selfkurs` `sk`;

-- --------------------------------------------------------

--
-- Struktur des Views `gpb_tn_view`
--
DROP TABLE IF EXISTS `gpb_tn_view`;

CREATE ALGORITHM=UNDEFINED DEFINER=`web32`@`localhost` SQL SECURITY DEFINER VIEW `gpb_tn_view` AS select `tn`.`id` AS `id`,`tn`.`mitisid` AS `mitisid`,`tn`.`mitisanrede` AS `mitisanrede`,`tn`.`mitisvorname` AS `mitisvorname`,`tn`.`anrede` AS `anrede`,`tn`.`vorname` AS `vorname`,`tn`.`nachname` AS `nachname`,`tn`.`geburtsdatum` AS `geburtsdatum`,`tn`.`email` AS `email`,`tn`.`berufid` AS `berufid`,`tn`.`nutzername` AS `nutzername`,`tn`.`passwort` AS `passwort`,`tn`.`moodleid` AS `moodleid`,`tn`.`berichtsheft_offen` AS `berichtsheft_offen`,concat(`tn`.`vorname`,concat(' ',`tn`.`nachname`)) AS `tnname`,concat(`f`.`kuerzel`,concat(' / ',`b`.`kuerzel`)) AS `berufkuerzel` from ((`gpb_tn` `tn` left join `gpb_beruf` `b` on(`b`.`id` = `tn`.`berufid`)) left join `gpb_berufsfamilie` `f` on(`f`.`id` = `b`.`familieid`));
